@import url("/fonts/diagnostic/google-fonts.css");
@import url("https://be.cdn.yclients.com/css/open_sans.css");
@import url("https://be.cdn.yclients.com/css/roboto.css");
@import url("https://be.cdn.yclients.com/css/inter.css");
@import url("https://be.cdn.yclients.com/css/p.backoffice.ac3e2b95271a0a9255bbdda25b38d5af.css");
@import url("https://be.cdn.yclients.com/css/p.backoffice-yclients.1e56cbfff03de9dea19500aeb34f2a45.css");
@import url("https://be.cdn.yclients.com/css/p.redesign.fb84f2a1f4578690cd84bcb85255e260.css");
@import url("https://be.cdn.yclients.com/css/p.light-redesign-deprecated.d79e41181df1c9dfa777b0d782aa23ef.css");
@import url("https://be.cdn.yclients.com/css/p.header-redesign.701aa1f7f2d8042747a370ae0ed6f1c9.css");
@import "tailwindcss";

:root {
  --background: #fbfcff;
  --foreground: #2b3134;
}

.eco-product-analytics-page {
  width: 100%;
}

.eco-pa-shell {
  display: grid;
  gap: 18px;
  font-family: Inter, "Open Sans", Roboto, Arial, sans-serif;
  letter-spacing: 0;
}

.eco-pa-head {
  align-items: flex-start;
}

.eco-pa-head .eco-actions {
  justify-content: flex-end;
}

.eco-pa-filters {
  display: grid;
  gap: 14px;
}

.eco-pa-filter-head {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-pa-filter-head span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-pa-filter-grid {
  display: grid;
  grid-template-columns: repeat(9, minmax(120px, 1fr));
  gap: 10px;
}

.eco-pa-switches {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.eco-pa-check {
  display: inline-flex;
  min-height: 32px;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  background: var(--eco-surface);
  padding: 0 10px;
  color: var(--eco-ink-2);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.eco-pa-check input {
  width: 15px;
  height: 15px;
  accent-color: var(--eco-rust);
}

.eco-pa-alert,
.eco-pa-loading,
.eco-pa-empty {
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid #fde68a;
  border-radius: 6px;
  background: #fffbeb;
  padding: 12px 14px;
  color: #92400e;
  font-size: 13px;
  font-weight: 650;
}

.eco-pa-alert.is-success {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}

.eco-pa-loading,
.eco-pa-empty {
  justify-content: center;
  min-height: 130px;
  border-color: var(--eco-line);
  background: var(--eco-surface);
  color: var(--eco-muted);
}

.eco-pa-tabs {
  margin-bottom: 0;
}

.eco-pa-stack {
  display: grid;
  gap: 16px;
}

.eco-pa-kpis,
.eco-pa-new-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.eco-pa-section {
  padding: 0;
  overflow: hidden;
}

.eco-pa-section > .eco-card__head {
  margin: -18px -18px 14px;
}

.eco-pa-two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.eco-pa-table-wrap .eco-table {
  min-width: 1120px;
}

.eco-pa-product-title {
  display: grid;
  min-width: 260px;
  gap: 3px;
}

.eco-pa-product-title a {
  color: var(--eco-ink);
  font-weight: 800;
  line-height: 1.25;
  text-decoration: none;
}

.eco-pa-product-title a:hover {
  color: var(--eco-rust);
}

.eco-pa-product-title small {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-pa-row-actions {
  min-width: 76px;
  opacity: 1;
}

.eco-pa-quality-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.eco-pa-quality-item {
  display: grid;
  gap: 8px;
  min-height: 132px;
  align-content: flex-start;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface-sunk);
  padding: 12px;
}

.eco-pa-quality-item strong {
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-pa-quality-item span,
.eco-pa-matrix-cell small,
.eco-pa-matrix-cell em,
.eco-pa-export-item small {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
}

.eco-pa-matrix {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-pa-matrix-cell {
  display: grid;
  gap: 7px;
  min-height: 150px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface);
  padding: 13px;
}

.eco-pa-matrix-cell strong {
  color: var(--eco-ink);
  font-size: 22px;
  line-height: 1;
}

.eco-pa-matrix-cell span {
  color: var(--eco-ink-2);
  font-weight: 800;
}

.eco-pa-matrix-cell em {
  font-style: normal;
}

.eco-pa-matrix-cell.is-ax {
  border-color: #bbf7d0;
  background: #f0fdf4;
}

.eco-pa-matrix-cell.is-az,
.eco-pa-matrix-cell.is-bz,
.eco-pa-matrix-cell.is-cz {
  border-color: #fde68a;
  background: #fffbeb;
}

.eco-pa-export-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-pa-export-item {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 24px;
  align-items: center;
  gap: 10px;
  min-height: 72px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface);
  padding: 12px;
  color: var(--eco-ink);
  text-align: left;
}

.eco-pa-export-item:hover {
  border-color: var(--eco-line-strong);
  background: var(--eco-hover);
}

.eco-pa-export-item span {
  display: grid;
  gap: 3px;
}

.is-spin {
  animation: eco-spin 0.9s linear infinite;
}

@media (max-width: 1280px) {
  .eco-pa-filter-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .eco-pa-kpis,
  .eco-pa-new-summary,
  .eco-pa-quality-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .eco-pa-head,
  .eco-pa-head .eco-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-pa-head .eco-btn,
  .eco-pa-head .eco-badge {
    width: 100%;
  }

  .eco-pa-filter-grid,
  .eco-pa-kpis,
  .eco-pa-new-summary,
  .eco-pa-quality-grid,
  .eco-pa-matrix,
  .eco-pa-export-grid,
  .eco-pa-two-col {
    grid-template-columns: 1fr;
  }

  .eco-pa-switches .eco-btn {
    width: 100%;
  }
}

.eco-product-export-menu {
  position: relative;
  display: inline-flex;
}

.eco-product-export-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 80;
  min-width: 240px;
  overflow: hidden;
  border: 1px solid var(--eco-border);
  border-radius: 8px;
  background: var(--eco-surface);
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.18);
}

.eco-product-export-popover button {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: flex-start;
  border: 0;
  background: transparent;
  padding: 10px 12px;
  color: var(--eco-ink);
  font-size: 14px;
  text-align: left;
}

.eco-product-export-popover button:hover {
  background: var(--eco-soft);
}

.eco-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 95;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.48);
  padding: 24px;
}

.eco-modal {
  width: min(1180px, calc(100vw - 32px));
  max-height: calc(100vh - 48px);
  overflow: hidden;
  border: 1px solid var(--eco-border);
  border-radius: 8px;
  background: var(--eco-surface);
  box-shadow: 0 24px 72px rgba(15, 23, 42, 0.24);
}

.eco-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid var(--eco-border);
  padding: 18px 20px;
}

.eco-modal-head h3 {
  margin: 2px 0 0;
  font-size: 22px;
  font-weight: 750;
}

.eco-contact-action-button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid rgba(29, 78, 216, 0.22);
  border-radius: 8px;
  background: #eff6ff;
  color: #1d4ed8;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
}

.eco-contact-action-button:hover {
  background: #dbeafe;
  border-color: rgba(29, 78, 216, 0.34);
}

.eco-contact-action-button.is-sm {
  min-height: 28px;
  padding: 0 9px;
  font-size: 12px;
}

.eco-contact-action-button.is-icon {
  width: 32px;
  min-height: 32px;
  padding: 0;
}

.eco-contact-action-button.is-link {
  min-height: 0;
  border: 0;
  background: transparent;
  padding: 0;
}

.eco-contact-action-backdrop {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 18px;
}

.eco-contact-action-panel {
  width: min(520px, calc(100vw - 28px));
  max-height: calc(100vh - 28px);
  overflow: auto;
  border: 1px solid var(--eco-border, #e2e8f0);
  border-radius: 8px;
  background: var(--eco-surface, #fff);
  box-shadow: 0 26px 76px rgba(15, 23, 42, 0.25);
}

.eco-contact-action-panel header,
.eco-contact-action-panel footer {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 16px;
}

.eco-contact-action-panel header {
  border-bottom: 1px solid var(--eco-border, #e2e8f0);
}

.eco-contact-action-panel header p,
.eco-contact-action-panel header h3,
.eco-contact-action-panel header span {
  margin: 0;
}

.eco-contact-action-panel header p {
  color: var(--eco-muted-ink, #64748b);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.eco-contact-action-panel header h3 {
  margin-top: 3px;
  color: var(--eco-ink, #0f172a);
  font-size: 21px;
  font-weight: 800;
  line-height: 1.18;
}

.eco-contact-action-panel header span {
  display: block;
  margin-top: 5px;
  color: var(--eco-muted-ink, #64748b);
  font-size: 13px;
}

.eco-contact-action-icon {
  display: inline-flex;
  width: 34px;
  height: 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--eco-border, #e2e8f0);
  border-radius: 8px;
  background: #fff;
  color: #334155;
  cursor: pointer;
}

.eco-contact-action-status,
.eco-contact-action-alert {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 14px 16px 0;
  border-radius: 8px;
  padding: 10px 11px;
  font-size: 13px;
}

.eco-contact-action-status {
  border: 1px solid #bfdbfe;
  background: #eff6ff;
  color: #1e40af;
}

.eco-contact-action-alert.is-error {
  border: 1px solid rgba(220, 38, 38, 0.28);
  background: #fef2f2;
  color: #991b1b;
}

.eco-contact-action-alert.is-success {
  border: 1px solid rgba(22, 163, 74, 0.26);
  background: #f0fdf4;
  color: #166534;
}

.eco-contact-action-grid,
.eco-contact-action-templates {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 14px 16px 0;
}

.eco-contact-action-grid button,
.eco-contact-action-grid a,
.eco-contact-action-wide,
.eco-contact-action-panel footer button {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--eco-border, #e2e8f0);
  border-radius: 8px;
  background: #fff;
  color: #0f172a;
  padding: 0 11px;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.eco-contact-action-grid button:disabled,
.eco-contact-action-grid a[aria-disabled="true"],
.eco-contact-action-panel footer button:disabled {
  opacity: 0.5;
  pointer-events: none;
}

.eco-contact-action-wide {
  margin: 14px 16px 0;
  width: calc(100% - 32px);
  border-color: rgba(29, 78, 216, 0.24);
  background: #eff6ff;
  color: #1d4ed8;
}

.eco-contact-action-templates button {
  border: 1px solid var(--eco-border, #e2e8f0);
  border-radius: 8px;
  background: #fff;
  color: #334155;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.eco-contact-action-templates button.is-active {
  border-color: rgba(29, 78, 216, 0.34);
  background: #dbeafe;
  color: #1d4ed8;
}

.eco-contact-action-message {
  display: grid;
  gap: 7px;
  padding: 14px 16px 0;
}

.eco-contact-action-message span {
  color: var(--eco-muted-ink, #64748b);
  font-size: 12px;
  font-weight: 700;
}

.eco-contact-action-message textarea {
  width: 100%;
  resize: vertical;
  border: 1px solid var(--eco-border, #e2e8f0);
  border-radius: 8px;
  padding: 10px 11px;
  color: #0f172a;
  font: inherit;
}

.eco-contact-action-panel footer {
  justify-content: flex-end;
  padding-top: 14px;
}

.eco-contact-action-panel footer .is-primary {
  border-color: #1d4ed8;
  background: #2563eb;
  color: #fff;
}

.eco-contact-action-panel footer .is-secondary {
  background: #f8fafc;
}

.eco-contact-action-panel .is-spin {
  animation: eco-contact-spin 0.9s linear infinite;
}

.eco-client-contact-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

@keyframes eco-contact-spin {
  to {
    transform: rotate(360deg);
  }
}

.eco-product-import-grid {
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(0, 1fr);
  min-height: 560px;
}

.eco-product-import-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  border-right: 1px solid var(--eco-border);
  padding: 18px;
  background: var(--eco-muted);
}

.eco-toggle-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  color: var(--eco-ink);
}

.eco-product-import-actions,
.eco-product-import-footer,
.eco-product-import-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.eco-product-import-preview {
  min-width: 0;
  overflow: auto;
  padding: 18px;
}

.eco-product-import-summary {
  display: grid;
  grid-template-columns: repeat(6, minmax(96px, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.eco-product-import-summary span {
  border: 1px solid var(--eco-border);
  border-radius: 8px;
  background: var(--eco-surface);
  padding: 9px 10px;
  font-size: 13px;
  color: var(--eco-muted-ink);
}

.eco-product-import-summary b {
  color: var(--eco-ink);
}

.eco-product-import-table-wrap {
  margin-top: 12px;
  max-height: 390px;
  overflow: auto;
  border: 1px solid var(--eco-border);
  border-radius: 8px;
}

.eco-product-import-table th,
.eco-product-import-table td {
  vertical-align: top;
  font-size: 13px;
}

.eco-product-import-table tr.is-problem td {
  background: rgba(239, 68, 68, 0.08);
}

.eco-product-import-error {
  border: 1px solid rgba(239, 68, 68, 0.3);
  border-radius: 8px;
  background: rgba(239, 68, 68, 0.08);
  padding: 10px 12px;
  color: #991b1b;
  font-size: 14px;
}

.eco-product-import-limit {
  padding: 10px 12px;
  color: var(--eco-muted-ink);
  font-size: 13px;
}

.eco-product-import-footer {
  justify-content: flex-end;
  margin-top: 14px;
}

.eco-product-import-history {
  display: grid;
  width: min(760px, 100%);
  gap: 8px;
  margin-top: 14px;
}

.eco-product-import-history button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid var(--eco-border);
  border-radius: 8px;
  background: var(--eco-surface);
  padding: 10px 12px;
  color: var(--eco-ink);
  text-align: left;
}

.eco-product-import-history button:hover {
  background: var(--eco-soft);
}

.eco-product-import-history b,
.eco-product-import-history small {
  display: block;
}

.eco-product-import-history small,
.eco-product-import-history em {
  color: var(--eco-muted-ink);
  font-size: 12px;
  font-style: normal;
}

@media (max-width: 920px) {
  .eco-modal-backdrop {
    padding: 12px;
  }

  .eco-product-import-grid {
    grid-template-columns: 1fr;
  }

  .eco-product-import-panel {
    border-right: 0;
    border-bottom: 1px solid var(--eco-border);
  }

  .eco-product-import-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.eco-closing-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1100;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.42);
}

.eco-closing-modal {
  display: flex;
  width: min(720px, 100vw);
  height: 100%;
  flex-direction: column;
  background: #fff;
  color: #172026;
  box-shadow: -22px 0 60px rgba(15, 23, 42, 0.2);
}

.eco-closing-modal__header,
.eco-closing-modal__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(15, 23, 42, 0.12);
}

.eco-closing-modal__header h2 {
  margin: 4px 0 0;
  color: #172026;
  font-size: 20px;
  font-weight: 800;
}

.eco-closing-modal__body {
  display: grid;
  gap: 16px;
  overflow: auto;
  padding: 20px;
}

.eco-closing-modal__footer {
  flex-wrap: wrap;
  justify-content: flex-end;
  border-top: 1px solid rgba(15, 23, 42, 0.12);
  border-bottom: 0;
}

.eco-closing-state,
.eco-closing-error {
  display: flex;
  min-height: 180px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  color: #64748b;
  font-size: 14px;
}

.eco-closing-error {
  color: #b91c1c;
}

.eco-closing-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.eco-closing-summary div,
.eco-closing-check,
.eco-closing-history {
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 8px;
  background: #f8fafc;
  padding: 12px;
}

.eco-closing-summary span {
  display: block;
  margin-bottom: 4px;
  color: #64748b;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.eco-closing-summary strong {
  display: block;
  overflow-wrap: anywhere;
  font-size: 14px;
}

.eco-closing-check {
  color: #334155;
  font-size: 13px;
}

.eco-closing-check ul,
.eco-closing-history ul {
  margin: 8px 0 0;
  padding-left: 18px;
}

.eco-closing-check__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.eco-closing-check.is-error {
  border-color: #fecaca;
  background: #fef2f2;
  color: #991b1b;
}

.eco-closing-check.is-warning {
  border-color: #fde68a;
  background: #fffbeb;
  color: #92400e;
}

.eco-closing-check.is-ok {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
  font-weight: 700;
}

.eco-closing-remarks-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #334155;
  font-size: 14px;
  font-weight: 700;
}

.eco-closing-history h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
}

.eco-closing-history p {
  margin: 8px 0 0;
  color: #64748b;
  font-size: 13px;
}

.eco-closing-history li {
  margin-top: 8px;
}

.eco-closing-history a {
  display: block;
  color: #172026;
  font-weight: 800;
  text-decoration: none;
}

.eco-closing-history span {
  display: block;
  margin-top: 2px;
  color: #64748b;
  font-size: 12px;
}

.eco-closing-upd-settings {
  display: grid;
  gap: 14px;
  border-top: 1px solid rgba(15, 23, 42, 0.12);
  padding-top: 16px;
}

.eco-closing-upd-settings h3 {
  margin: 0;
  color: #172026;
  font-size: 15px;
  font-weight: 850;
}

.eco-closing-form-grid,
.eco-closing-signers-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.eco-closing-form-grid label {
  display: grid;
  gap: 6px;
}

.eco-closing-form-grid label.is-wide {
  grid-column: 1 / -1;
}

.eco-closing-form-grid span,
.eco-closing-signers-grid legend {
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.eco-closing-signers-grid fieldset {
  display: grid;
  gap: 8px;
  min-width: 0;
  margin: 0;
  border: 1px solid rgba(15, 23, 42, 0.12);
  border-radius: 8px;
  padding: 12px;
}

@media (max-width: 720px) {
  .eco-closing-summary {
    grid-template-columns: 1fr;
  }

  .eco-closing-form-grid,
  .eco-closing-signers-grid {
    grid-template-columns: 1fr;
  }

  .eco-closing-modal__footer {
    justify-content: stretch;
  }

  .eco-closing-modal__footer .eco-btn {
    width: 100%;
  }
}

/* TGM eco-8 literal diagnostic report transfer from report.html/report-print.jsx. */
.diag-client-report-page {
  min-height: 100vh;
  padding: 0 0 56px;
  background: #0a0a0a;
  color: #f5f2ed;
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.tgm-report-toolbar {
  display: flex;
  width: min(980px, calc(100vw - 48px));
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 0 auto;
  padding: 14px 0;
  color: #9a9a9a;
  font-size: 12px;
}

.tgm-report-toolbar a,
.tgm-report-toolbar button {
  display: inline-flex;
  height: 38px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
  color: #f5f2ed;
  background: #1a1a1a;
  border: 1px solid #2a2a2a;
  border-radius: 0;
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.tgm-report-toolbar button {
  background: #c2410c;
  border-color: #c2410c;
}

.tgm-client-report {
  --ink: #0a0a0a;
  --ink-2: #1a1a1a;
  --paper: #f5f2ed;
  --paper-2: #ece7dd;
  --rust: #c2410c;
  --steel: #3d3d3d;
  --gray-1: #6b6b6b;
  --gray-2: #9a9a9a;
  --line: #2a2a2a;
  --success: #15803d;
  --warn: #c2410c;
  --crit: #b91c1c;
  overflow: hidden;
  width: min(980px, calc(100vw - 48px));
  margin: 0 auto;
  background: var(--ink);
  color: var(--paper);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.46);
}

.tgm-client-report * {
  box-sizing: border-box;
}

.tgm-client-report a {
  color: inherit;
  text-decoration: none;
}

.tgm-client-report .container {
  max-width: 980px;
  margin: 0 auto;
  padding: 0 24px;
}

.tgm-client-report.grain {
  position: relative;
}

.tgm-client-report.grain::after,
.tgm-client-report .grain::after {
  position: absolute;
  inset: 0;
  z-index: 1;
  content: "";
  pointer-events: none;
  opacity: 0.28;
  mix-blend-mode: overlay;
  background-image: radial-gradient(rgba(255, 255, 255, 0.18) 0.5px, transparent 0.5px);
  background-size: 7px 7px;
}

.tgm-client-report > *,
.tgm-client-report .grain > * {
  position: relative;
  z-index: 2;
}

.tgm-client-report .l-mono {
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.04em;
}

.tgm-client-report .eyebrow {
  display: block;
  color: var(--rust);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.tgm-client-report .eyebrow.muted {
  color: var(--gray-2);
}

.tgm-client-report .rust,
.tgm-client-report .dot {
  color: var(--rust);
}

.tgm-client-report .topstrip {
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}

.tgm-client-report .topstrip .row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tgm-client-report .strip-group {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 22px;
}

.tgm-client-report .wordmark {
  display: block;
  height: 16px;
  flex-shrink: 0;
}

.tgm-client-report .hero {
  padding: 30px 0 60px;
  border-bottom: none;
}

.tgm-client-report .hero-intro {
  display: flex;
  align-items: baseline;
  gap: 14px;
  margin-bottom: 26px;
}

.tgm-client-report .hero-intro .line {
  flex: 1;
  height: 1px;
  background: var(--steel);
}

.tgm-client-report .hero-intro .l-mono {
  font-size: 11px;
  letter-spacing: 0.16em;
}

.tgm-client-report h1 {
  margin: 0;
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: clamp(40px, 6.5vw, 84px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 0.92;
  text-transform: uppercase;
}

.tgm-client-report h1 span:not(.dot) {
  color: var(--gray-2);
}

.tgm-client-report .hero-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 56px;
  align-items: center;
  margin-top: 50px;
}

.tgm-client-report .work-done {
  max-width: 540px;
  margin: 14px 0 0;
  color: var(--paper);
  font-size: 16px;
  line-height: 1.55;
  opacity: 0.92;
}

.tgm-client-report .numpanels {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 28px;
}

.tgm-client-report .numpanel {
  min-width: 0;
  padding: 16px 18px;
  border: 1px solid var(--line);
}

.tgm-client-report .numpanel .k {
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tgm-client-report .numpanel .v {
  overflow: hidden;
  margin-top: 10px;
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 36px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tgm-client-report .numpanel .v.sm {
  font-size: 24px;
}

.tgm-client-report .numpanel .u {
  overflow: hidden;
  margin-top: 4px;
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.tgm-client-report .tgm-car-card {
  position: relative;
  min-height: 240px;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  background: #0e0e0e;
  border: 1px solid var(--line);
}

.tgm-client-report .tgm-car-glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 85%, rgba(194, 65, 12, 0.18), transparent 60%);
}

.tgm-client-report .tgm-car-card svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.tgm-client-report .tgm-car-region {
  position: absolute;
  top: 12px;
  left: 14px;
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.tgm-client-report .tgm-car-meta {
  position: absolute;
  bottom: 12px;
  left: 14px;
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.tgm-client-report .chequered {
  height: 14px;
  background-color: var(--ink);
  background-image:
    linear-gradient(45deg, var(--paper) 25%, transparent 25%),
    linear-gradient(-45deg, var(--paper) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--paper) 75%),
    linear-gradient(-45deg, transparent 75%, var(--paper) 75%);
  background-position: 0 0, 0 7px, 7px -7px, -7px 0;
  background-size: 14px 14px;
}

.tgm-client-report .chequered.thin {
  height: 8px;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0;
  background-size: 8px 8px;
}

.tgm-client-report .verdict-section {
  padding: 0;
  border-bottom: none;
}

.tgm-client-report .verdict {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  overflow: hidden;
  padding: 36px;
  color: var(--paper);
  background: var(--rust);
}

.tgm-client-report .verdict::before {
  position: absolute;
  top: -40px;
  right: -10px;
  content: attr(data-ghost);
  color: rgba(10, 10, 10, 0.12);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 280px;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 0.8;
  pointer-events: none;
}

.tgm-client-report .v-num {
  position: relative;
  z-index: 1;
  padding: 14px 8px;
  text-align: center;
  background: rgba(10, 10, 10, 0.15);
  border: 1px solid rgba(245, 242, 237, 0.2);
}

.tgm-client-report .v-num.soft {
  background: rgba(255, 255, 255, 0.1);
}

.tgm-client-report .v-num.dark {
  background: rgba(10, 10, 10, 0.4);
}

.tgm-client-report .v-num .n {
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 56px;
  font-weight: 700;
  line-height: 1;
  white-space: pre-line;
}

.tgm-client-report .v-num.verdict-title .n {
  font-size: 32px;
  line-height: 1.05;
  text-transform: uppercase;
}

.tgm-client-report .v-num .l {
  margin-top: 8px;
  color: rgba(245, 242, 237, 0.9);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tgm-client-report section {
  padding: 70px 0;
  border-bottom: 1px solid var(--line);
}

.tgm-client-report .section-alt {
  background: #0e0e0e;
}

.tgm-client-report .section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 28px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.tgm-client-report .section-head .l {
  display: flex;
  align-items: baseline;
  gap: 18px;
}

.tgm-client-report .section-head .num {
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.14em;
}

.tgm-client-report .section-head h2 {
  margin: 10px 0 0;
  color: var(--paper);
  font-family: Inter, system-ui, sans-serif;
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.05;
}

.tgm-client-report .master {
  text-align: right;
}

.tgm-client-report .master .l-mono {
  margin-bottom: 6px;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.tgm-client-report .master > div:last-child {
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 18px;
  font-weight: 700;
  text-transform: uppercase;
}

.tgm-client-report .blocks {
  display: grid;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
}

.tgm-client-report .block {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
  gap: 18px;
  align-items: flex-start;
  padding: 24px 28px;
  background: var(--ink);
  break-inside: avoid;
}

.tgm-client-report .block-num {
  padding-top: 4px;
  color: var(--rust);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.tgm-client-report .block-body .title {
  margin-bottom: 14px;
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.1;
  text-transform: uppercase;
}

.tgm-client-report .block-items {
  display: grid;
  gap: 1px;
  background: var(--line);
}

.tgm-client-report .block-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 14px;
  align-items: center;
  padding: 14px 16px;
  background: var(--ink);
}

.tgm-client-report .item-label {
  color: var(--paper);
  font-size: 14px;
  font-weight: 600;
}

.tgm-client-report .item-value {
  color: var(--gray-2);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.04em;
}

.tgm-client-report .item-status {
  padding: 4px 10px;
  border: 1px solid rgba(245, 242, 237, 0.2);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.tgm-client-report .item-status.good { color: #4ade80; background: rgba(21, 128, 61, 0.15); border-color: rgba(21, 128, 61, 0.4); }
.tgm-client-report .item-status.warn { color: #ff9a5b; background: rgba(194, 65, 12, 0.15); border-color: rgba(194, 65, 12, 0.4); }
.tgm-client-report .item-status.crit { color: #fca5a5; background: rgba(185, 28, 28, 0.2); border-color: rgba(185, 28, 28, 0.5); }
.tgm-client-report .item-status.no-access,
.tgm-client-report .item-status.by-mileage,
.tgm-client-report .item-status.by-client { color: #93c5fd; background: rgba(29, 78, 216, 0.16); border-color: rgba(147, 197, 253, 0.3); }
.tgm-client-report .item-status.unchecked { color: #c8c2b8; background: rgba(245, 242, 237, 0.08); border-color: rgba(245, 242, 237, 0.14); }

.tgm-client-report .recs {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.tgm-client-report .rec {
  padding: 24px 28px;
  background: #1a1a1a;
  border: 1px solid var(--line);
  border-left: 4px solid var(--warn);
  break-inside: avoid;
}

.tgm-client-report .rec.crit {
  border-left-color: var(--crit);
}

.tgm-client-report .rec-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.tgm-client-report .rec h3 {
  margin: 0;
  color: var(--paper);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.1;
  text-transform: uppercase;
}

.tgm-client-report .rec-tag {
  padding: 4px 8px;
  color: #ff9a5b;
  background: rgba(194, 65, 12, 0.15);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tgm-client-report .rec.crit .rec-tag {
  color: #fca5a5;
  background: rgba(185, 28, 28, 0.2);
}

.tgm-client-report .desc {
  color: rgba(245, 242, 237, 0.86);
  font-size: 14px;
  line-height: 1.55;
}

.tgm-client-report .desc span,
.tgm-client-report .quote {
  color: var(--gray-2);
}

.tgm-client-report .measurement {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 12px;
  padding: 6px 12px;
  color: #ff9a5b;
  background: rgba(194, 65, 12, 0.15);
}

.tgm-client-report .measurement span {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.tgm-client-report .measurement b {
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.tgm-client-report .rec-photos {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}

.tgm-client-report .rec-photos img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  background: #0a0a0a;
  border: 1px solid rgba(245, 242, 237, 0.14);
}

.tgm-client-report .quote {
  margin-top: 14px;
  padding-left: 14px;
  border-left: 2px solid var(--steel);
  font-size: 13px;
  font-style: italic;
}

.tgm-client-report .empty-card {
  padding: 22px 20px;
  color: var(--gray-2);
  background: #1a1a1a;
  border: 1px dashed var(--line);
  font-size: 14px;
}

.tgm-client-report .sticker-wrap {
  max-width: 380px;
  margin-top: 50px;
}

.tgm-client-report .sticker {
  position: relative;
  margin-top: 12px;
  padding: 22px 26px;
  color: var(--ink);
  background: var(--paper);
}

.tgm-client-report .sticker-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.tgm-client-report .sticker img {
  display: block;
  height: 32px;
}

.tgm-client-report .mini-checker {
  width: 60px;
  height: 8px;
  background-color: var(--paper);
  background-image:
    linear-gradient(45deg, var(--ink) 25%, transparent 25%),
    linear-gradient(-45deg, var(--ink) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--ink) 75%),
    linear-gradient(-45deg, transparent 75%, var(--ink) 75%);
  background-position: 0 0, 0 4px, 4px -4px, -4px 0;
  background-size: 8px 8px;
}

.tgm-client-report .sticker h3 {
  margin: 0;
  color: var(--gray-1);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tgm-client-report .sticker .km {
  margin-top: 4px;
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 36px;
  font-weight: 700;
  line-height: 1;
}

.tgm-client-report .sticker .date {
  margin-top: 4px;
  color: var(--rust);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 22px;
  font-weight: 700;
}

.tgm-client-report .sticker .quote {
  margin-top: 14px;
  padding-left: 0;
  color: var(--steel);
  border-left: 0;
  font-family: Inter, system-ui, sans-serif;
  font-size: 13px;
}

.tgm-client-report .sticker .meta {
  margin-top: 14px;
  color: var(--gray-1);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 9px;
  letter-spacing: 0.12em;
  overflow-wrap: anywhere;
}

.tgm-client-report .photos {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.tgm-client-report .tgm-photo {
  margin: 0;
  break-inside: avoid;
}

.tgm-client-report .tgm-photo-img {
  position: relative;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  background-color: #0e0e0e;
  background-position: center;
  background-size: cover;
}

.tgm-client-report .tgm-photo-scrim {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.82) 0%, rgba(0, 0, 0, 0.1) 55%, transparent 100%);
}

.tgm-client-report .tgm-photo-dot {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.25);
}

.tgm-client-report .tgm-photo-no {
  position: absolute;
  z-index: 2;
  top: 7px;
  left: 9px;
  color: rgba(245, 242, 237, 0.8);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 8px;
  letter-spacing: 0.1em;
}

.tgm-client-report .tgm-photo-cap {
  position: absolute;
  right: 9px;
  bottom: 8px;
  left: 9px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tgm-client-report .tgm-photo-cap .lbl {
  color: var(--rust);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tgm-client-report .tgm-photo-cap .cap {
  color: var(--paper);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
}

.tgm-client-report .legend {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 10px;
}

.tgm-client-report .key {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--gray-2);
  font-size: 9px;
}

.tgm-client-report .mark {
  display: inline-flex;
  width: 14px;
  height: 14px;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #fff;
  border-radius: 50%;
  font-size: 9px;
  font-weight: 800;
}

.tgm-client-report .mark.sm {
  width: 13px;
  height: 13px;
  font-size: 8px;
}

.tgm-client-report .checklist {
  columns: 2;
  column-gap: 16px;
}

.tgm-client-report .check-block {
  margin-bottom: 10px;
  break-inside: avoid;
}

.tgm-client-report .check-block-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
  padding-bottom: 5px;
  color: var(--paper);
  border-bottom: 1.5px solid var(--paper);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.tgm-client-report .check-block-title span {
  color: var(--rust);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
}

.tgm-client-report .check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  border-bottom: 1px solid var(--line);
}

.tgm-client-report .check-label {
  flex: 1;
  color: var(--paper);
  font-size: 10px;
}

.tgm-client-report .check-val {
  max-width: 42%;
  color: var(--gray-2);
  font-size: 9.5px;
  text-align: right;
}

.tgm-client-report .cta-section {
  padding: 0;
  border-bottom: none;
}

.tgm-client-report .cta {
  position: relative;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 40px;
  align-items: center;
  overflow: hidden;
  padding: 56px 36px;
  color: var(--ink);
  background: var(--paper);
  break-inside: avoid;
}

.tgm-client-report .cta::before {
  position: absolute;
  top: -60px;
  right: -100px;
  content: attr(data-ghost);
  color: rgba(10, 10, 10, 0.04);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 520px;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 0.8;
  pointer-events: none;
}

.tgm-client-report .cta > * {
  position: relative;
  z-index: 1;
}

.tgm-client-report .cta h2 {
  position: relative;
  margin: 16px 0 0;
  color: var(--ink);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: clamp(36px, 5vw, 64px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 0.95;
  text-transform: uppercase;
}

.tgm-client-report .cta h2 span {
  color: var(--rust);
}

.tgm-client-report .cta p {
  max-width: 480px;
  margin: 20px 0 0;
  color: var(--steel);
  font-size: 16px;
  line-height: 1.55;
}

.tgm-client-report .reminder {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 18px;
  color: var(--steel);
  font-size: 12px;
}

.tgm-client-report .cta-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}

.tgm-client-report .btn,
.tgm-client-report .copy-link {
  display: inline-flex;
  height: 56px;
  align-items: center;
  gap: 10px;
  padding: 0 28px;
  border: 1px solid;
  cursor: pointer;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.tgm-client-report .btn.rust {
  color: var(--paper);
  background: var(--rust);
  border-color: var(--rust);
}

.tgm-client-report .btn.dark,
.tgm-client-report .copy-link {
  color: var(--paper);
  background: var(--ink);
  border-color: var(--ink);
}

.tgm-client-report .phone {
  margin-top: 6px;
  color: var(--ink);
  font-family: Oswald, Impact, "Arial Narrow", sans-serif;
  font-size: 24px;
  font-weight: 700;
}

.tgm-client-report .qr {
  width: 82px;
  height: 82px;
  padding: 5px;
  background: #fff;
}

.tgm-client-report footer {
  padding: 40px 0;
  background: var(--ink);
}

.tgm-client-report .foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  color: var(--gray-1);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tgm-client-report .foot-brand,
.tgm-client-report .foot-meta {
  display: flex;
  align-items: center;
  gap: 22px;
}

.tgm-client-report .foot-brand img {
  display: block;
  height: 28px;
}

.tgm-client-report .disclaimer {
  max-width: 740px;
  margin-top: 16px;
  padding-top: 16px;
  color: var(--gray-1);
  border-top: 1px solid var(--line);
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
  line-height: 1.6;
}

@media (max-width: 720px) {
  .diag-client-report-page {
    padding-bottom: 0;
  }

  .tgm-report-toolbar,
  .tgm-client-report {
    width: 100%;
  }

  .tgm-report-toolbar {
    padding: 10px 12px;
  }

  .tgm-report-toolbar span {
    display: none;
  }

  .tgm-client-report .topstrip .row,
  .tgm-client-report .hero-grid,
  .tgm-client-report .numpanels,
  .tgm-client-report .verdict,
  .tgm-client-report .block,
  .tgm-client-report .block-item,
  .tgm-client-report .section-head,
  .tgm-client-report .section-head .l,
  .tgm-client-report .photos,
  .tgm-client-report .cta,
  .tgm-client-report .foot,
  .tgm-client-report .foot-brand,
  .tgm-client-report .foot-meta {
    grid-template-columns: 1fr;
    align-items: flex-start;
    flex-direction: column;
  }

  .tgm-client-report .container {
    padding: 0 18px;
  }

  .tgm-client-report .hero {
    padding-bottom: 42px;
  }

  .tgm-client-report section {
    padding: 48px 0;
  }

  .tgm-client-report .block-item {
    gap: 8px;
  }

  .tgm-client-report .checklist {
    columns: 1;
  }

  .tgm-client-report .cta-actions {
    align-items: flex-start;
  }
}

@media print {
  @page {
    size: A4;
    margin: 0;
  }

  html,
  body {
    background: #0a0a0a !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .diag-client-report-page {
    min-height: 0 !important;
    padding: 0 !important;
    background: #0a0a0a !important;
  }

  .diag-client-report-page .no-print,
  .tgm-report-toolbar {
    display: none !important;
  }

  .tgm-client-report {
    width: 210mm !important;
    max-width: none !important;
    margin: 0 !important;
    box-shadow: none !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .tgm-client-report .hero,
  .tgm-client-report .verdict,
  .tgm-client-report section,
  .tgm-client-report .block,
  .tgm-client-report .rec,
  .tgm-client-report .tgm-photo,
  .tgm-client-report .sticker,
  .tgm-client-report .cta,
  .tgm-client-report footer {
    break-inside: avoid;
    page-break-inside: avoid;
  }
}

/* Diagnostic transfer from tgm-8.zip: platform/tokens.css + diagnostics.jsx + diag-print.jsx */
:root {
  --f-display: "Oswald", "Arial Narrow", Impact, sans-serif;
  --f-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --f-mono: "JetBrains Mono", "SFMono-Regular", Consolas, monospace;
  --ink: #0a0a0a;
  --ink-2: #1a1a1a;
  --bg: #f5f2ed;
  --surface: #fffaf3;
  --surface-sunk: #ece7dd;
  --surface-deep: #ded7ca;
  --paper: #f5f2ed;
  --rust: #c2410c;
  --rust-tint: #fff0e8;
  --rust-tint-2: #ffd7c2;
  --line: #e5e2da;
  --line-strong: #d6d1c4;
  --muted: #737373;
  --faint: #a3a3a3;
  --success: #15803d;
  --warning: #b45309;
  --danger: #b91c1c;
  --info: #1d4ed8;
  --danger-tint: #fee2e2;
  --danger-tint-strong: #fecaca;
  --warning-tint: #ffedd5;
  --warning-tint-strong: #fed7aa;
  --info-tint: #dbeafe;
  --info-tint-strong: #bfdbfe;
}

.preset-chip {
  min-height: 30px;
  padding: 0 10px;
  color: var(--ink-2);
  background: var(--surface-sunk);
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.preset-chip:hover,
.preset-chip.light:hover {
  color: var(--rust);
  background: var(--rust-tint);
  border-color: var(--rust-tint-2);
}

.preset-chip.light {
  background: #fff;
}

.preset-chip.is-active {
  color: #fff;
  background: var(--rust);
  border-color: var(--rust);
}

.preset-chip.light.is-active {
  color: #fff;
  background: var(--rust);
}

.diag-archive-screen {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  flex-direction: column;
  color: var(--ink);
  background: var(--bg);
  font-family: var(--f-sans);
}

.diag-archive-topbar {
  display: flex;
  min-height: 70px;
  align-items: center;
  gap: 16px;
  padding: 0 22px;
  color: #f5f2ed;
  background: #0a0a0a;
  border-bottom: 1px solid #242424;
  flex-shrink: 0;
}

.diag-archive-close,
.diag-archive-btn {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 12px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
}

.diag-archive-btn:hover,
.diag-archive-close:hover {
  transform: translateY(-1px);
}

.diag-archive-btn:disabled {
  cursor: not-allowed;
  opacity: 0.42;
  transform: none;
}

.diag-archive-close,
.diag-archive-btn.is-dark {
  color: #f5f2ed;
  background: #2f2f2f;
  border-color: #3d3d3d;
}

.diag-archive-btn.is-primary {
  color: #fff;
  background: var(--rust);
  border-color: var(--rust);
}

.diag-archive-separator {
  width: 1px;
  height: 24px;
  background: #3d3d3d;
}

.diag-archive-title {
  display: grid;
  gap: 3px;
  flex: 1;
  min-width: 0;
}

.diag-archive-title span,
.diag-archive-title small,
.diag-archive-progress span,
.diag-archive-sidebar-head,
.diag-archive-side-summary > span,
.diag-archive-item-head > div > span,
.diag-archive-status > div > span,
.diag-archive-field > span,
.diag-archive-photos > span,
.diag-archive-comment > span,
.diag-archive-summary > div:first-child > span {
  color: #9a9a9a;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.diag-archive-title strong {
  overflow: hidden;
  font-size: 16px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diag-archive-title b {
  color: #9a9a9a;
  font-family: var(--f-mono);
  font-weight: 500;
}

.diag-archive-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.diag-archive-mode-toggle {
  display: inline-flex;
  overflow: hidden;
  border: 1px solid #3d3d3d;
  border-radius: 6px;
}

.diag-archive-mode-toggle button {
  min-height: 38px;
  padding: 0 12px;
  color: #9a9a9a;
  background: #151515;
  border: 0;
  border-right: 1px solid #3d3d3d;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
}

.diag-archive-mode-toggle button:last-child {
  border-right: 0;
}

.diag-archive-mode-toggle button.is-active {
  color: #fff;
  background: var(--rust);
}

.diag-archive-progress {
  text-align: right;
}

.diag-archive-progress strong {
  display: block;
  margin-top: 2px;
  font-family: var(--f-mono);
  font-size: 14px;
}

.diag-archive-ring {
  position: relative;
  width: 48px;
  height: 48px;
}

.diag-archive-ring span {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #f5f2ed;
  font-family: var(--f-mono);
  font-size: 12px;
  font-weight: 800;
}

.diag-archive-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 18px;
  color: #7f1d1d;
  background: #fee2e2;
  border-bottom: 1px solid #fecaca;
}

.diag-archive-error button {
  border: 0;
  background: transparent;
  cursor: pointer;
}

.diag-archive-loading {
  display: grid;
  flex: 1;
  place-items: center;
  color: var(--muted);
  font-weight: 800;
}

.diag-archive-body {
  display: grid;
  grid-template-columns: 292px minmax(0, 1fr);
  flex: 1;
  min-height: 0;
}

.diag-archive-sidebar {
  min-height: 0;
  overflow-y: auto;
  background: var(--surface);
  border-right: 1px solid var(--line);
}

.diag-archive-sidebar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 22px 22px 14px;
}

.diag-archive-sidebar-head button {
  display: none;
  width: 44px;
  height: 44px;
  color: var(--muted);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.diag-archive-block-btn {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 5px;
  padding: 15px 20px;
  text-align: left;
  background: transparent;
  border: 0;
  border-top: 1px solid var(--line);
  border-left: 3px solid transparent;
  cursor: pointer;
}

.diag-archive-block-btn.is-open {
  background: #efebe2;
  border-left-color: var(--rust);
}

.diag-archive-block-btn span {
  display: grid;
  gap: 2px;
  flex: 1;
}

.diag-archive-block-btn strong {
  color: var(--ink);
  font-size: 13px;
  line-height: 1.2;
}

.diag-archive-block-btn small {
  color: var(--muted);
  font-size: 11px;
}

.diag-archive-block-btn i {
  display: inline-flex;
  min-width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  color: #fff;
  border-radius: 9px;
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
}

.diag-archive-block-btn i:empty {
  display: none;
}

.diag-archive-block-btn .is-crit { background: var(--danger); }
.diag-archive-block-btn .is-warn { background: var(--warning); }
.diag-archive-block-btn .is-ind { background: #6b7280; }
.diag-archive-block-btn .is-good { background: var(--success); }

.diag-archive-item-btn {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  padding: 12px 20px 12px 33px;
  text-align: left;
  background: transparent;
  border: 0;
  border-left: 3px solid transparent;
  cursor: pointer;
}

.diag-archive-item-btn.is-active {
  background: #f3dfd4;
  border-left-color: var(--rust);
}

.diag-archive-item-btn b {
  display: inline-flex;
  width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  color: #fff;
  border-radius: 50%;
  font-size: 10px;
  flex-shrink: 0;
}

.diag-archive-item-btn span {
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.3;
}

.diag-archive-item-btn em {
  min-width: 18px;
  height: 18px;
  display: inline-grid;
  place-items: center;
  color: #fff;
  background: var(--rust);
  border-radius: 9px;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.diag-archive-side-summary {
  margin-top: 8px;
  padding: 20px;
  border-top: 1px solid var(--line);
}

.diag-archive-side-summary > div {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 12px;
}

.diag-archive-side-summary p {
  margin: 0;
  padding: 10px 12px;
  background: var(--surface-sunk);
  border: 1px solid var(--line);
}

.diag-archive-side-summary b {
  display: block;
  margin-top: 4px;
  font-family: var(--f-mono);
  font-size: 18px;
}

.diag-archive-side-summary .dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 6px;
  border-radius: 50%;
}

.diag-archive-side-summary .success { background: var(--success); }
.diag-archive-side-summary .warning { background: var(--warning); }
.diag-archive-side-summary .danger { background: var(--danger); }
.diag-archive-side-summary .info { background: var(--info); }

.diag-archive-main {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  padding: 28px 36px 0;
  background:
    linear-gradient(90deg, rgba(10,10,10,0.025) 1px, transparent 1px) 0 0 / 52px 52px,
    var(--bg);
}

.diag-quick-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 18px;
  align-items: start;
  padding-bottom: 26px;
}

.diag-quick-board {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.diag-quick-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 5px solid var(--rust);
  border-radius: 8px;
}

.diag-quick-hero span,
.diag-quick-summary > span,
.diag-quick-sheet > span {
  color: var(--rust);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.diag-quick-hero h1 {
  margin: 5px 0 0;
  color: var(--ink);
  font-size: 24px;
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1.05;
}

.diag-quick-hero p {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.diag-quick-hero p b {
  color: var(--ink);
}

.diag-quick-tools {
  display: flex;
  align-items: flex-start;
