}

.diag-archive-recommendation > span {
  color: var(--info);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.diag-archive-recommendation.is-danger > span { color: var(--danger); }
.diag-archive-recommendation.is-warning > span { color: var(--warning); }

.diag-archive-recommendation footer {
