}

.diag-archive-lightbox > div {
  position: relative;
  display: grid;
  gap: 10px;
  max-width: min(920px, 94vw);
  color: #fff;
}

.diag-archive-lightbox button {
  position: absolute;
  top: -14px;
  right: -14px;
  width: 36px;
  height: 36px;
  color: #fff;
  background: #111;
  border: 1px solid #333;
