.paper-a4 {
  --rep-pad: 14mm;
  width: 210mm;
  min-height: 297mm;
  margin: 24px auto 0;
  overflow: hidden;
  color: #0a0a0a;
  background: #fff;
  box-shadow: 0 24px 60px rgba(0,0,0,0.4);
  font-size: 10.5px;
  line-height: 1.4;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.rep-hero { position: relative; color: #f5f2ed; background: #0a0a0a; }
.rep-hero-top { display: flex; align-items: center; justify-content: space-between; padding: 9mm var(--rep-pad) 0; font-family: var(--f-mono); font-size: 9px; letter-spacing: 0.14em; color: #9a9a9a; }
.rep-wordmark { color: #f5f2ed; font-family: var(--f-display); font-size: 16px; font-weight: 700; letter-spacing: 0.01em; }
.rep-hero-body { display: grid; grid-template-columns: 1.25fr 1fr; gap: 22px; align-items: center; padding: 6mm var(--rep-pad) 7mm; }
.rep-eyebrow { color: #737373; font-size: 9px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; }
.rep-eyebrow.rust { color: var(--rust); }
.rep-title { margin: 10px 0 0; font-family: var(--f-display); font-size: 40px; font-weight: 700; line-height: 0.96; letter-spacing: -0.01em; text-transform: uppercase; }
.rep-title .muted2 { color: #6e6e6e; }
.rep-title .rust { color: var(--rust); }
.rep-facts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 20px; }
.rep-fact { padding: 8px 9px; border: 1px solid #2a2a2a; }
.rep-fact .k { color: #8a8a8a; font-size: 7.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.rep-fact .v { margin-top: 3px; font-family: var(--f-display); font-size: 19px; font-weight: 700; line-height: 1.05; }
.rep-fact .v.sm { font-size: 15px; }
.rep-fact .u { margin-top: 1px; color: #8a8a8a; font-size: 8px; }
.rep-hero-car { position: relative; aspect-ratio: 4 / 3; overflow: hidden; background: #0e0e0e; border: 1px solid #2a2a2a; }
.rep-hero-car svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.rep-hero-car::after { content: ""; position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 80%, rgba(194,65,12,0.18), transparent 60%); }
.rep-car-tag { position: absolute; z-index: 2; bottom: 8px; left: 10px; color: #b8b2a8; font-family: var(--f-mono); font-size: 8px; letter-spacing: 0.1em; }
.rep-chequered { height: 9px; background-image: linear-gradient(45deg,#f5f2ed 25%,transparent 25%), linear-gradient(-45deg,#f5f2ed 25%,transparent 25%), linear-gradient(45deg,transparent 75%,#f5f2ed 75%), linear-gradient(-45deg,transparent 75%,#f5f2ed 75%); background-size: 9px 9px; background-position: 0 0, 0 4.5px, 4.5px -4.5px, -4.5px 0; background-color: #0a0a0a; }

.rep-verdict { display: grid; grid-template-columns: repeat(4, 0.7fr) 1.5fr; border-bottom: 1px solid #e5e2da; }
.rep-v-cell { padding: 12px 10px; border-right: 1px solid #e5e2da; }
.rep-verdict .rep-v-cell:first-child { padding-left: var(--rep-pad); }
.rep-v-cell .n { font-family: var(--f-display); font-size: 30px; font-weight: 700; line-height: 1; }
.rep-v-cell .l { margin-top: 4px; color: #737373; font-size: 8.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.rep-v-cell.good .n { color: #15803d; }
.rep-v-cell.warn .n { color: #b45309; }
.rep-v-cell.crit .n { color: #b91c1c; }
.rep-v-cell.ind .n { color: #1d4ed8; }
.rep-v-statement { display: flex; flex-direction: column; justify-content: center; padding: 12px var(--rep-pad); background: #f4f1ea; }
.rep-v-statement .s { margin-top: 6px; font-family: var(--f-display); font-size: 22px; font-weight: 700; line-height: 1; text-transform: uppercase; }

.rep-sec { padding: 10mm var(--rep-pad) 0; break-inside: avoid; }
.rep-sec-head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 12px; }
.rep-sec-num { color: var(--rust); font-family: var(--f-mono); font-size: 11px; font-weight: 800; }
.rep-h2 { margin: 4px 0 0; font-family: var(--f-display); font-size: 24px; font-weight: 700; letter-spacing: -0.01em; text-transform: uppercase; }
.rep-recs { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.rep-rec { padding: 11px 13px; border: 1px solid #e5e2da; border-left: 3px solid; break-inside: avoid; }
.rep-rec-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 6px; }
.rep-rec-head h3 { margin: 0; font-size: 13px; font-weight: 800; }
.rep-rec-tag { flex-shrink: 0; padding: 3px 7px; color: #fff; border-radius: 2px; font-size: 7.5px; font-weight: 800; letter-spacing: 0.03em; text-transform: uppercase; white-space: nowrap; }
.rep-rec-desc { color: #2a2a2a; font-size: 10.5px; line-height: 1.5; }
.rep-rec-photos { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; margin-top: 8px; }
.rep-rec-photos img { display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border: 1px solid #e5e2da; }
.rep-rec-quote { margin-top: 8px; padding-top: 7px; color: #525252; border-top: 1px dashed #d6d1c4; font-size: 9.5px; font-style: italic; }
.rep-rec-quote span { color: #9a9a9a; font-style: normal; }

.rep-photos { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.rep-photo { margin: 0; break-inside: avoid; }
.rep-photo-img { position: relative; aspect-ratio: 4 / 3; overflow: hidden; background-size: cover; background-position: center; }
.rep-photo-scrim { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.82) 0%, rgba(0,0,0,0.1) 55%, transparent 100%); }
.rep-photo-dot { position: absolute; top: 8px; right: 8px; width: 10px; height: 10px; border-radius: 50%; box-shadow: 0 0 0 2px rgba(255,255,255,0.25); }
.rep-photo-no { position: absolute; z-index: 2; top: 7px; left: 9px; color: rgba(245,242,237,0.8); font-family: var(--f-mono); font-size: 8px; letter-spacing: 0.1em; }
.rep-photo-cap { position: absolute; z-index: 2; right: 9px; bottom: 8px; left: 9px; display: flex; flex-direction: column; gap: 2px; }
.rep-photo-cap .lbl { color: var(--rust); font-size: 7.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.rep-photo-cap .cap { color: #f5f2ed; font-size: 11px; font-weight: 700; line-height: 1.2; text-shadow: 0 1px 3px rgba(0,0,0,0.7); }
.rep-photo-note { margin-top: 8px; color: #9a9a9a; font-size: 8.5px; }

.rep-legend { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 10px; }
.rep-key { display: inline-flex; align-items: center; gap: 5px; color: #525252; font-size: 8.5px; }
.rep-mark { display: inline-flex; width: 14px; height: 14px; align-items: center; justify-content: center; color: #fff; border-radius: 50%; font-size: 9px; font-weight: 800; flex-shrink: 0; }
.rep-mark.sm { width: 13px; height: 13px; font-size: 8px; }
.rep-check { columns: 2; column-gap: 16px; }
.rep-block { margin-bottom: 10px; break-inside: avoid; }
.rep-block-head { display: flex; align-items: center; gap: 8px; margin-bottom: 3px; padding-bottom: 5px; border-bottom: 1.5px solid #0a0a0a; font-size: 11px; font-weight: 800; letter-spacing: 0.02em; text-transform: uppercase; }
.rep-block-no { color: var(--rust); font-family: var(--f-mono); }
.rep-check-row { display: flex; align-items: center; gap: 8px; padding: 4px 0; border-bottom: 1px solid #efebe2; }
.rep-check-label { flex: 1; color: #2a2a2a; font-size: 10px; }
.rep-check-val { max-width: 42%; color: #737373; font-size: 9.5px; text-align: right; }

.rep-foot { position: relative; padding: 10mm var(--rep-pad) 12mm; break-inside: avoid; }
.rep-foot-cta { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding: 14px 16px; color: #f5f2ed; background: #0a0a0a; }
.rep-foot-q { max-width: 320px; margin-top: 8px; font-family: var(--f-display); font-size: 19px; font-weight: 700; line-height: 1.05; text-transform: uppercase; }
.rep-foot-sub { max-width: 320px; margin-top: 6px; color: #9a9a9a; font-size: 9.5px; line-height: 1.5; }
.rep-foot-contact { flex-shrink: 0; text-align: right; }
.rep-foot-contact .ph { color: var(--rust); font-family: var(--f-display); font-size: 18px; font-weight: 700; }
.rep-foot-contact .tg { margin-top: 4px; font-size: 10px; }
.rep-foot-contact .link { margin-top: 6px; color: #9a9a9a; font-family: var(--f-mono); font-size: 9px; }
.rep-online-actions { display: flex; flex-wrap: wrap; gap: 5px; justify-content: flex-end; margin-top: 8px; }
.rep-online-actions a,
.rep-online-actions button { display: inline-flex; min-height: 26px; align-items: center; gap: 4px; padding: 0 7px; color: #f5f2ed; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.16); font-size: 9px; text-decoration: none; }
.rep-reminder { display: inline-flex; align-items: center; gap: 6px; margin-top: 10px; color: #c8c2b8; font-size: 10px; }
.rep-sign { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 26px; }
.rep-sign-line { height: 22px; border-bottom: 1px solid #0a0a0a; }
.rep-sign-lbl { margin-top: 4px; color: #525252; font-size: 8.5px; }
.rep-disclaimer { margin-top: 18px; padding-top: 12px; color: #9a9a9a; border-top: 1px solid #e5e2da; font-size: 8px; line-height: 1.55; }
.rep-qr { position: absolute; right: var(--rep-pad); bottom: 12mm; width: 72px; height: 72px; background: #fff; }

