  margin-left: 2px;
}

.eco-product-actions-menu {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 10080;
  display: grid;
  min-width: 236px;
  max-width: min(300px, calc(100vw - 28px));
  max-height: calc(100vh - 24px);
  overflow-y: auto;
  padding: 6px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  box-shadow: 0 18px 48px rgba(21, 18, 14, 0.18);
  text-align: left;
  white-space: normal;
}

.eco-product-actions-menu::before {
  position: absolute;
  top: -6px;
  left: var(--eco-action-menu-arrow-left, 18px);
  width: 10px;
  height: 10px;
  background: var(--eco-surface);
  border-top: 1px solid var(--eco-line-strong);
  border-left: 1px solid var(--eco-line-strong);
  content: "";
  transform: rotate(45deg);
}

.eco-product-actions-menu.is-top::before {
  top: auto;
  bottom: -6px;
  border-top: 0;
  border-left: 0;
  border-right: 1px solid var(--eco-line-strong);
  border-bottom: 1px solid var(--eco-line-strong);
}

