.eco-facet-dialog {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  width: min(560px, calc(100vw - 32px));
  max-height: min(720px, calc(100vh - 48px));
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: 0 26px 80px rgba(21, 18, 14, 0.28);
}

.eco-facet-dialog-head,
.eco-facet-dialog-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-facet-dialog-footer {
  border-top: 1px solid var(--eco-line);
  border-bottom: 0;
  justify-content: flex-end;
}

.eco-facet-dialog-head h3 {
  margin: 2px 0 0;
  color: var(--eco-ink);
  font-size: 22px;
  font-weight: 800;
}

.eco-facet-search {
  margin: 16px 20px 10px;
}

.eco-facet-dialog-list {
  min-height: 180px;
  overflow: auto;
  padding: 0 20px 18px;
}

.eco-products-empty {
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 40px 20px;
  color: var(--eco-muted);
  text-align: center;
}

.eco-products-empty strong {
  color: var(--eco-ink);
  font-size: 18px;
  font-weight: 800;
}

.eco-products-empty span {
  max-width: 560px;
  line-height: 1.5;
}

.eco-products-empty.is-error strong {
  color: #991b1b;
}

.eco-products-empty-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 8px;
}

@media (max-width: 1180px) {
  .eco-inventory-layout,
  .eco-inventory-layout.is-filter-collapsed {
    display: block;
    padding-top: 20px;
  }

  .eco-filter-slot {
    position: fixed;
    inset: 0;
    z-index: 75;
    pointer-events: none;
  }

  .eco-inventory-layout.is-filter-drawer-open .eco-filter-slot {
    pointer-events: auto;
  }

  .eco-filter-drawer-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(21, 18, 14, 0.36);
    border: 0;
    opacity: 0;
    transition: opacity 180ms ease;
  }

  .eco-inventory-layout.is-filter-drawer-open .eco-filter-drawer-backdrop {
    display: block;
    opacity: 1;
  }

  .eco-filter-rail,
  .eco-inventory-layout.is-filter-collapsed .eco-filter-rail {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    width: min(100%, 560px);
    max-height: min(84vh, 760px);
    margin: 0 auto;
    overflow: auto;
    padding: 18px 18px 10px;
    border-color: var(--eco-line);
    border-radius: 12px 12px 0 0;
    opacity: 1;
    pointer-events: auto;
    transform: translateY(104%);
    transition: transform 200ms ease;
    visibility: visible;
  }

  .eco-inventory-layout.is-filter-drawer-open .eco-filter-rail {
    transform: translateY(0);
  }

  .eco-filter-collapse,
  .eco-filter-reopen {
    display: none !important;
  }

  .eco-filter-close-mobile {
    display: inline-flex;
    width: 34px;
    height: 34px;
  }

  .eco-filter-mobile-toggle {
    display: inline-flex;
    min-height: 38px;
    padding: 0 12px;
    margin-bottom: 12px;
  }

  .eco-product-confirm {
    grid-template-columns: 1fr;
  }

  .eco-product-confirm-actions {
    flex-direction: column-reverse;
  }

  .eco-product-confirm-actions .eco-btn {
    width: 100%;
  }

  .eco-product-toast {
    right: 12px;
    bottom: 12px;
    left: 12px;
    max-width: none;
  }
}

.eco-product-skeleton-row td {
  height: 72px;
}

.eco-product-skeleton-line {
  display: block;
  width: 100%;
  height: 12px;
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(148, 136, 120, 0.12), rgba(148, 136, 120, 0.24), rgba(148, 136, 120, 0.12));
  background-size: 220% 100%;
  animation: eco-product-shimmer 1.4s ease-in-out infinite;
}

.eco-action-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 4px;
}

.eco-action-link:hover {
  background: var(--eco-hover);
}

.eco-action-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-deep);
  border-radius: 4px;
  flex: 0 0 auto;
}

.eco-action-icon.is-accent {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
}

.eco-panel-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-panel-row:last-child {
  border-bottom: 0;
}

.eco-dark-start {
  position: relative;
  overflow: hidden;
  padding: 40px;
  color: #f5f2ed;
  background: var(--eco-ink);
  border-radius: 4px;
}

.eco-dark-start::before {
  position: absolute;
  inset: 0;
  content: "";
  opacity: 0.4;
  background-image:
    repeating-linear-gradient(60deg, transparent 0 22px, rgba(245, 242, 237, 0.04) 22px 23px),
    repeating-linear-gradient(-60deg, transparent 0 22px, rgba(245, 242, 237, 0.04) 22px 23px);
}

.eco-dark-start > * {
  position: relative;
}

.eco-page-crumbs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 10px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-page-crumbs a {
  color: var(--eco-ink-3);
  text-decoration: none;
}

.eco-page-crumbs a:hover {
  color: var(--eco-ink);
}

.eco-page-crumbs .sep {
  color: var(--eco-faint);
}

.eco-page-crumbs .cur {
  color: var(--eco-ink);
  font-weight: 600;
}

.eco-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.eco-page-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.eco-card__head--plain {
  min-height: auto;
  padding: 0 0 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-card__head--plain h2 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 16px;
  font-weight: 700;
}

.eco-card__head--plain p {
  margin: 4px 0 0;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-icon-btn:hover {
  color: var(--eco-ink);
  background: var(--eco-hover);
  border-color: var(--eco-line-strong);
}

.eco-select-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  min-width: 0;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 12px;
  white-space: nowrap;
}

.eco-select-chip span {
  color: var(--eco-muted);
}

.eco-select-inline {
  min-width: 0;
  max-width: 100%;
  flex: 1;
  padding-right: 16px;
  appearance: none;
  -webkit-appearance: none;
  color: var(--eco-ink);
  background-color: transparent;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),
    linear-gradient(135deg, currentColor 50%, transparent 50%);
  background-repeat: no-repeat;
  background-position: calc(100% - 8px) 50%, calc(100% - 4px) 50%;
  background-size: 4px 4px, 4px 4px;
  border: 0;
  outline: none;
  font-weight: 600;
  text-overflow: ellipsis;
}

.eco-form-error,
.eco-form-hint {
  margin: 12px 0 0;
  font-size: 12px;
}

.eco-form-error {
  color: var(--eco-danger);
}

.eco-form-hint {
  color: var(--eco-muted);
}

.eco-crm-page {
  min-height: calc(100dvh - var(--eco-topbar-h, 0px));
}

.eco-crm-head {
  margin-bottom: 14px;
}

.eco-crm-metrics {
  grid-template-columns: repeat(7, minmax(120px, 1fr));
  margin-bottom: 14px;
}

.eco-crm-filter-strip {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}

.eco-crm-view-tabs,
.eco-crm-filter-pills {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-crm-view-tabs {
  padding: 3px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-crm-view-tabs button,
.eco-crm-filter-pills button {
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 750;
}

.eco-crm-view-tabs button.is-active,
.eco-crm-filter-pills button.is-active {
  color: var(--eco-rust-ink);
  background: var(--eco-rust-tint);
  border-color: var(--eco-rust-tint-strong);
}

.eco-crm-view-tabs button:disabled {
  opacity: 0.48;
}

.eco-crm-filter-pills {
  flex: 1 1 520px;
}

.eco-crm-filter-pills button {
  background: var(--eco-surface);
  border-color: var(--eco-line);
}

.eco-crm-search {
  flex: 1 1 360px;
  min-width: 280px;
  max-width: 520px;
}

.eco-crm-page-error {
  margin: 0 0 12px;
}

.eco-crm-form-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.eco-counterparty-box {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-top: 16px;
  padding: 14px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-counterparty-main {
  min-width: 0;
  flex: 1;
}

.eco-counterparty-search {
  position: relative;
  max-width: 520px;
  margin-top: 10px;
}

.eco-counterparty-dropdown {
  position: absolute;
  z-index: 30;
  top: calc(100% + 4px);
  right: 0;
  left: 0;
  max-height: 224px;
  padding: 5px;
  overflow: auto;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  box-shadow: var(--eco-shadow-pop);
}

.eco-counterparty-dropdown button {
  display: grid;
  gap: 2px;
  width: 100%;
  padding: 8px 10px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 0;
  border-radius: 2px;
  font-size: 13px;
  text-align: left;
}

.eco-counterparty-dropdown button span {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-counterparty-dropdown button:hover {
  color: var(--eco-ink);
  background: var(--eco-hover);
}

.eco-counterparty-empty {
  padding: 8px 10px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-counterparty-selected {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  padding: 7px 10px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid var(--eco-success-tint-strong);
  border-radius: 4px;
  font-size: 13px;
}

.eco-counterparty-selected button {
  color: inherit;
  background: transparent;
  border: 0;
  font-size: 12px;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.eco-check-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  max-width: 360px;
  padding: 10px 12px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 12px;
}

.eco-check-row input {
  margin-top: 2px;
}

.eco-crm-board-shell {
  height: clamp(520px, calc(100dvh - 342px), 820px);
  min-height: 520px;
  overflow: auto;
  padding-bottom: 10px;
  overscroll-behavior: contain;
}

.eco-crm-board {
  display: grid;
  gap: 12px;
  align-items: stretch;
  min-width: max-content;
  min-height: 100%;
}

.eco-crm-column {
  display: flex;
  width: 100%;
  min-width: 300px;
  min-height: 100%;
  flex-direction: column;
  overflow: hidden;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-top: 3px solid var(--eco-rust);
  border-radius: 4px;
}

.eco-crm-column.is-drag-over {
  background: color-mix(in srgb, var(--eco-rust-tint) 56%, var(--eco-surface-sunk));
  border-color: var(--eco-rust-tint-strong);
}

.eco-crm-column.is-empty {
  min-height: 260px;
}

.eco-crm-column-head {
  position: sticky;
  z-index: 2;
  top: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 12px 10px;
  background: var(--eco-surface);
  border-bottom: 1px solid var(--eco-line);
}

.eco-crm-column-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 850;
  letter-spacing: 0;
}

.eco-crm-column-count {
  padding: 1px 6px;
  color: var(--eco-muted);
  background: var(--eco-surface-deep);
  border-radius: 2px;
  font-family: ui-monospace, monospace;
  font-size: 10px;
  letter-spacing: 0;
}

.eco-crm-column-sub {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 7px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 700;
}

.eco-crm-column-sub span + span::before {
  content: "·";
  margin-right: 6px;
  color: var(--eco-muted);
}

.eco-crm-column-sub .is-danger {
  color: var(--eco-danger);
}

.eco-crm-cards {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow-y: auto;
  padding: 9px;
}

.eco-crm-empty {
  padding: 18px 14px;
  color: var(--eco-muted);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 4px;
  font-size: 12px;
  text-align: center;
}

.eco-deal-card {
  position: relative;
  display: block;
  min-height: 118px;
  padding: 10px 11px;
  cursor: pointer;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-deal-card.is-expanded {
  min-height: 0;
  padding-bottom: 12px;
}

.eco-deal-card:hover {
  border-color: var(--eco-ink-3);
  box-shadow: var(--eco-shadow-md);
}

.eco-deal-card.is-muted {
  opacity: 0.72;
}

.eco-deal-card.is-overdue {
  border-color: var(--eco-danger-tint-strong);
  background: color-mix(in srgb, var(--eco-danger-tint) 36%, var(--eco-surface));
  box-shadow: 0 0 0 1px var(--eco-danger) inset, var(--eco-shadow-sm);
}

.eco-deal-card.is-soon {
  border-color: var(--eco-warning-tint-strong);
  background: color-mix(in srgb, var(--eco-warning-tint) 34%, var(--eco-surface));
}

.eco-deal-card.is-moving {
  opacity: 0.62;
}

.eco-deal-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.eco-deal-card__top {
  margin-bottom: 6px;
  color: var(--eco-muted);
  font-size: 10px;
}

.eco-deal-card__top-actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.eco-deal-card__chevron {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  color: var(--eco-muted);
  background: transparent;
  border: 0;
  border-radius: 4px;
}

.eco-deal-card__chevron:hover {
  color: var(--eco-ink);
  background: var(--eco-hover);
}

.eco-deal-card.is-expanded .eco-deal-card__chevron svg {
  transform: rotate(180deg);
}

.eco-deal-card__grab {
  display: inline-flex;
  align-items: center;
  color: var(--eco-muted);
  opacity: 0.72;
}

.eco-deal-card__client {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
  align-items: center;
}

.eco-deal-card__client strong {
  display: block;
  min-width: 0;
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 850;
  line-height: 1.18;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__client span:not(.eco-client-type-badge) {
  display: block;
  margin-top: 2px;
  overflow: hidden;
  color: var(--eco-muted);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__vehicle {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  margin-top: 5px;
  color: var(--eco-muted);
  font-size: 11px;
  line-height: 1.3;
}

.eco-deal-card__vehicle span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__text {
  display: -webkit-box;
  overflow: hidden;
  margin: 7px 0 0;
  color: var(--eco-ink-2);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.3;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.eco-deal-card__next {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  margin-top: 7px;
  padding: 0;
  color: var(--eco-ink-2);
  background: transparent;
  border: 0;
}

.eco-deal-card__next.is-overdue {
  color: var(--eco-danger);
  background: transparent;
}

.eco-deal-card__next span {
  flex: 0 0 auto;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: none;
}

.eco-deal-card__next strong {
  min-width: 0;
  overflow: hidden;
  font-size: 12px;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__status-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  margin-top: 7px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 750;
}

.eco-deal-card__status-row > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 0;
}

.eco-deal-card__links {
  display: flex;
  gap: 5px;
  margin-top: 7px;
}

.eco-deal-card__links span {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  opacity: 0.58;
}

.eco-deal-card__links span.is-on {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
  opacity: 1;
}

.eco-client-type-badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 850;
  line-height: 1;
  white-space: nowrap;
}

.eco-client-type-badge.is-new {
  color: #075985;
  background: #e0f2fe;
  border: 1px solid #bae6fd;
}

.eco-client-type-badge.is-regular {
  color: #047857;
  background: #dff7ed;
  border: 1px solid #b9ecd5;
}

.eco-client-type-badge.is-repeat {
  color: #9a3412;
  background: #ffedd5;
  border: 1px solid #fed7aa;
}

.eco-client-type-badge.is-unlinked {
