}

.eco-deal-card__history {
  display: grid;
  gap: 2px;
  margin-top: 10px;
  padding: 8px 9px;
  color: var(--eco-ink-2);
  background: #f8faf8;
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-deal-card__history span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-deal-card__history strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.eco-deal-card__notes {
  margin: 8px 0 0;
  padding: 7px 8px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border-radius: 2px;
  font-size: 11px;
  line-height: 1.35;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.eco-deal-card__expanded {
  display: grid;
  gap: 9px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px dashed var(--eco-line-dashed);
}

.eco-deal-card__details {
  display: grid;
  gap: 5px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 700;
}

.eco-deal-card__details span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-deal-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-deal-card__actions a,
.eco-deal-card__actions button {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  justify-content: center;
  padding: 0 9px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

.eco-deal-card__actions a:hover,
.eco-deal-card__actions button:hover {
  color: var(--eco-rust);
  border-color: #f0c2aa;
}

.eco-deal-card__move {
  margin-top: 0;
}

.eco-deal-card__move select {
  width: 100%;
  min-height: 30px;
  padding: 0 9px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 3px;
  font-size: 11px;
  font-weight: 700;
}

.eco-crm-mobile-list {
  display: none;
}

.eco-crm-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(4px);
}

.eco-crm-drawer {
  display: flex;
  flex-direction: column;
  width: min(840px, calc(100vw - 48px));
  height: 100vh;
  max-height: 100dvh;
  overflow: hidden;
  background: #fbfaf7;
  border-left: 1px solid var(--eco-line);
  box-shadow: -24px 0 70px rgba(15, 23, 42, 0.22);
}

.eco-crm-form-drawer {
  width: min(980px, calc(100vw - 48px));
}

.eco-crm-drawer__header,
.eco-crm-drawer__footer {
  background: rgba(255, 255, 255, 0.96);
  border-color: var(--eco-line);
