}

.eco-crm-drawer__header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  padding: 18px 22px 16px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-crm-drawer__header span {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-crm-drawer__header h2 {
  margin: 5px 0 0;
  color: var(--eco-ink);
  font-size: 25px;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1.16;
  overflow-wrap: anywhere;
}

.eco-crm-drawer__header p {
  margin: 7px 0 0;
  color: var(--eco-muted);
  font-size: 13px;
}

.eco-crm-drawer__badges,
.eco-crm-drawer__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.eco-crm-drawer__badges {
  margin-top: 10px;
}

.eco-crm-drawer__actions {
  padding: 12px 22px;
  background: #fff;
  border-bottom: 1px solid var(--eco-line);
}

.eco-crm-drawer__body,
.eco-crm-form-body {
  overflow: auto;
  padding: 18px 22px 24px;
}

.eco-crm-drawer__body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.eco-crm-wide-block {
  grid-column: 1 / -1;
}

.eco-crm-form-body {
  display: grid;
  gap: 14px;
}

.eco-crm-form-section {
  padding: 15px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-crm-form-section h3 {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0 0 12px;
  color: var(--eco-ink);
  font-size: 15px;
  font-weight: 850;
}

.eco-crm-drawer select.eco-input {
  padding-right: 34px;
  appearance: none;
  -webkit-appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--eco-muted) 50%),
    linear-gradient(135deg, var(--eco-muted) 50%, transparent 50%);
  background-repeat: no-repeat;
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-size: 5px 5px, 5px 5px;
}

.eco-crm-client-search {
  position: relative;
  margin-bottom: 12px;
}

.eco-crm-client-dropdown {
  top: calc(100% + 2px);
}

.eco-crm-check-row {
  max-width: none;
  min-height: 42px;
}

.eco-crm-integrations {
  padding: 13px 15px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-crm-integrations summary {
  cursor: pointer;
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 850;
}

.eco-crm-integrations .eco-check-row {
  max-width: none;
  margin-top: 12px;
}

.eco-crm-drawer__footer {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 14px 22px calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--eco-line);
}

.eco-crm-drawer__footer span {
  color: var(--eco-muted);
  font-size: 13px;
  font-weight: 750;
}

.eco-crm-drawer__footer > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.eco-crm-copy-line {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.eco-crm-copy-line button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-crm-related-link,
.eco-crm-related-row {
  display: grid;
  align-items: center;
  min-height: 38px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  text-decoration: none;
}

.eco-crm-related-link {
  place-items: center;
  margin-top: 12px;
  font-size: 13px;
  font-weight: 800;
}

.eco-crm-related-row {
  grid-template-columns: auto minmax(80px, 0.8fr) minmax(0, 1fr);
  gap: 8px;
  margin-top: 8px;
  padding: 8px 10px;
}

.eco-crm-related-row span {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 850;
}

.eco-crm-related-row strong {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
}

.eco-crm-reminder-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.eco-crm-reminder-actions button {
  min-height: 28px;
  padding: 0 9px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
}

.eco-crm-comment-box {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  margin-top: 12px;
  padding: 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border-radius: 6px;
}

.eco-crm-comment-box p {
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.eco-crm-history {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-crm-history div {
  padding: 11px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-crm-history span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-crm-history strong {
  display: block;
  margin-top: 5px;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-crm-history p {
  margin: 4px 0 0;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-crm-drawer-stage {
  min-width: 210px;
}

.eco-records-stack {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 14px;
}

.eco-journal-strip {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 2px;
}

.eco-journal-date-nav {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: 36px;
  padding: 2px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
}

.eco-journal-date-card {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 190px;
  height: 30px;
  padding: 0 12px;
  color: var(--eco-ink);
  cursor: pointer;
}

.eco-journal-date-card strong {
  display: block;
  font-size: 13px;
  line-height: 1.1;
}

.eco-journal-date-card small {
  display: block;
  margin-top: 2px;
  color: var(--eco-rust);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.eco-journal-date-card input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.eco-journal-statuses {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.eco-journal-statuses span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--eco-ink-2);
  font-size: 11px;
}

.eco-journal-statuses strong {
  color: var(--eco-muted);
  font-family: ui-monospace, monospace;
  font-size: 10px;
}

.eco-journal-free-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.eco-journal-free-strip > div {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 64px;
  padding: 12px 14px;
  background: var(--eco-surface-deep);
  border: 1px solid var(--eco-line);
  border-left: 3px solid var(--eco-muted);
  border-radius: 4px;
}

.eco-journal-free-strip > div.is-open {
  background: var(--eco-success-tint);
  border-color: var(--eco-success-tint-strong);
  border-left-color: var(--eco-success);
}

.eco-journal-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 50%;
  font-weight: 700;
}

.eco-journal-free-strip strong {
  display: block;
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-journal-free-strip p {
  margin: 3px 0 0;
  color: var(--eco-ink-2);
  font-size: 12px;
}

.eco-journal-free-strip b {
  color: var(--eco-success);
  font-family: ui-monospace, monospace;
}

.eco-journal-free-strip span {
  color: var(--eco-muted);
}

.eco-journal-error {
  padding: 9px 12px;
  background: var(--eco-danger-tint);
  border: 1px solid var(--eco-danger-tint-strong);
  border-radius: 4px;
}

.eco-records-page {
  --record-blue: #2563eb;
  --record-blue-soft: #eff6ff;
  --record-amber: #b45309;
  --record-amber-soft: #fff7ed;
  --record-orange: #ea580c;
  --record-orange-soft: #ffedd5;
  --record-green: #15803d;
  --record-green-soft: #ecfdf3;
  --record-red: #dc2626;
  --record-red-soft: #fef2f2;
}

.eco-records-head {
  align-items: center;
  padding: 18px 0 20px;
}

.eco-records-head .eco-page-actions .eco-btn,
.eco-records-head .eco-page-actions button {
  min-height: 38px;
}

.eco-records-toolbar,
.eco-records-filterbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-records-filterbar {
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.72);
}

.eco-records-date-nav {
  height: 40px;
}

.eco-records-date-picker {
  position: relative;
}

.eco-records-date-card {
  min-width: 242px;
  height: 34px;
}

.eco-records-date-trigger {
  display: flex;
  align-items: center;
  gap: 8px;
  color: inherit;
  text-align: left;
}

.eco-records-date-card strong {
  font-size: 14px;
}

.eco-records-month-popover {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 30;
  width: min(380px, calc(100vw - 32px));
  padding: 12px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 8px;
  box-shadow: 0 18px 54px rgba(10, 10, 10, 0.16);
}

.eco-records-month-head {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) 32px auto;
  gap: 8px;
  align-items: center;
}

.eco-records-month-head strong {
  color: var(--eco-ink);
  font-size: 14px;
  text-align: center;
  text-transform: capitalize;
}

.eco-records-month-head > button:last-child {
  height: 32px;
  padding: 0 9px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid rgba(194, 65, 12, 0.18);
  border-radius: 5px;
  font-size: 12px;
  font-weight: 800;
}

.eco-records-month-state {
  margin-top: 8px;
  padding: 8px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-radius: 5px;
  font-size: 12px;
}

.eco-records-month-state.is-error {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
}

.eco-records-month-weekdays,
.eco-records-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
}

.eco-records-month-weekdays {
  margin-top: 12px;
}

.eco-records-month-weekdays span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  text-align: center;
  text-transform: uppercase;
}

.eco-records-month-grid {
  margin-top: 6px;
}

.eco-records-month-day {
  display: grid;
  gap: 2px;
  min-height: 52px;
  padding: 6px;
  color: var(--eco-ink);
  background: #fff;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  text-align: left;
}

.eco-records-month-day span {
  font-size: 12px;
  font-weight: 850;
}

.eco-records-month-day strong {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}

.eco-records-month-day small {
  overflow: hidden;
  color: var(--eco-muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-records-month-day.is-free,
.eco-records-month-day.is-open {
  background: var(--eco-success-tint);
  border-color: #bbf7d0;
}

.eco-records-month-day.is-busy {
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-records-month-day.is-full {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-records-month-day.is-outside {
  opacity: 0.46;
}

.eco-records-month-day.is-selected {
  outline: 2px solid rgba(194, 65, 12, 0.42);
  outline-offset: 1px;
}

.eco-records-month-day.is-today span {
