}

.eco-records-month-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-month-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.eco-records-month-legend i {
  width: 8px;
  height: 8px;
  border-radius: 999px;
}

.eco-records-month-legend i.is-free {
  background: var(--eco-success);
}

.eco-records-month-legend i.is-busy {
  background: var(--eco-warning);
}

.eco-records-month-legend i.is-full {
  background: var(--eco-danger);
}

.eco-records-control {
  height: 38px;
  min-width: 206px;
}

.eco-records-search {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: min(100%, 330px);
  height: 38px;
  padding: 0 11px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
}

.eco-records-search input {
  min-width: 0;
  flex: 1;
  color: var(--eco-ink);
  background: transparent;
  border: 0;
  outline: none;
  font-size: 13px;
}

.eco-records-confirmed {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 38px;
  padding: 0 11px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid var(--eco-success-tint-strong, #bbf7d0);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
}

.eco-records-confirmed strong {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.eco-records-view-toggle {
  margin-left: auto;
}

.eco-records-view-toggle .eco-seg-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
}

.eco-records-statuses {
  margin-left: auto;
}

.eco-records-statuses i {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.eco-records-availability {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 10px;
}

.eco-records-availability-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 58px;
  padding: 10px 12px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-left: 3px solid var(--eco-faint);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-records-availability-item.is-open {
  background: linear-gradient(90deg, var(--eco-success-tint), #fff 68%);
  border-color: #bbf7d0;
  border-left-color: var(--eco-success);
}

.eco-records-availability-item span {
  display: block;
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-records-availability-item strong {
  display: block;
  margin-top: 2px;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-records-availability-item p {
  margin: 3px 0 0;
  color: var(--eco-ink-2);
  font-size: 12px;
}

.eco-records-availability-item b {
  color: var(--eco-success);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.eco-records-error {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border: 1px solid #fecaca;
  border-radius: 6px;
}

.eco-records-error strong {
  display: block;
  color: var(--eco-danger);
  font-size: 13px;
}

.eco-records-error p {
  margin: 2px 0 0;
  font-size: 12px;
}

.eco-records-layout {
  display: grid;
  grid-template-columns: minmax(720px, 1fr) minmax(360px, 400px);
  gap: 14px;
  align-items: start;
}

.eco-records-calendar,
.eco-records-details {
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-records-calendar {
  min-width: 0;
  overflow: visible;
}

.eco-records-empty-banner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  margin: 10px;
  padding: 10px 12px;
  color: var(--eco-ink-2);
  background: var(--eco-rust-tint);
  border: 1px dashed rgba(194, 65, 12, 0.34);
  border-radius: 6px;
}

.eco-records-empty-banner strong {
  display: block;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-records-empty-banner span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-records-details {
  position: sticky;
  top: calc(var(--eco-topbar-h) + var(--eco-substrip-h) + 16px);
  max-height: calc(100vh - var(--eco-topbar-h) - var(--eco-substrip-h) - 32px);
  overflow: auto;
  padding: 12px;
}

.eco-records-timeline-shell {
  overflow-x: auto;
  overflow-y: visible;
}

.eco-records-timeline {
  width: 100%;
}

.eco-records-timeline-head,
.eco-records-timeline-grid {
  display: grid;
}

.eco-records-timeline-head {
  position: sticky;
  z-index: 6;
  top: 0;
  background: #fbfaf7;
  border-bottom: 1px solid var(--eco-line);
}

.eco-records-timeline-head > div {
  min-width: 0;
  padding: 10px 12px;
  border-left: 1px solid var(--eco-line);
}

.eco-records-timeline-head > div:first-child {
  border-left: 0;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-records-timeline-head span {
  display: inline-flex;
  padding: 2px 6px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-radius: 3px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.eco-records-timeline-head strong {
  display: block;
  margin-top: 5px;
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-records-timeline-grid {
  position: relative;
  overflow: visible;
  background: #fffdf9;
}

.eco-records-time-axis {
  position: relative;
  z-index: 5;
  background: #f6f2ea;
  border-right: 1px solid var(--eco-line);
}

.eco-records-time-axis > div {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--eco-muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 800;
}

.eco-records-timeline-col {
  position: relative;
  min-width: 0;
  cursor: cell;
  background:
    linear-gradient(90deg, rgba(229, 226, 218, 0.62) 1px, transparent 1px),
    #fff;
  border-left: 1px solid var(--eco-line);
}

.eco-records-hour-line,
.eco-records-half-line {
  position: absolute;
  right: 0;
  left: 0;
  pointer-events: none;
}

.eco-records-hour-line {
  border-top: 1px solid rgba(200, 194, 179, 0.42);
}

.eco-records-half-line {
  border-top: 1px dashed rgba(229, 226, 218, 0.48);
}

.eco-records-hover-slot {
  position: absolute;
  right: 8px;
  left: 8px;
  z-index: 2;
  pointer-events: none;
  background: rgba(194, 65, 12, 0.08);
  border: 1px dashed rgba(194, 65, 12, 0.42);
  border-radius: 5px;
}

.eco-records-hover-slot span {
  position: absolute;
  top: 6px;
  right: 8px;
  padding: 3px 7px;
  color: var(--eco-rust);
  background: #fff;
  border: 1px solid rgba(194, 65, 12, 0.24);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
}

.eco-records-drag-target {
  position: absolute;
  right: 8px;
  left: 8px;
  z-index: 7;
  display: grid;
  align-content: start;
  gap: 3px;
  padding: 7px 9px;
  pointer-events: none;
  color: var(--eco-rust);
  background: rgba(194, 65, 12, 0.12);
  border: 1px solid rgba(194, 65, 12, 0.44);
  border-radius: 6px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.56);
}

.eco-records-drag-target span {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 900;
}

.eco-records-drag-target strong {
  font-size: 11px;
  font-weight: 850;
}

.eco-records-now-line {
  position: absolute;
  right: 0;
  z-index: 1;
  pointer-events: none;
  border-top: 1px solid rgba(220, 38, 38, 0.48);
}

.eco-records-now-line::before {
  position: absolute;
  top: -4px;
  left: -4px;
  width: 7px;
  height: 7px;
  content: "";
  background: #dc2626;
  border-radius: 999px;
}

.eco-records-now-label {
  position: absolute;
  right: 8px;
  z-index: 7;
  transform: translateY(-50%);
  padding: 2px 6px;
  color: #fff;
  background: #dc2626;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
}

.eco-record-card {
  position: absolute;
  right: 8px;
  left: 8px;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 8px 10px;
  overflow: hidden;
  color: var(--eco-ink);
  background: var(--record-blue-soft);
  border: 1px solid #bfdbfe;
  border-left: 4px solid var(--record-blue);
  border-radius: 6px;
  box-shadow: 0 6px 14px rgba(15, 23, 42, 0.06);
  text-align: left;
  touch-action: none;
}

.eco-record-card:hover {
  z-index: 5;
  border-color: rgba(10, 10, 10, 0.2);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.12);
}

.eco-record-card.is-selected {
  z-index: 6;
  background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.5), transparent);
  outline: 2px solid rgba(194, 65, 12, 0.42);
  outline-offset: 1px;
}

.eco-record-card.is-overlap {
  padding-right: 7px;
  padding-left: 7px;
}

.eco-record-card.is-interacting {
  opacity: 0.42;
}

.eco-record-card__resize {
  position: absolute;
  right: 8px;
  bottom: 3px;
  left: 8px;
  height: 8px;
  cursor: ns-resize;
}

.eco-record-card__resize::after {
  position: absolute;
  right: calc(50% - 14px);
  bottom: 2px;
  width: 28px;
  height: 3px;
  content: "";
  background: rgba(15, 23, 42, 0.22);
  border-radius: 999px;
}

.eco-record-card__time {
  color: var(--eco-ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 900;
}

.eco-record-card__service {
  display: -webkit-box;
  overflow: hidden;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.18;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  text-overflow: ellipsis;
  white-space: normal;
}

.eco-record-card__client,
.eco-record-card small,
.eco-record-card i {
  overflow: hidden;
  color: var(--eco-ink-3);
  font-size: 11px;
  font-style: normal;
  line-height: 1.22;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-record-card i {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.eco-record-card__case {
  align-self: flex-start;
  max-width: 100%;
  padding: 2px 5px;
  overflow: hidden;
  color: var(--eco-rust);
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 4px;
  font-size: 9px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.eco-record-card--normal .eco-record-card__service {
  -webkit-line-clamp: 2;
}

.eco-record-card--compact {
  padding: 6px 8px;
}

.eco-record-card--compact .eco-record-card__service,
.eco-record-card--mini .eco-record-card__service {
  display: block;
  white-space: nowrap;
  -webkit-line-clamp: 1;
}

.eco-record-card--compact small,
.eco-record-card--compact i,
.eco-record-card--compact .eco-record-card__case,
.eco-record-card--mini small,
.eco-record-card--mini i,
.eco-record-card--mini .eco-record-card__case {
  display: none;
}

.eco-record-card--mini {
  gap: 1px;
  padding: 5px 7px;
  border-left-width: 3px;
}

.eco-record-card--mini .eco-record-card__time {
  font-size: 10px;
}

.eco-record-card--mini .eco-record-card__service,
.eco-record-card--mini .eco-record-card__client {
  font-size: 11px;
  line-height: 1.12;
}

.eco-record-card--confirmed,
.eco-record-card--arrived {
  background: var(--record-green-soft);
  border-color: #bbf7d0;
  border-left-color: var(--record-green);
}

.eco-record-card--waiting,
.eco-record-card--new {
  background: var(--record-blue-soft);
  border-color: #bfdbfe;
  border-left-color: var(--record-blue);
}

.eco-record-card--in_work {
  background: var(--record-orange-soft);
  border-color: #fed7aa;
  border-left-color: var(--record-orange);
}

.eco-record-card--done,
.eco-record-card--cancelled {
  background: #f8fafc;
  border-color: #e2e8f0;
  border-left-color: #64748b;
}

.eco-record-card--no_show {
  background: var(--record-red-soft);
  border-color: #fecaca;
  border-left-color: var(--record-red);
}

.eco-record-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.eco-record-status--confirmed,
.eco-record-status--arrived {
  color: var(--record-green);
  background: var(--record-green-soft);
  border: 1px solid #bbf7d0;
}

.eco-record-status--new,
.eco-record-status--waiting {
  color: var(--record-blue);
  background: var(--record-blue-soft);
  border: 1px solid #bfdbfe;
}

.eco-record-status--in_work {
  color: var(--record-orange);
  background: var(--record-orange-soft);
  border: 1px solid #fed7aa;
}

.eco-record-status--done,
.eco-record-status--cancelled {
  color: #475569;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.eco-record-status--no_show {
  color: var(--record-red);
  background: var(--record-red-soft);
  border: 1px solid #fecaca;
}

.eco-records-list {
  overflow: auto;
}

.eco-records-list table {
  width: 100%;
  min-width: 1040px;
  border-collapse: collapse;
  font-size: 12px;
}

.eco-records-list th,
.eco-records-list td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--eco-line);
  text-align: left;
  vertical-align: top;
}

.eco-records-list th {
  color: var(--eco-muted);
  background: #fbfaf7;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-records-list tr.is-selected td {
  background: var(--eco-rust-tint);
}

.eco-records-list a,
.eco-records-list button {
  color: var(--eco-rust);
  background: transparent;
  border: 0;
  font-weight: 800;
  text-decoration: none;
}

.eco-records-empty,
.eco-records-details-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 420px;
  padding: 28px;
  color: var(--eco-muted);
  text-align: center;
}

.eco-records-empty strong,
.eco-records-details-empty strong {
  color: var(--eco-ink);
  font-size: 16px;
}

.eco-records-empty p,
.eco-records-details-empty p {
  max-width: 360px;
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.eco-records-details-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.eco-records-details-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  background: #fbfaf7;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-records-details-head span:first-child {
  display: block;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-details-head strong {
  display: block;
  margin-top: 4px;
  color: var(--eco-ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 20px;
  line-height: 1.1;
}

.eco-records-detail-block {
  padding: 12px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-records-section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-records-section-title > div {
  margin-left: auto;
}

.eco-records-section-title a,
.eco-records-section-title button {
  color: var(--eco-rust);
  background: transparent;
  border: 0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
  text-decoration: none;
  text-transform: none;
}

.eco-records-section-title button:disabled,
.eco-records-list button:disabled,
.eco-records-empty-inline button:disabled {
  cursor: wait;
  opacity: 0.62;
}

.eco-records-detail-main strong,
.eco-records-detail-main span {
  display: block;
}

.eco-records-detail-main strong {
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-records-detail-main span {
  margin-top: 4px;
  color: var(--eco-ink-2);
  font-size: 13px;
}

.eco-records-inline-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  min-height: 28px;
  padding: 0 9px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
}

.eco-records-detail-list {
  display: grid;
  gap: 8px;
  margin: 0;
}

.eco-records-detail-list div {
  display: grid;
  grid-template-columns: 94px minmax(0, 1fr);
  gap: 8px;
}

.eco-records-detail-list dt {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-detail-list dd {
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 700;
}

.eco-records-services-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-records-services-list span {
  padding: 5px 8px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
}

.eco-records-muted,
.eco-records-detail-block p,
.eco-records-detail-block small {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.45;
}

.eco-records-warning {
  color: var(--eco-danger);
  font-size: 12px;
}

.eco-records-empty-inline {
  display: grid;
  gap: 8px;
  padding: 10px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 5px;
  font-size: 12px;
}

.eco-records-empty-inline a,
.eco-records-empty-inline button {
  color: var(--eco-rust);
  background: transparent;
  border: 0;
  font-weight: 800;
  text-decoration: none;
  text-align: left;
}

.eco-records-shipment-list {
  display: grid;
  gap: 7px;
}

.eco-records-shipment-list a {
  display: grid;
  gap: 3px;
  padding: 9px;
  color: inherit;
  background: #fbfaf7;
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  text-decoration: none;
}

.eco-records-shipment-list a:hover {
  border-color: var(--eco-line-strong);
}

.eco-records-shipment-list strong {
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-records-shipment-list span {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-case-link {
  display: grid;
  gap: 4px;
  padding: 9px;
  color: inherit;
  background: #fbfaf7;
  border: 1px solid var(--eco-line);
  border-radius: 5px;
}

.eco-records-case-link strong {
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-records-case-link span,
.eco-records-case-link small {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-detail-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.eco-records-detail-actions .eco-btn {
  width: 100%;
  min-height: 34px;
}

.eco-records-drawer-backdrop,
.eco-records-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.38);
}

.eco-records-modal-backdrop {
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.eco-records-drawer {
  display: flex;
  width: min(760px, 100vw);
  height: 100%;
  flex-direction: column;
  background: var(--eco-surface);
  box-shadow: -18px 0 48px rgba(15, 23, 42, 0.18);
}

.eco-records-drawer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-records-drawer-head span {
  display: block;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-records-drawer-head strong {
  display: block;
  margin-top: 4px;
  color: var(--eco-ink);
  font-size: 18px;
}

.eco-records-drawer-head button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-records-form {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  padding: 14px 18px 18px;
  overflow: auto;
  background: #fbfaf7;
}

.eco-records-form section {
  padding: 12px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-records-form-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-records-form label {
  display: grid;
  gap: 6px;
  color: var(--eco-ink-2);
  font-size: 12px;
  font-weight: 800;
}

.eco-records-form input,
.eco-records-form select,
.eco-records-form textarea {
  width: 100%;
  min-height: 36px;
  padding: 0 10px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 13px;
  outline: none;
}

.eco-records-form textarea {
  min-height: 72px;
  padding-top: 9px;
  resize: vertical;
}

.eco-records-form input:focus,
.eco-records-form select:focus,
.eco-records-form textarea:focus {
  border-color: var(--eco-rust);
  box-shadow: 0 0 0 2px rgba(194, 65, 12, 0.12);
}

.eco-records-availability-check {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  margin-top: 10px;
  padding: 10px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid #bbf7d0;
  border-radius: 5px;
}

.eco-records-availability-check.is-warning,
.eco-records-availability-check:has(.eco-records-overlap) {
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-records-availability-check strong {
  display: block;
  color: currentColor;
  font-size: 12px;
}

.eco-records-availability-check p {
  margin: 3px 0 0;
  color: var(--eco-ink-2);
  font-size: 12px;
}

.eco-records-slot-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.eco-records-slot-suggestions button {
  min-height: 28px;
  padding: 0 8px;
  color: var(--eco-rust);
  background: #fff;
  border: 1px solid rgba(194, 65, 12, 0.28);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
}

.eco-records-overlap {
  display: flex !important;
  grid-template-columns: none !important;
  align-items: center;
  gap: 8px !important;
  margin-top: 8px;
  color: var(--eco-ink-2) !important;
}

.eco-records-overlap input {
  width: 16px;
  min-height: 16px;
  padding: 0;
}

.eco-records-service-picker,
.eco-records-client-options,
.eco-records-status-picker {
  display: grid;
  gap: 7px;
}

.eco-records-service-picker {
  max-height: 246px;
  overflow: auto;
}

.eco-records-client-field {
  position: relative;
}

.eco-records-service-picker button,
.eco-records-client-options button {
  display: grid;
  gap: 3px;
  padding: 9px 10px;
  color: var(--eco-ink-2);
  background: #fbfaf7;
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  text-align: left;
}

.eco-records-service-picker button.is-selected,
.eco-records-client-options button.is-selected {
  color: var(--eco-ink);
  background: var(--eco-rust-tint);
  border-color: rgba(194, 65, 12, 0.34);
}

.eco-records-service-picker strong,
.eco-records-client-options strong {
  color: inherit;
  font-size: 12px;
}

.eco-records-service-picker span,
.eco-records-client-options span {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-records-client-options {
  margin: 8px 0 10px;
}

.eco-records-client-history {
  display: grid;
  gap: 5px;
  margin-top: 8px;
  padding: 9px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  font-size: 11px;
}

.eco-records-client-history strong {
  color: var(--eco-ink);
}

.eco-records-client-history a {
  color: var(--eco-rust);
  font-weight: 800;
  text-decoration: none;
}

.eco-records-status-picker {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.eco-records-status-picker button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  color: var(--eco-ink-2);
  background: #fbfaf7;
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
}

.eco-records-status-picker button.is-selected {
  background: var(--eco-surface);
  border-color: var(--eco-line-strong);
  box-shadow: inset 0 0 0 1px var(--eco-rust);
}

.eco-records-status-picker i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.eco-records-form-error {
  padding: 10px;
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border: 1px solid #fecaca;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 800;
}

.eco-records-drawer-footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 18px;
  background: var(--eco-surface);
  border-top: 1px solid var(--eco-line);
}

.eco-records-comment-modal {
  width: min(560px, 100%);
  max-height: min(640px, 90vh);
  overflow: hidden;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-md);
}

.eco-records-comment-body {
  display: grid;
  gap: 12px;
  padding: 16px;
}

.eco-records-comment-body p,
.eco-records-comment-body small {
  margin: 0;
  white-space: pre-wrap;
  color: var(--eco-ink-2);
  font-size: 13px;
  line-height: 1.5;
}

.eco-records-comment-body small {
  padding-top: 12px;
  color: var(--eco-muted);
  border-top: 1px solid var(--eco-line);
}

.eco-records-toast {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 90;
  padding: 11px 14px;
  color: #fff;
  background: var(--eco-ink);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-md);
  font-size: 13px;
  font-weight: 800;
}

.eco-records-skeleton {
  min-height: 40px;
  background: linear-gradient(90deg, #f0ede6 25%, #faf8f3 37%, #f0ede6 63%);
  background-size: 400% 100%;
  border-radius: 6px;
  animation: eco-skeleton 1.4s ease infinite;
}

.eco-records-mobile-cards {
  display: none;
}

.eco-records-mobile-card {
  display: grid;
  gap: 4px;
  width: 100%;
  padding: 12px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  text-align: left;
}

.eco-records-mobile-card.is-selected {
  border-color: var(--eco-rust);
  box-shadow: inset 0 0 0 1px rgba(194, 65, 12, 0.2);
}

.eco-records-mobile-card span {
  color: var(--eco-muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 900;
}

.eco-records-mobile-card strong {
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-records-mobile-card small {
  color: var(--eco-ink-3);
  font-size: 12px;
}

.eco-records-mobile-card em {
  justify-self: flex-start;
  padding: 3px 6px;
  color: var(--eco-rust);
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 4px;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.eco-spin {
  animation: eco-spin 0.8s linear infinite;
}

@keyframes eco-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes eco-skeleton {
  0% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0 50%;
  }
}

.eco-salary-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 16px;
}

.eco-salary-tabs {
  margin-bottom: 20px;
}

.eco-salary-content {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.eco-salary-section {
  scroll-margin-top: calc(var(--eco-topbar-h) + var(--eco-substrip-h) + 20px);
}

.eco-salary-section-head {
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-salary-section-head .eco-page-title {
  font-size: 20px;
}

.eco-payroll-page {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.eco-payroll-head {
  align-items: flex-start;
  margin-bottom: 0;
}

.eco-payroll-head-actions {
  align-items: stretch;
  min-width: fit-content;
}

.eco-payroll-mode {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-height: 36px;
  padding: 2px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-payroll-mode button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 11px;
  color: var(--eco-ink-3);
  background: transparent;
  border: 0;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.eco-payroll-mode button.is-active {
  color: var(--eco-ink);
  background: var(--eco-surface);
  box-shadow: var(--eco-shadow-sm);
}

.eco-payroll-mode button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.eco-payroll-metrics {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  margin-bottom: 0;
}

.eco-payroll-context {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 9px 12px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-size: 12px;
}

.eco-payroll-context strong {
  color: var(--eco-ink);
}

.eco-payroll-tabs {
  margin-bottom: 0;
}

.eco-payroll-toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 90;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  max-width: min(420px, calc(100vw - 24px));
  min-height: 42px;
  padding: 0 14px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid #bbf7d0;
  border-radius: 6px;
  box-shadow: var(--eco-shadow-md);
  font-size: 13px;
  font-weight: 700;
}

.eco-payroll-workspace {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-payroll-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-payroll-toolbar p {
  margin: 5px 0 0;
  color: var(--eco-muted);
  font-size: 13px;
}

.eco-payroll-controls {
  display: flex;
  align-items: flex-end;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.eco-payroll-field {
  display: grid;
  gap: 5px;
  min-width: 132px;
}

.eco-payroll-field > span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-payroll-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-payroll-presets button,
.eco-payroll-employee-strip button {
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}

.eco-payroll-presets button:hover,
.eco-payroll-employee-strip button:hover {
  background: var(--eco-hover);
}

.eco-payroll-progress,
.eco-payroll-error {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 12px;
  border-radius: 6px;
  font-size: 13px;
}

.eco-payroll-progress {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid #ffd6c2;
}

.eco-payroll-error {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border: 1px solid #fecaca;
}

.eco-payroll-error > div {
  display: grid;
  gap: 3px;
  min-width: 0;
  flex: 1;
}

.eco-payroll-error span {
  color: #991b1b;
}

.eco-payroll-problems {
  display: grid;
  gap: 12px;
  padding: 12px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 6px;
}

.eco-payroll-problems__head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: var(--eco-warning);
}

.eco-payroll-problems__head div {
  display: grid;
  gap: 3px;
}

.eco-payroll-problems__head span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-payroll-problem-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 8px;
}

.eco-payroll-problem-list > div {
  display: grid;
  gap: 3px;
  padding: 10px;
  background: var(--eco-surface);
  border: 1px solid #fed7aa;
  border-left: 3px solid var(--eco-warning);
  border-radius: 4px;
}

.eco-payroll-problem-list > div.is-danger {
  border-color: #fecaca;
  border-left-color: var(--eco-danger);
}

.eco-payroll-problem-list strong {
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-payroll-problem-list span {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
}

.eco-payroll-skeleton {
  display: grid;
  gap: 8px;
}

.eco-payroll-skeleton span {
  height: 48px;
  overflow: hidden;
  background: linear-gradient(90deg, var(--eco-surface-sunk), var(--eco-surface-deep), var(--eco-surface-sunk));
  background-size: 200% 100%;
  border-radius: 4px;
  animation: eco-payroll-shimmer 1.25s ease-in-out infinite;
}

@keyframes eco-payroll-shimmer {
  to {
    background-position-x: -200%;
  }
}

.eco-payroll-empty {
  display: grid;
  justify-items: start;
  gap: 8px;
  padding: 28px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 6px;
}

.eco-payroll-empty strong {
  color: var(--eco-ink);
  font-size: 16px;
}

.eco-payroll-empty span {
  font-size: 13px;
}

.eco-payroll-table-wrap,
.eco-payroll-rules-table-wrap {
  overflow-x: auto;
}

.eco-payroll-table {
  min-width: 1280px;
}

.eco-payroll-table .is-num,
.eco-payroll-rules-table .is-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.eco-payroll-table .is-strong {
  color: var(--eco-ink);
  font-weight: 800;
}

.eco-payroll-table .is-positive {
  color: var(--eco-success);
}

.eco-payroll-table .is-negative {
  color: var(--eco-danger);
}

.eco-payroll-table .is-actions {
  width: 44px;
  text-align: right;
}

.eco-payroll-clickable-row {
  cursor: pointer;
}

.eco-payroll-person {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
}

.eco-payroll-person > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  color: var(--eco-ink);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
  flex: 0 0 auto;
}

.eco-payroll-person strong,
.eco-payroll-rules-table strong {
  display: block;
  color: var(--eco-ink);
  overflow-wrap: anywhere;
}

.eco-payroll-person small,
.eco-payroll-rules-table small {
  display: block;
  margin-top: 2px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-payroll-close-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-payroll-close-row div {
  display: grid;
  gap: 4px;
}

.eco-payroll-close-row span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-payroll-month-nav {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-height: 36px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
}

.eco-payroll-month-nav button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 0;
}

.eco-payroll-month-nav strong {
  min-width: 170px;
  padding: 0 8px;
  text-align: center;
  text-transform: capitalize;
}

.eco-payroll-employee-strip {
  display: flex;
  gap: 8px;
  padding-bottom: 2px;
  overflow-x: auto;
}

.eco-payroll-employee-strip button.is-active {
  color: #fff;
  background: var(--eco-rust);
  border-color: var(--eco-rust);
}

.eco-payroll-calendar-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.eco-payroll-calendar-filters {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-payroll-calendar-filters button {
  min-height: 28px;
  padding: 0 10px;
  color: var(--eco-ink-3);
  background: transparent;
  border: 0;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.eco-payroll-calendar-filters button.is-active {
  color: var(--eco-ink);
  background: var(--eco-surface);
  box-shadow: var(--eco-shadow-sm);
}

.eco-payroll-save-state {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 750;
}

.eco-payroll-save-state.is-saving,
.eco-payroll-save-state.is-dirty {
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-payroll-save-state.is-saved {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: #bbf7d0;
}

.eco-payroll-selection-tools {
  display: grid;
  gap: 8px;
  padding: 10px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-payroll-quick-select,
.eco-payroll-bulk-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-payroll-month-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--eco-line-strong);
}

.eco-payroll-calendar-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(320px, 0.55fr);
  gap: 16px;
  align-items: start;
}

.eco-payroll-calendar-shell {
  display: grid;
  gap: 12px;
}

.eco-payroll-calendar-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-payroll-calendar-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.eco-payroll-calendar-legend i,
.eco-payroll-calendar-day i {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.eco-payroll-calendar-legend i.is-working,
.eco-payroll-calendar-day.has-working i {
  background: var(--eco-success);
}

.eco-payroll-calendar-legend i.is-actual,
.eco-payroll-calendar-day.has-actual i {
  background: var(--eco-info);
}

.eco-payroll-calendar-legend i.is-absence,
.eco-payroll-calendar-day.has-absence i {
  background: var(--eco-warning);
}

.eco-payroll-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}

