  padding: 0 10px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid #ffd6c2;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 760;
}

.eco-receipt-result-panel,
.eco-receipt-product-results {
  margin-top: 10px;
  overflow: hidden;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-receipt-result-hint,
.eco-receipt-empty-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  color: var(--eco-muted);
  font-size: 13px;
}

.eco-receipt-result-hint.is-error {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
}

.eco-receipt-counterparty-row {
  display: block;
  width: 100%;
  padding: 11px 12px;
  text-align: left;
  border-top: 1px solid var(--eco-line);
}

.eco-receipt-counterparty-row:hover {
  background: var(--eco-surface-sunk);
}

.eco-receipt-counterparty-row strong {
  display: block;
  color: var(--eco-ink);
  font-weight: 760;
}

.eco-receipt-counterparty-row span {
  display: block;
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-supplier-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--eco-line);
}

.eco-receipt-supplier-actions label {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  color: var(--eco-ink-2);
  font-size: 13px;
  font-weight: 720;
}

.eco-receipt-mini-form {
  margin-top: 12px;
  padding: 12px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-receipt-mini-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  grid-column: 1 / -1;
}

.eco-receipt-product-row {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto auto;
  gap: 14px;
  align-items: center;
  padding: 12px;
  border-top: 1px solid var(--eco-line);
}

.eco-receipt-product-row:first-child {
  border-top: 0;
}

.eco-receipt-product-row:hover {
  background: var(--eco-surface-sunk);
}

.eco-receipt-product-row strong {
  display: block;
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 760;
}

.eco-receipt-product-row span {
  display: block;
  margin-top: 4px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-product-row dl {
  display: grid;
  grid-template-columns: repeat(4, auto);
  gap: 12px;
  margin: 0;
}

.eco-receipt-product-row dt {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-receipt-product-row dd {
  margin: 2px 0 0;
  color: var(--eco-ink);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  font-weight: 760;
}

.eco-receipt-product-skeleton {
  height: 58px;
  margin: 10px 12px;
}

.eco-receipt-bulk-cells {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  justify-content: flex-end;
}

.eco-receipt-bulk-cells > button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-3);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 760;
}

.eco-receipt-bulk-cells > button:not(:disabled):hover {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
}

.eco-receipt-bulk-cells > button:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

.eco-receipt-cell-editor-host {
  margin: -4px 0 12px;
}

.eco-receipt-cell-popover {
  z-index: 2;
  display: grid;
  gap: 10px;
  width: min(100%, 460px);
  padding: 12px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-md);
}

.eco-receipt-bulk-cells .eco-receipt-cell-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 380px;
}

.eco-receipt-cell-popover-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.eco-receipt-cell-popover-head strong {
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 780;
}

.eco-receipt-cell-popover-head button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-receipt-cell-search,
.eco-receipt-cell-create {
  display: grid;
  gap: 6px;
}

.eco-receipt-cell-search {
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  min-height: 36px;
  padding: 0 10px;
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-receipt-cell-search svg {
  color: var(--eco-muted);
}

.eco-receipt-cell-search input,
.eco-receipt-cell-create input {
  width: 100%;
  height: 34px;
  color: var(--eco-ink);
  background: transparent;
  border: 0;
  outline: none;
}

.eco-receipt-cell-create {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-receipt-cell-create input {
  padding: 0 10px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: none;
}

.eco-receipt-cell-options {
  display: grid;
  gap: 6px;
  max-height: 180px;
  overflow: auto;
}

.eco-receipt-cell-options > span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-cell-options button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 34px;
  padding: 7px 9px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  text-align: left;
}

.eco-receipt-cell-options button.is-active,
.eco-receipt-cell-options button:hover {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
}

.eco-receipt-cell-options strong {
  font-size: 12px;
  font-weight: 780;
}

.eco-receipt-cell-options em {
  color: var(--eco-muted);
  font-size: 11px;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.eco-receipt-cell-checkbox {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  color: var(--eco-ink-2);
  font-size: 12px;
  font-weight: 720;
}

.eco-receipt-cell-warning {
  padding: 8px 9px;
  color: #92400e;
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 4px;
  font-size: 12px;
  line-height: 1.35;
}

.eco-receipt-cell-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.eco-receipt-cell-actions button {
  height: 30px;
  padding: 0 11px;
  color: var(--eco-ink-3);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 760;
}

.eco-receipt-cell-actions button.is-primary {
  color: #fff;
  background: var(--eco-rust);
  border-color: var(--eco-rust);
}

.eco-receipt-position-table {
  overflow: auto;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-receipt-position-table table {
  width: 100%;
  min-width: 1040px;
  border-collapse: separate;
  border-spacing: 0;
}

.eco-receipt-position-table th {
  height: 34px;
  padding: 8px 10px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-bottom: 1px solid var(--eco-line-strong);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-align: left;
  text-transform: uppercase;
}

.eco-receipt-position-table td {
  padding: 10px;
  background: var(--eco-surface);
  border-bottom: 1px solid var(--eco-line);
  vertical-align: middle;
}

.eco-receipt-position-table tr:last-child td {
  border-bottom: 0;
}

.eco-receipt-position-table tr.is-selected td {
  background: #fff7ed;
}

.eco-receipt-select-col {
  width: 42px;
}

.eco-receipt-select-cell {
  width: 42px;
  text-align: center;
}

.eco-receipt-select-cell button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-receipt-select-cell button.is-selected {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
}

.eco-receipt-position-table td strong {
  display: block;
  color: var(--eco-ink);
  font-weight: 760;
}

.eco-receipt-position-table td span {
  display: block;
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-position-table input:not(.eco-input) {
  width: 92px;
  height: 34px;
  padding: 0 8px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.eco-receipt-position-table .eco-input.l-money {
  width: 118px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.eco-receipt-position-table .l-sum {
  color: var(--eco-ink);
  font-weight: 780;
  text-align: right;
  white-space: nowrap;
}

.eco-receipt-product-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  color: var(--eco-ink);
  text-decoration: none;
}

.eco-receipt-product-link:hover {
  color: var(--eco-rust);
}

.eco-receipt-product-link strong {
  overflow: hidden;
  text-overflow: ellipsis;
}

.eco-receipt-cell-cell {
  min-width: 150px;
}

.eco-receipt-cell-wrap {
  display: grid;
  gap: 4px;
  justify-items: start;
}

.eco-receipt-cell-wrap small {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-receipt-cell-wrap small.is-danger {
  color: var(--eco-danger);
}

.eco-receipt-cell-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  max-width: 150px;
  padding: 0 8px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 760;
  white-space: nowrap;
}

.eco-receipt-cell-pill:not(:disabled):hover {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
}

.eco-receipt-cell-pill.is-missing {
  color: #92400e;
  background: #fffbeb;
  border-color: #fde68a;
}

.eco-receipt-cell-pill.is-wrong-store {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-receipt-cell-pill:disabled {
  cursor: default;
}

.eco-receipt-cell-pill span {
  overflow: hidden;
  margin: 0;
  color: inherit;
  text-overflow: ellipsis;
}

.eco-receipt-cell-pill em {
  color: inherit;
  font-size: 11px;
  font-style: normal;
  opacity: 0.78;
}

.eco-receipt-empty-positions {
  display: grid;
  justify-items: center;
  gap: 7px;
  padding: 36px 16px;
  color: var(--eco-muted);
  text-align: center;
  background: var(--eco-surface);
}

.eco-receipt-empty-positions strong {
  color: var(--eco-ink);
  font-size: 15px;
}

.eco-receipt-empty-positions span {
  max-width: 430px;
  font-size: 13px;
}

.eco-receipt-position-cards {
  display: none;
}

.eco-receipt-summary {
  position: sticky;
  top: 0;
  align-self: start;
  padding: 16px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-receipt-summary > span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.eco-receipt-summary dl {
  display: grid;
  gap: 10px;
  margin: 12px 0 0;
}

.eco-receipt-summary div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-receipt-summary dt {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-summary dd {
  margin: 0;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 760;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.eco-receipt-drawer-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 18px;
  border-top: 1px solid var(--eco-line);
}

.eco-receipt-drawer-footer > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.eco-receipt-drawer-footer strong {
  color: var(--eco-ink);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}

.eco-receipt-drawer-footer span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-receipt-footer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.eco-receipt-conduct-btn:not(:disabled) {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: #86efac;
}

.eco-receipt-conduct-btn:not(:disabled):hover {
  background: #bbf7d0;
}

.eco-receipt-page .l-money,
.eco-receipt-page .l-number,
.eco-receipt-page .l-mono {
  font-variant-numeric: tabular-nums;
}

@media (max-width: 1280px) {
  .eco-receipt-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .eco-receipt-drawer {
    width: 100vw;
  }

  .eco-receipt-drawer-body {
    grid-template-columns: 1fr;
  }

  .eco-receipt-summary {
    position: static;
  }

  .eco-receipt-details {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .eco-receipt-head {
    align-items: stretch;
    padding: 16px;
  }

  .eco-receipt-kpis {
    grid-template-columns: 1fr;
  }

  .eco-receipt-state-card {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .eco-receipt-state-card .eco-btn {
    grid-column: 1 / -1;
    width: 100%;
  }

  .eco-receipt-journal-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .eco-receipt-journal-head .l-meta,
  .eco-receipt-journal-head .eco-row-actions,
  .eco-receipt-journal-head .eco-row-actions .eco-btn {
    width: 100%;
  }

  .eco-receipt-doc-table {
    min-width: 920px;
  }

  .eco-receipt-drawer-head {
    padding: 15px 16px;
  }

  .eco-receipt-drawer-body {
    padding: 12px;
  }

  .eco-receipt-drawer-head h2 {
    font-size: 19px;
  }

  .eco-receipt-form-section {
    padding: 14px;
  }

  .eco-receipt-param-grid,
  .eco-receipt-invoice-grid,
  .eco-receipt-mini-form {
    grid-template-columns: 1fr;
  }

  .eco-receipt-product-row {
    grid-template-columns: 1fr;
  }

  .eco-receipt-product-row dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-receipt-position-table {
    display: none;
  }

  .eco-receipt-position-cards {
    display: grid;
    gap: 10px;
  }

  .eco-receipt-position-card {
    display: grid;
    gap: 10px;
    padding: 12px;
    background: var(--eco-surface);
    border: 1px solid var(--eco-line);
    border-radius: 6px;
  }

  .eco-receipt-position-card > div:first-child strong {
    display: block;
    color: var(--eco-ink);
    font-weight: 760;
  }

  .eco-receipt-position-card > div:first-child span {
    display: block;
    margin-top: 3px;
    color: var(--eco-muted);
    font-size: 12px;
  }

  .eco-receipt-card-cell {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 8px 0;
    border-top: 1px solid var(--eco-line);
    border-bottom: 1px solid var(--eco-line);
  }

  .eco-receipt-position-card label {
    display: grid;
    gap: 5px;
    color: var(--eco-muted);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .eco-receipt-position-card input:not(.eco-input),
  .eco-receipt-position-card .eco-input {
    width: 100%;
    height: 36px;
    padding: 0 10px;
    border: 1px solid var(--eco-line-strong);
    border-radius: 4px;
    font-variant-numeric: tabular-nums;
  }

  .eco-receipt-position-card-total {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding-top: 8px;
    border-top: 1px solid var(--eco-line);
  }

  .eco-receipt-position-card-total span {
    color: var(--eco-muted);
    font-size: 12px;
  }

  .eco-receipt-position-card-total strong {
    color: var(--eco-ink);
    font-variant-numeric: tabular-nums;
  }

  .eco-receipt-position-card > button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 34px;
    color: var(--eco-danger);
    background: var(--eco-danger-tint);
    border: 1px solid #fecaca;
    border-radius: 4px;
    font-weight: 760;
  }

  .eco-receipt-drawer-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-receipt-footer-actions,
  .eco-receipt-footer-actions .eco-btn {
    width: 100%;
  }
}

.eco-restock-page {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.eco-restock-head {
  margin-top: 8px;
  margin-bottom: 0;
}

.eco-restock-metrics {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.eco-restock-summary-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 36px;
  padding: 8px 12px;
  color: var(--eco-ink-3);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 760;
}

.eco-restock-summary-strip em {
  color: var(--eco-muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
  white-space: nowrap;
}

.eco-restock-category-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  overflow-x: auto;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-restock-category-tab {
