.eco-diagnostic-live-offers li.is-added {
  border-color: #bbf7d0;
}

.eco-diagnostic-live-offers li b {
  display: block;
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 900;
}

.eco-diagnostic-live-offer-price {
  color: var(--eco-ink-2) !important;
  font-weight: 850 !important;
}

.eco-diagnostic-live-offers em {
  color: var(--eco-success);
  font-size: 12px;
  font-style: normal;
  font-weight: 900;
}

.eco-diagnostic-live-offer-actions {
  display: grid;
  gap: 6px;
}

.eco-diagnostic-live-offer-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 9px;
  color: var(--eco-ink-2);
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  font-size: 12px;
  font-weight: 900;
}

.eco-diagnostic-live-offer-actions button:first-child {
  color: #fff;
  background: var(--eco-diagnostic-accent-strong);
  border-color: var(--eco-diagnostic-accent-strong);
}

.eco-diagnostic-live-offer-actions button:hover {
  border-color: var(--eco-diagnostic-accent-line);
}

.eco-diagnostic-report-link a {
  display: block;
  overflow: hidden;
  color: var(--eco-diagnostic-accent-strong);
  font-size: 12px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-diagnostic-fast-actions,
.eco-diagnostic-filter-actions {
  display: grid;
  gap: 8px;
}

.eco-diagnostic-fast-actions > div:last-child,
.eco-diagnostic-filter-actions > div:last-child {
  display: grid;
  gap: 6px;
}

.eco-diagnostic-fast-actions button,
.eco-diagnostic-filter-actions button {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 7px;
  align-items: center;
  min-height: 36px;
  padding: 8px 9px;
  color: var(--eco-ink-2);
  text-align: left;
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 5px;
  font-size: 12px;
  font-weight: 850;
  line-height: 1.15;
}

.eco-diagnostic-fast-actions button:hover,
.eco-diagnostic-filter-actions button:hover,
.eco-diagnostic-filter-actions button.is-active {
  color: var(--eco-diagnostic-accent-strong);
  background: var(--eco-hover);
  border-color: var(--eco-diagnostic-accent-line);
}

.eco-diagnostic-fast-actions button:disabled,
.eco-diagnostic-filter-actions button:disabled {
  cursor: not-allowed;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-color: var(--eco-line);
  opacity: 0.58;
}

.eco-diagnostic-fast-actions span,
.eco-diagnostic-filter-actions span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.eco-diagnostic-side-actions {
  display: grid;
  gap: 8px;
}

.eco-diagnostic-side-actions .eco-btn {
  width: 100%;
}

.eco-diagnostic-block-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.eco-diagnostic-block-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  min-height: 92px;
  padding: 14px;
  text-align: left;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-sm);
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.eco-diagnostic-block-card:hover {
  border-color: var(--eco-diagnostic-accent-line);
  box-shadow: var(--eco-shadow-sm);
}

.eco-diagnostic-block-card div {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.eco-diagnostic-block-card strong {
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-diagnostic-block-card span {
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
}

.eco-diagnostic-block-card i {
  grid-column: 1 / -1;
  overflow: hidden;
  height: 4px;
  background: var(--eco-surface-deep);
  border-radius: 99px;
}

.eco-diagnostic-block-card em {
  display: block;
  height: 100%;
  background: var(--eco-diagnostic-accent-strong);
  border-radius: inherit;
}

.eco-diagnostic-summary-btn,
.eco-diagnostic-skip-btn,
.eco-diagnostic-voice-btn {
  width: 100%;
}

.eco-diagnostic-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-diagnostic-panel-head > div {
  min-width: 0;
  text-align: right;
}

.eco-diagnostic-node-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.eco-diagnostic-node {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 12px;
  padding: 12px 14px;
  color: var(--eco-ink);
  text-align: left;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-node:hover {
  background: var(--eco-hover);
  border-color: var(--eco-line-strong);
}

.eco-diagnostic-node > span:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
  font-weight: 650;
}

.eco-diagnostic-measurement {
  padding: 14px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-measurement-input {
  height: 54px;
  font-size: 28px;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
}

.eco-diagnostic-scale {
  position: relative;
  overflow: hidden;
  height: 8px;
  margin-top: 10px;
  background: linear-gradient(90deg, var(--eco-success), #f59e0b, var(--eco-danger));
  border-radius: 999px;
}

.eco-diagnostic-scale-marker {
  width: 4px;
  height: 100%;
  background: rgba(10, 10, 10, 0.55);
}

.eco-diagnostic-status-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-diagnostic-status-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 74px;
  padding: 12px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 750;
}

.eco-diagnostic-status-btn--green.is-active {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: #86efac;
}

.eco-diagnostic-status-btn--yellow.is-active {
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fcd34d;
}

.eco-diagnostic-status-btn--red.is-active {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fca5a5;
}

.eco-diagnostic-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-diagnostic-tag {
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-3);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.eco-diagnostic-tag.is-active {
  color: var(--eco-diagnostic-accent-strong);
  background: var(--eco-diagnostic-accent-tint);
  border-color: var(--eco-diagnostic-accent-line);
}

.eco-diagnostic-tags-more {
  position: relative;
}

.eco-diagnostic-tags-more summary {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-diagnostic-accent-strong);
  background: var(--eco-diagnostic-accent-tint);
  border: 1px solid var(--eco-diagnostic-accent-line);
  border-radius: 999px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 850;
  list-style: none;
}

.eco-diagnostic-tags-more summary::-webkit-details-marker {
  display: none;
}

.eco-diagnostic-tags-more div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}

.eco-diagnostic-file {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

.eco-diagnostic-file input {
  min-width: 0;
  margin-left: auto;
  font-size: 12px;
}

.eco-diagnostic-recommendation {
  margin-top: 2px;
}

.eco-diagnostic-summary-kpis {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.eco-diagnostic-offers,
.eco-diagnostic-next-visit,
.eco-diagnostic-zone,
.eco-diagnostic-photo-summary,
.eco-diagnostic-report-preview {
  overflow: hidden;
}

.eco-diagnostic-section-head {
  margin-bottom: 12px;
}

.eco-diagnostic-section-head p {
  margin: 6px 0 0;
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
}

.eco-diagnostic-zone-list {
  display: grid;
  gap: 10px;
}

.eco-diagnostic-zone-item {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(280px, 1.1fr);
  gap: 12px;
  align-items: start;
  padding: 12px;
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-zone-item.is-red {
  background: linear-gradient(90deg, var(--eco-danger-tint), var(--eco-bg) 30%);
  border-left: 4px solid var(--eco-danger);
}

.eco-diagnostic-zone-item.is-yellow {
  background: linear-gradient(90deg, var(--eco-warning-tint), var(--eco-bg) 30%);
  border-left: 4px solid var(--eco-warning);
}

.eco-diagnostic-zone-item strong,
.eco-diagnostic-summary-offers > strong,
.eco-diagnostic-report-preview-card strong {
  display: block;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 900;
  line-height: 1.25;
}

.eco-diagnostic-zone-item span,
.eco-diagnostic-report-preview-card span,
.eco-diagnostic-report-preview-card p {
  display: block;
  margin-top: 4px;
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
}

.eco-diagnostic-zone-item em {
  display: block;
  margin-top: 7px;
  color: var(--eco-ink-2);
  font-size: 12px;
  font-style: normal;
  font-weight: 850;
  line-height: 1.35;
}

.eco-diagnostic-summary-offers {
  display: grid;
  gap: 8px;
}

.eco-diagnostic-summary-offers.is-next-visit {
  padding: 10px;
  background: var(--eco-warning-tint);
  border: 1px solid #fde68a;
  border-radius: 6px;
}

.eco-diagnostic-summary-offer {
  display: grid;
  gap: 8px;
  padding: 10px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-summary-empty {
  padding: 12px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 850;
}

.eco-diagnostic-summary-empty.is-inline {
  padding: 10px;
  font-size: 12px;
}

.eco-diagnostic-reminder-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-diagnostic-photo-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
  gap: 10px;
}

.eco-diagnostic-photo-summary-grid figure {
  overflow: hidden;
  margin: 0;
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-photo-summary-grid img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.eco-diagnostic-photo-summary-grid figcaption {
  padding: 8px;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.25;
}

.eco-diagnostic-report-preview {
  display: grid;
  gap: 10px;
}

.eco-diagnostic-report-preview-card {
  display: grid;
  gap: 10px;
  padding: 12px;
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-diagnostic-report-preview-card p {
  margin: 0;
}

.eco-diagnostic-report-preview-card a {
  display: block;
  overflow: hidden;
  color: var(--eco-diagnostic-accent-strong);
  font-size: 12px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-diagnostic-report-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-diagnostic-offers li {
  padding: 12px 0;
  border-bottom: 1px solid var(--eco-line);
}

.eco-diagnostic-offers li:last-child {
  border-bottom: 0;
}

.eco-diagnostic-offer-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 750;
}

.eco-diagnostic-offer-check input,
.eco-diagnostic-offer-variants input {
  accent-color: var(--eco-diagnostic-accent-strong);
}

.eco-diagnostic-offer-variants {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 0 0 26px;
}

.eco-diagnostic-offer-variants label,
.eco-diagnostic-offer-static {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-diagnostic-offer-static {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-left: 0;
}

.eco-diagnostic-offer-variants b,
.eco-diagnostic-offer-static b {
  color: var(--eco-ink);
  font-weight: 750;
  font-variant-numeric: tabular-nums;
}

.eco-diagnostic-actions {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) repeat(3, minmax(0, 1fr));
  gap: 8px;
}

@media (max-width: 1320px) and (min-width: 1181px) {
  .platform-shell__main {
    gap: 14px;
  }

  .platform-shell__brand span {
    display: none;
  }

  .platform-shell__search {
    width: 220px;
    min-width: 220px;
  }

  .eco-shipment-new-page {
    width: min(100%, 1360px);
  }

  .eco-shipment-new-layout {
    grid-template-columns: minmax(0, 1fr) minmax(280px, 320px);
  }

  .eco-shipment-vin-body {
    grid-template-columns: minmax(280px, 0.48fr) minmax(0, 1fr);
  }

  .eco-shipment-vin-spec-grid,
  .eco-shipment-new-attributes dl {
    grid-template-columns: 1fr;
  }

  .eco-shipment-card-body {
    grid-template-columns: 1fr;
  }

  .eco-shipment-client-actions {
    justify-content: flex-start;
  }

  .eco-shipment-new-total-main {
    align-items: flex-start;
    flex-direction: column;
  }

  .eco-shipment-detail-layout {
    grid-template-columns: minmax(0, 1fr) minmax(300px, 360px);
    gap: 20px;
  }

  .eco-shipment-detail-party-card {
    grid-template-columns: 1fr;
  }

  .eco-shipment-detail-vin-form {
    grid-template-columns: 1fr;
  }

  .eco-shipment-detail-search-filters,
  .eco-shipment-detail-vin-specs {
    grid-template-columns: 1fr;
  }

  .eco-shipment-detail-party + .eco-shipment-detail-party {
    border-top: 1px solid var(--eco-line);
    border-left: 0;
  }
}

@media (max-width: 1180px) {
  .platform-shell__main {
    display: grid;
    grid-template-columns: 1fr auto;
    height: auto;
    min-height: var(--eco-topbar-h);
  }

  .platform-shell__brand-row {
    grid-column: 1 / -1;
  }

  .platform-shell__actions {
    margin-left: 0;
  }

  .platform-shell__nav {
    display: none;
  }

  .platform-shell__search {
    display: none;
  }

  .eco-home-kpi-grid,
  .eco-home-main-grid,
  .eco-home-mini-grid,
  .eco-dashboard-kpi-grid,
  .eco-dashboard-main-grid,
  .eco-dashboard-bottom-grid,
  .eco-dashboard-alert-grid,
  .eco-notifications-kpis,
  .eco-notifications-grid,
  .eco-crm-metrics,
  .eco-salary-metrics,
  .eco-stock-doc-metrics,
  .eco-restock-metrics,
  .eco-cabinet-metrics,
  .eco-cabinet-salary-kpis,
  .eco-cabinet-grid,
  .eco-diagnostic-vehicle,
  .eco-diagnostic-vehicle-grid,
  .eco-diagnostic-summary-kpis,
  .eco-diagnostic-actions,
  .eco-shipment-new-layout,
  .eco-shipment-new-context,
  .eco-shipment-card-body,
  .eco-shipment-vin-body,
  .eco-shipment-vin-spec-grid,
  .eco-shipment-new-modal-grid,
  .eco-crm-form-grid,
  .eco-inventory-layout,
  .eco-restock-layout {
    grid-template-columns: 1fr;
  }

  .eco-records-layout {
    grid-template-columns: 1fr;
  }

  .eco-records-details {
    position: static;
    max-height: none;
  }

  .eco-records-form-grid,
  .eco-records-status-picker {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-counterparty-box {
    flex-direction: column;
  }

  .eco-journal-free-strip > div {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .eco-journal-free-strip .eco-btn {
    grid-column: 2;
    justify-self: start;
  }

  .eco-restock-rail {
    position: static;
  }

  .eco-shipment-new-aside {
    position: static;
  }

  .eco-shipment-new-page {
    width: 100%;
  }

  .eco-shipment-new-aside {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-shipment-client-actions .eco-btn {
    width: 100%;
  }

  .eco-shipment-vin-spec-pane h3 {
    font-size: 24px;
  }

  .eco-shipment-detail-head,
  .eco-shipment-detail-layout,
  .eco-shipment-detail-party-card {
    grid-template-columns: 1fr;
  }

  .eco-shipment-detail-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .eco-shipment-detail-actions {
    justify-content: flex-start;
  }

  .eco-shipment-detail-aside {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-shipment-detail-party + .eco-shipment-detail-party {
    border-top: 1px solid var(--eco-line);
    border-left: 0;
  }

  .eco-crm-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-dashboard-kpi-grid,
  .eco-dashboard-alert-grid,
  .eco-notifications-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-dashboard-stat-row,
  .eco-dashboard-stat-row--crm,
  .eco-dashboard-cash-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-dashboard-appointment-row,
  .eco-dashboard-crm-row {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .eco-dashboard-row-actions {
    justify-content: flex-start;
  }

  .eco-crm-drawer__body,
  .eco-crm-history {
    grid-template-columns: 1fr;
  }

  .eco-diagnostic-quick-row-main {
    grid-template-columns: minmax(180px, 1fr) minmax(320px, 1.4fr);
  }

  .eco-diagnostic-quick-row-main:not(:has(.eco-diagnostic-quick-measure)) {
    grid-template-columns: minmax(180px, 1fr) minmax(320px, 1.4fr);
  }

  .eco-diagnostic-quick-measure,
  .eco-diagnostic-quick-row-tools {
    grid-column: 1 / -1;
  }

  .eco-diagnostic-quick-row-tools {
    display: flex;
    justify-content: flex-start;
  }

  .eco-diagnostic-quick-details {
    grid-template-columns: 1fr;
  }

  .eco-diagnostic-zone-item {
    grid-template-columns: 1fr;
  }

  .eco-diagnostic-reminder-actions {
    justify-content: flex-start;
  }

  .eco-diagnostic-inline-offer,
