  .eco-shipment-mobile-card__actions .flex {
    justify-content: flex-end;
  }

  .eco-shipment-mobile-empty {
    background: var(--eco-surface);
    border: 1px solid var(--eco-line);
    border-radius: 6px;
  }
}

.eco-position-group-row td {
  height: auto !important;
  padding: 9px 16px !important;
  background: color-mix(in srgb, var(--shipment-surface-muted, #f3eee6) 78%, white) !important;
  border-top: 1px solid var(--shipment-border-strong, #cdc3b4) !important;
  border-bottom: 1px solid var(--shipment-border, #ded7ca) !important;
}

.eco-position-group-label,
.eco-position-card-group-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--shipment-text-soft, #76746d);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-position-group-label b,
.eco-position-card-group-title b {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 22px;
  padding: 0 8px;
  color: var(--shipment-text, #292a24);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  letter-spacing: 0;
  background: var(--shipment-surface, #fffdfa);
  border: 1px solid var(--shipment-border, #ded7ca);
  border-radius: 999px;
}

.eco-position-card-group-title {
  padding: 3px 2px 0;
}

@media (max-width: 900px) {
  .eco-shipment-new-positions .eco-table-wrap {
    display: none;
  }

  .eco-position-cards {
    display: grid !important;
    padding: 14px;
  }

  .eco-position-head-actions {
    width: 100%;
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
  }

  .eco-position-head-actions button {
    width: 100%;
  }

  .eco-position-title-row {
    width: 100%;
    justify-content: space-between;
  }

  .eco-position-card-head button {
    width: 32px !important;
    height: 32px !important;
    padding: 0 !important;
  }

  .eco-position-card-controls {
    grid-template-columns: 1fr !important;
  }

  .eco-position-card-controls label {
    min-width: 0;
  }

  .eco-position-discount,
  .eco-position-edit-input.is-price,
  .eco-position-edit-input.is-qty {
    width: 100% !important;
  }

  .eco-shipment-new-table-foot {
    grid-template-columns: 1fr;
  }

  .eco-shipment-new-table-foot strong {
    justify-self: start;
  }
}

/* Precheck document page */
.eco-precheck-page {
  --precheck-bg: #f4f2ed;
  --precheck-surface: #fffdfa;
  --precheck-surface-soft: #faf8f3;
  --precheck-surface-muted: #f1eee7;
  --precheck-border: #ded7ca;
  --precheck-border-strong: #c9bfad;
  --precheck-text: #24241f;
  --precheck-text-soft: #6f6d65;
  --precheck-faint: #9a958a;
  --precheck-accent: #b6491f;
  --precheck-accent-hover: #983b18;
  --precheck-green: #243229;
  --precheck-ok: #1c7347;
  --precheck-warn: #a16a15;
  width: min(100%, 1500px);
  padding: 20px 24px 72px;
  color: var(--precheck-text);
  background: var(--precheck-bg);
}

.eco-precheck-page * {
  letter-spacing: 0;
}

.eco-precheck-page .eco-page-kicker {
  color: var(--precheck-faint);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
}

.eco-precheck-page .eco-card {
  overflow: hidden;
  background: var(--precheck-surface);
  border: 1px solid var(--precheck-border);
  border-radius: 8px;
  box-shadow: 0 1px 1px rgba(36, 36, 31, 0.03), 0 12px 30px rgba(36, 36, 31, 0.045);
}

.eco-precheck-head {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin: 0 0 16px;
  padding: 18px 20px;
  background: var(--precheck-surface);
  border: 1px solid var(--precheck-border);
  border-radius: 8px;
  box-shadow: 0 1px 1px rgba(36, 36, 31, 0.03), 0 12px 30px rgba(36, 36, 31, 0.045);
}

.eco-precheck-head::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--precheck-accent);
  border-radius: 8px 0 0 8px;
  content: "";
}

.eco-precheck-back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  margin-bottom: 8px;
  color: var(--precheck-text-soft);
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
}

.eco-precheck-back-link:hover,
.eco-precheck-crumbs a:hover {
  color: var(--precheck-accent);
}

.eco-precheck-crumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 7px;
}

.eco-precheck-crumbs a {
  color: inherit;
  text-decoration: none;
}

.eco-precheck-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.eco-precheck-title-row .eco-page-title,
.eco-precheck-head .eco-page-title {
  margin: 0;
  color: var(--precheck-text);
  font-size: 38px;
  font-weight: 850;
  line-height: 1;
}

.eco-precheck-head .eco-page-subtitle {
  max-width: none;
  margin-top: 9px;
  color: var(--precheck-text-soft);
  font-size: 14px;
  font-weight: 650;
}

.eco-precheck-head-meta {
  margin: 4px 0 0;
  color: var(--precheck-faint);
  font-size: 13px;
  font-weight: 650;
}

.eco-precheck-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 336px;
  gap: 16px;
  align-items: start;
}

.eco-precheck-main {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.eco-precheck-aside {
  position: sticky;
  top: 104px;
  display: grid;
  gap: 12px;
  min-width: 0;
}

.eco-precheck-card .eco-card__head,
.eco-precheck-total-card .eco-shipment-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 66px;
  padding: 16px 20px;
  background: var(--precheck-surface-soft);
  border-bottom: 1px solid var(--precheck-border);
}

.eco-precheck-card .eco-card__head h2,
.eco-precheck-total-card .eco-shipment-card-head h2 {
  margin: 0;
  color: var(--precheck-text);
  font-size: 24px;
  font-weight: 850;
  line-height: 1.1;
}

.eco-precheck-total-card .eco-shipment-card-head {
  background: var(--precheck-green);
  border-bottom-color: var(--precheck-green);
}

.eco-precheck-total-card .eco-shipment-card-head h2 {
  color: #fff;
}

.eco-precheck-context-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding: 20px;
}

.eco-precheck-context-item {
  display: grid;
  gap: 7px;
  min-height: 74px;
  align-content: center;
  padding: 13px 14px;
  background: var(--precheck-surface-soft);
  border: 1px solid var(--precheck-border);
  border-radius: 8px;
}

.eco-precheck-context-item.is-wide {
  grid-column: span 2;
}

.eco-precheck-context-item span {
  color: var(--precheck-text-soft);
  font-size: 11px;
  font-weight: 850;
  text-transform: uppercase;
}

.eco-precheck-context-item strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--precheck-text);
  font-size: 15px;
  font-weight: 850;
}

.eco-precheck-mono,
.eco-precheck-table code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.eco-precheck-table-wrap {
  overflow-x: auto;
}

.eco-precheck-table {
  width: 100%;
  min-width: 1120px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13px;
}

.eco-precheck-table th {
  padding: 13px 14px;
  color: var(--precheck-text-soft);
  background: var(--precheck-surface-muted);
  border-bottom: 1px solid var(--precheck-border-strong);
  font-size: 10px;
  font-weight: 850;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.eco-precheck-table td {
  padding: 15px 14px;
  color: var(--precheck-text);
  background: #fff;
  border-bottom: 1px solid var(--precheck-border);
  vertical-align: top;
}

.eco-precheck-table tr.is-warning td {
  background: #fffaf0;
}

.eco-precheck-table tfoot td {
  color: var(--precheck-text);
  background: var(--precheck-surface-soft);
  font-weight: 850;
}

.eco-precheck-table .is-num {
  text-align: right;
  white-space: nowrap;
}

.eco-precheck-table .is-total {
  font-size: 15px;
  font-weight: 900;
}

.eco-precheck-table-index {
  width: 46px;
  color: var(--precheck-faint) !important;
  font-weight: 850;
}

.eco-precheck-position-name {
  display: block;
  max-width: 520px;
  color: var(--precheck-text);
  font-size: 15px;
  font-weight: 900;
  line-height: 1.28;
  overflow-wrap: anywhere;
}

.eco-precheck-position-sub,
.eco-precheck-table code {
  display: block;
  margin-top: 5px;
  color: var(--precheck-faint);
  font-size: 11px;
  font-weight: 700;
}

.eco-precheck-marking-cell {
  width: 280px;
}

.eco-precheck-marking-box {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.eco-precheck-marking-note {
  color: var(--precheck-text-soft);
  font-size: 12px;
  font-weight: 700;
}

.eco-precheck-marking-input {
  width: 100%;
  min-height: 70px;
  padding: 10px 11px;
  color: var(--precheck-text);
  background: #fff;
  border: 1px solid var(--precheck-border-strong);
  border-radius: 7px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  line-height: 1.35;
  outline: none;
  resize: vertical;
}

.eco-precheck-marking-input:focus {
  border-color: var(--precheck-accent);
  outline: 3px solid rgba(182, 73, 31, 0.14);
  outline-offset: 1px;
}

.eco-precheck-marking-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  color: var(--precheck-text-soft);
  font-size: 12px;
  font-weight: 750;
}

.eco-precheck-marking-actions .is-danger {
  color: #b91c1c;
}

.eco-precheck-marking-actions button {
  min-height: 30px;
  padding: 0 9px;
  color: var(--precheck-accent);
  background: #fff;
  border: 1px solid var(--precheck-border-strong);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 850;
}

.eco-precheck-position-cards {
  display: none;
  gap: 12px;
  padding: 16px;
}

.eco-precheck-position-card {
  display: grid;
  gap: 13px;
  padding: 14px;
  background: #fff;
  border: 1px solid var(--precheck-border);
  border-radius: 8px;
}

.eco-precheck-position-card.is-warning {
  background: #fffaf0;
  border-color: #e6c66c;
}

.eco-precheck-position-card-head {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
}

.eco-precheck-position-card-head > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 28px;
  color: var(--precheck-accent);
  background: #fff0e8;
  border: 1px solid #edc5b3;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 900;
}

.eco-precheck-position-card-head strong {
  display: block;
  overflow-wrap: anywhere;
  color: var(--precheck-text);
  font-size: 15px;
  font-weight: 900;
  line-height: 1.28;
}

.eco-precheck-position-card-head small {
  display: block;
  margin-top: 4px;
  color: var(--precheck-faint);
  font-size: 12px;
  font-weight: 700;
}

.eco-precheck-position-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.eco-precheck-position-card-grid span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 38px;
  padding: 8px 10px;
  color: var(--precheck-text-soft);
  background: var(--precheck-surface-soft);
  border: 1px solid var(--precheck-border);
  border-radius: 7px;
  font-size: 12px;
  font-weight: 750;
}

.eco-precheck-position-card-grid strong {
  color: var(--precheck-text);
  font-size: 13px;
  font-weight: 900;
  text-align: right;
}

.eco-precheck-empty-state {
  display: grid;
  gap: 9px;
  align-content: center;
  justify-items: start;
  min-height: 240px;
  margin: 20px;
  padding: 28px 32px;
  color: var(--precheck-text-soft);
  background: var(--precheck-surface-soft);
  border: 1px dashed var(--precheck-border-strong);
  border-radius: 8px;
}

.eco-precheck-empty-state strong {
  color: var(--precheck-text);
  font-size: 18px;
  font-weight: 900;
}

.eco-precheck-empty-state span {
  font-size: 14px;
  font-weight: 650;
  line-height: 1.45;
}

.eco-precheck-state-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  max-width: 920px;
  margin: 90px auto 0;
}

.eco-precheck-state-card h1 {
  margin: 4px 0 0;
  color: var(--precheck-text);
  font-size: 30px;
  font-weight: 900;
}

.eco-precheck-state-card p {
  margin: 8px 0 0;
  color: var(--precheck-text-soft);
  font-size: 14px;
  font-weight: 650;
}

.eco-precheck-state-card.is-error {
  border-color: #f0b8ad;
  background: #fff8f5;
}

.eco-precheck-state-icon {
  width: 30px;
  height: 30px;
  color: var(--precheck-accent);
}

.eco-precheck-total-body {
  display: grid;
  gap: 13px;
  padding: 18px;
}

.eco-precheck-total-line,
.eco-precheck-total-main {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
}

.eco-precheck-total-line span,
.eco-precheck-total-main span {
  color: var(--precheck-text-soft);
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.eco-precheck-total-line strong {
  color: var(--precheck-text);
  font-size: 14px;
  font-weight: 900;
  text-align: right;
}

.eco-precheck-total-line.is-muted strong {
  color: var(--precheck-text-soft);
}

.eco-precheck-total-main {
  display: grid;
  gap: 6px;
  margin-top: 3px;
  padding-top: 16px;
  border-top: 1px dashed var(--precheck-border-strong);
}

.eco-precheck-total-main strong {
  color: var(--precheck-text);
  font-size: 44px;
  font-weight: 950;
  line-height: 1;
  overflow-wrap: anywhere;
}

.eco-precheck-submit {
  width: 100%;
  min-height: 56px !important;
  margin-top: 2px;
  background: var(--precheck-accent) !important;
  border-color: var(--precheck-accent) !important;
  border-radius: 8px !important;
  box-shadow: 0 12px 26px rgba(182, 70, 29, 0.22) !important;
  font-size: 15px !important;
  font-weight: 900 !important;
}

.eco-precheck-submit:hover {
  background: var(--precheck-accent-hover) !important;
  border-color: var(--precheck-accent-hover) !important;
}

.eco-precheck-side-actions {
  display: grid;
  gap: 8px;
}

.eco-precheck-side-actions .eco-btn,
.eco-precheck-head .eco-btn {
  min-height: 40px;
  border-radius: 7px;
  font-weight: 850;
}

.eco-precheck-service-body {
  display: grid;
  gap: 10px;
  padding: 18px 20px;
}

.eco-precheck-service-body p {
  margin: 0;
  color: var(--precheck-text-soft);
  font-size: 14px;
  font-weight: 650;
  line-height: 1.45;
}

.eco-precheck-message {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 12px 13px;
  border: 1px solid var(--precheck-border);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 750;
}

.eco-precheck-message.is-error {
  color: #991b1b;
  background: #fff1f2;
  border-color: #fecaca;
}

.eco-precheck-message.is-success {
  color: var(--precheck-ok);
  background: #edf7f0;
  border-color: #b9dec7;
}

.eco-precheck-skeleton-head {
  display: grid;
  justify-content: stretch;
}

.eco-precheck-skeleton-table {
  display: grid;
  gap: 13px;
  padding: 20px;
}

.eco-precheck-spin {
  animation: eco-precheck-spin 0.85s linear infinite;
}

@keyframes eco-precheck-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 1279px) {
  .eco-precheck-page {
    padding: 16px 14px 48px;
  }

  .eco-precheck-layout {
    grid-template-columns: 1fr;
  }

  .eco-precheck-aside {
    position: static;
  }

  .eco-precheck-context-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .eco-precheck-page {
    padding: 12px 10px 36px;
  }

  .eco-precheck-head {
    flex-direction: column;
    padding: 18px 16px;
  }

  .eco-precheck-head .eco-actions,
  .eco-precheck-head .eco-btn {
    width: 100%;
  }

  .eco-precheck-head .eco-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .eco-precheck-title-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .eco-precheck-title-row .eco-page-title,
  .eco-precheck-head .eco-page-title {
    font-size: 32px;
  }

  .eco-precheck-card .eco-card__head,
  .eco-precheck-total-card .eco-shipment-card-head {
    align-items: flex-start;
    flex-direction: column;
    min-height: auto;
    padding: 16px;
  }

  .eco-precheck-card .eco-card__head h2,
  .eco-precheck-total-card .eco-shipment-card-head h2 {
    font-size: 24px;
  }

  .eco-precheck-context-grid {
    grid-template-columns: 1fr;
    padding: 16px;
  }

  .eco-precheck-context-item.is-wide {
    grid-column: auto;
  }

  .eco-precheck-table-wrap {
    display: none;
  }

  .eco-precheck-position-cards {
    display: grid;
  }

  .eco-precheck-position-card-grid {
    grid-template-columns: 1fr;
  }

  .eco-precheck-total-main strong {
    font-size: 38px;
  }

  .eco-precheck-state-card {
    grid-template-columns: 1fr;
    margin-top: 24px;
  }

  .eco-precheck-state-card .eco-actions,
  .eco-precheck-state-card .eco-btn {
    width: 100%;
  }
}

.product-editor-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.46);
  backdrop-filter: blur(4px);
}

.product-editor-drawer {
  display: flex;
  flex-direction: column;
  width: min(1280px, calc(100vw - 42px));
  height: 100vh;
  max-height: 100dvh;
  overflow: hidden;
  background: #fbfaf7;
  border-left: 1px solid var(--eco-line);
  box-shadow: -24px 0 70px rgba(15, 23, 42, 0.24);
}

.product-editor-header,
.product-editor-footer {
  position: sticky;
  z-index: 2;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(12px);
}

.product-editor-header {
  top: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 22px 16px;
  border-bottom: 1px solid var(--eco-line);
}

.product-editor-title-block {
  min-width: 0;
}

.product-editor-kicker {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.product-editor-header h2 {
  margin: 5px 0 0;
  color: var(--eco-ink);
  font-size: 24px;
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1.18;
  overflow-wrap: anywhere;
}

.product-editor-meta-line {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  margin-top: 9px;
