  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  list-style: none;
}

.product-editor-extra-details summary::after,
.product-editor-technical summary::after {
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--eco-muted);
  border-bottom: 2px solid var(--eco-muted);
  content: "";
  transform: rotate(45deg);
  transition: transform 140ms ease;
}

.product-editor-extra-details[open] summary::after,
.product-editor-technical[open] summary::after {
  transform: rotate(225deg);
}

.product-editor-extra-details summary::-webkit-details-marker,
.product-editor-technical summary::-webkit-details-marker {
  display: none;
}

.product-editor-extra-details summary span,
.product-editor-technical summary span {
  display: grid;
  gap: 3px;
}

.product-editor-extra-details summary b,
.product-editor-technical summary b {
  color: var(--eco-ink-2);
  font-size: 15px;
}

.product-editor-extra-details summary em,
.product-editor-technical summary em {
  font-size: 12px;
  font-style: normal;
}

.product-editor-extra-details[open] summary,
.product-editor-technical[open] summary {
  margin-bottom: 12px;
}

.product-editor-readonly-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.product-editor-readonly-grid span {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 8px 10px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.product-editor-readonly-grid b {
  color: var(--eco-muted);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.product-editor-readonly-grid em {
  overflow-wrap: anywhere;
  color: var(--eco-ink-3);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  font-style: normal;
}

.product-editor-footer {
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 22px calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--eco-line);
  box-shadow: 0 -12px 36px rgba(15, 23, 42, 0.08);
}

.product-editor-footer-note {
  color: var(--eco-muted);
  font-size: 13px;
  font-weight: 750;
}

.product-editor-footer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

@media (max-width: 900px) {
  .product-editor-drawer {
    width: calc(100vw - 18px);
  }

  .product-editor-workspace,
  .product-editor-two-columns,
  .product-editor-grid,
  .product-editor-readonly-grid {
    grid-template-columns: 1fr;
  }

  .product-editor-summary-rail {
    position: static;
    grid-row: auto;
  }

  .product-editor-field.is-full {
    grid-column: auto;
  }

  .product-editor-photo-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .product-editor-backdrop {
    justify-content: stretch;
  }

  .product-editor-drawer {
    width: 100vw;
    border-left: 0;
  }

  .product-editor-header,
  .product-editor-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .product-editor-header-actions,
  .product-editor-footer-actions,
  .product-editor-footer-actions .eco-btn {
    width: 100%;
  }

  .product-editor-footer-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .product-editor-scroll {
    padding: 14px 14px 20px;
  }

  .product-editor-nav {
    padding: 8px 14px;
  }

  .product-editor-header h2 {
    font-size: 20px;
  }

  .product-editor-section {
    padding: 14px;
  }

  .product-editor-section-head,
  .product-editor-kpi-row {
    align-items: stretch;
    flex-direction: column;
  }

  .product-editor-stock-grid,
  .product-editor-photo-grid {
    grid-template-columns: 1fr;
  }

  .product-editor-meta-line span {
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
  }
}

.eco-spin {
  animation: eco-spin 0.8s linear infinite;
}

@keyframes eco-spin {
  to {
    transform: rotate(360deg);
  }
}

.eco-clients-page {
