  gap: 12px;
}

.eco-client-telegram-error {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: #b42318 !important;
}

.eco-client-telegram-error span {
  min-width: 220px;
  flex: 1 1 auto;
}

.eco-client-telegram-link {
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 10px;
  background: #fff8f2;
  border: 1px solid #ffd6c2;
  border-radius: 8px;
}

.eco-client-telegram-link img {
  width: 112px;
  height: 112px;
  background: #fff;
  border-radius: 6px;
}

.eco-client-telegram-link div {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.eco-client-telegram-link strong {
  overflow-wrap: anywhere;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 800;
}

.eco-client-telegram-link span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-client-shipments-block {
  grid-column: 1 / -1;
}

.eco-client-shipments-summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
}

.eco-client-shipments-summary .eco-client-info-line {
  border-top: 0;
}

.eco-client-shipments-all {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 34px;
  padding: 0 10px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid #ffd6c2;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 850;
  text-decoration: none;
  white-space: nowrap;
}

.eco-client-shipments-all:hover {
  color: #8f3218;
  border-color: #f5b28f;
}

.eco-client-shipment-list {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.eco-client-shipment-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 58px;
  padding: 10px 12px;
  color: var(--eco-ink);
  background: #fff;
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  text-decoration: none;
}

.eco-client-shipment-row:hover {
  border-color: #f0c2aa;
  box-shadow: 0 8px 20px rgba(33, 28, 21, 0.06);
}

.eco-client-shipment-row span {
  min-width: 0;
}

.eco-client-shipment-row strong,
.eco-client-shipment-row em {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-client-shipment-row strong {
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 850;
}

.eco-client-shipment-row em {
  margin-top: 4px;
  color: var(--eco-muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
}

.eco-client-form-drawer {
  width: min(980px, calc(100vw - 48px));
}

.eco-client-form {
  display: grid;
  gap: 14px;
  overflow: auto;
  padding: 18px 22px 24px;
}

.eco-client-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.eco-client-type-seg {
  margin-bottom: 12px;
}

.eco-client-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.eco-client-field.is-full {
  grid-column: 1 / -1;
}

.eco-client-field span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.1em;
  line-height: 1.15;
  text-transform: uppercase;
}

.eco-client-field .eco-input {
  min-height: 42px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 650;
}

.eco-client-field textarea.eco-input {
  min-height: 86px;
  padding-top: 10px;
  line-height: 1.45;
  resize: vertical;
}

.eco-client-drawer__footer {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 14px 22px calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--eco-line);
}

.eco-client-drawer__footer span {
  color: var(--eco-muted);
  font-size: 13px;
  font-weight: 750;
}

.eco-client-drawer__footer > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.eco-client-confirm-backdrop {
  justify-content: center;
  align-items: center;
  padding: 18px;
}

.eco-client-confirm {
  width: min(420px, 100%);
  padding: 20px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-lg);
}

.eco-client-confirm__icon {
  display: inline-grid;
  place-items: center;
  width: 40px;
  height: 40px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-radius: 8px;
}

.eco-client-confirm h2 {
  margin: 14px 0 6px;
  color: var(--eco-ink);
  font-size: 20px;
  font-weight: 850;
}

.eco-client-confirm p {
  margin: 0 0 12px;
  color: var(--eco-muted);
  font-size: 13px;
  line-height: 1.45;
}

.eco-client-confirm > strong {
  display: block;
  padding: 10px 12px;
  color: var(--eco-ink);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-client-confirm__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 16px;
}

@media (max-width: 1180px) {
  .eco-clients-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-clients-table {
    width: max(100%, 1180px);
    min-width: 1180px;
  }

  .eco-clients-table .eco-clients-optional-col {
    display: none;
  }
}

@media (max-width: 860px) {
  .eco-clients-page {
    padding: 18px 12px 36px;
  }

  .eco-clients-search-panel {
    position: sticky;
    z-index: 20;
    top: calc(var(--eco-topbar-h) + var(--eco-substrip-h));
  }

  .eco-clients-metrics {
    display: flex;
    gap: 10px;
    overflow-x: auto;
    padding-bottom: 4px;
    scrollbar-width: thin;
  }

  .eco-clients-metrics .eco-kpi {
    min-width: 214px;
    min-height: 98px;
  }

  .eco-clients-page .eco-table-wrap {
    display: none;
  }

  .eco-clients-cards {
    display: grid;
    gap: 10px;
    padding: 12px;
  }

  .eco-clients-table-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-clients-page-size,
  .eco-clients-filters .eco-select-chip,
  .eco-clients-filters .eco-btn {
    width: 100%;
  }

  .eco-client-drawer,
  .eco-client-form-drawer {
    width: 100vw;
    border-left: 0;
  }

  .eco-client-drawer__body,
  .eco-client-form-grid {
    grid-template-columns: 1fr;
  }

  .eco-client-shipments-summary,
  .eco-client-shipment-row {
    grid-template-columns: 1fr;
  }

  .eco-client-shipments-all {
    justify-content: center;
  }

  .eco-client-field.is-full {
    grid-column: auto;
  }

  .eco-client-drawer__header,
  .eco-client-drawer__footer {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-client-drawer__footer > div,
  .eco-client-drawer__footer .eco-btn,
  .eco-client-drawer__actions .eco-btn,
  .eco-client-drawer__actions {
    width: 100%;
  }
}

@media (max-width: 560px) {
  .eco-clients-search .eco-input {
    font-size: 13px;
  }

  .eco-client-mobile-card__head,
  .eco-client-mobile-card__meta {
    grid-template-columns: 1fr;
  }

  .eco-client-mobile-card__head .eco-client-avatar {
    display: none;
  }

  .eco-client-mobile-card__actions,
  .eco-clients-pagination,
  .eco-clients-pagination > div,
  .eco-client-confirm__actions,
  .eco-client-confirm__actions .eco-btn,
  .eco-clients-state-actions,
  .eco-clients-state-actions .eco-btn {
    width: 100%;
  }

  .eco-client-mobile-card__actions,
  .eco-clients-pagination,
  .eco-client-confirm__actions,
  .eco-clients-state-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-client-info-line {
    grid-template-columns: 1fr;
    gap: 3px;
  }
}

/* Cash workspace */
.eco-cash-page {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.eco-cash-head {
  margin-bottom: 4px;
}

.eco-cash-tabs {
  align-self: flex-start;
}

.eco-cash-tabs .eco-seg-btn {
  min-width: 118px;
}

.eco-cash-tabs .eco-seg-btn:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.eco-cash-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.eco-cash-section__head {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.eco-cash-section__head .eco-page-title {
  margin-top: 0;
  font-size: 20px;
}

.eco-cash-section--danger .eco-cash-section__head .eco-page-title {
  color: var(--eco-danger);
}

.eco-cash-kpis {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.eco-cash-kpis .eco-kpi {
  min-height: 124px;
}

.eco-cash-open-card,
.eco-cash-active-grid,
.eco-cash-operation-grid {
  display: grid;
  gap: 16px;
}

.eco-cash-open-card {
  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.9fr);
  align-items: center;
}

.eco-cash-open-copy h3 {
  margin: 8px 0 0;
  color: var(--eco-ink);
  font-size: 22px;
  line-height: 1.15;
}

.eco-cash-open-copy p {
  max-width: 620px;
  margin: 10px 0 0;
  color: var(--eco-muted);
  font-size: 13px;
  line-height: 1.55;
}

.eco-cash-open-form,
.eco-cash-form-grid,
.eco-cash-close-grid {
  display: grid;
  gap: 12px;
}

.eco-cash-active-grid {
  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.9fr);
  align-items: start;
}

.eco-cash-operation-grid {
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
  align-items: start;
}

.eco-cash-form-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.eco-cash-form-grid--compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.eco-cash-close-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.eco-cash-field {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.eco-cash-field > span,
.eco-cash-definition-grid b,
.eco-cash-audit-grid b {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.eco-cash-field--wide {
  grid-column: 1 / -1;
}

.eco-cash-money-input {
  text-align: right;
  font-size: 16px;
  font-weight: 700;
}

.eco-cash-textarea {
  min-height: 92px;
  padding-top: 10px;
  resize: vertical;
}

.eco-cash-definition-grid,
.eco-cash-audit-grid {
  display: grid;
  gap: 10px;
}

.eco-cash-definition-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.eco-cash-definition-grid span,
.eco-cash-audit-grid span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-cash-action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.eco-cash-action-row--end {
  justify-content: flex-end;
}

.eco-cash-close-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
  padding: 12px 0 0;
  border-top: 1px dashed var(--eco-line);
}

.eco-cash-close-summary span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-cash-close-summary strong {
  font-size: 18px;
}

.eco-cash-warning,
.eco-cash-error,
.eco-cash-empty {
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-cash-warning {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding: 10px 12px;
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
  font-size: 12px;
  line-height: 1.45;
}

.eco-cash-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
  font-size: 13px;
}

.eco-cash-error--page {
  margin-top: -8px;
}

.eco-cash-empty {
  display: flex;
  min-height: 132px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  padding: 28px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border-style: dashed;
  text-align: center;
}

.eco-cash-empty strong {
  color: var(--eco-ink);
  font-size: 16px;
}

.eco-cash-empty span {
  max-width: 460px;
  line-height: 1.5;
}

.eco-cash-filter-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.eco-cash-search {
  width: min(100%, 420px);
}

.eco-cash-doc-table .eco-table {
  min-width: 1120px;
}

.eco-cash-doc-table .eco-table td,
.eco-cash-history-table .eco-table td,
.eco-cash-ops-table .eco-table td {
  height: 64px;
}

.eco-cash-history-table .eco-table {
  min-width: 1320px;
}

.eco-cash-primary-text {
  color: var(--eco-ink);
  font-weight: 650;
}

.eco-cash-secondary-text {
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-cash-purpose {
  max-width: 420px;
  color: var(--eco-ink-2);
  line-height: 1.35;
}

.eco-cash-doc-number {
  color: var(--eco-ink);
  font-weight: 700;
}

.eco-cash-money-cell {
  color: var(--eco-ink);
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}

.eco-cash-money-cell.is-danger,
.eco-cash-close-summary .is-danger {
  color: var(--eco-danger);
}

.eco-cash-money-cell.is-ok,
.eco-cash-close-summary .is-ok {
  color: var(--eco-success);
}

.eco-cash-inline-warning {
  display: block;
  margin-top: 3px;
  color: var(--eco-warning);
  font-family: Inter, "Open Sans", Roboto, Arial, sans-serif;
  font-size: 11px;
  font-weight: 600;
}

.eco-cash-payment-seg {
  width: fit-content;
}

.eco-cash-autocomplete {
  z-index: 5;
}

.eco-cash-autocomplete__list {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  left: 0;
  overflow: auto;
  max-height: 220px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  box-shadow: var(--eco-shadow-pop);
}

.eco-cash-autocomplete__list button,
.eco-cash-autocomplete__empty {
  display: block;
  width: 100%;
  padding: 9px 11px;
  color: var(--eco-ink);
  background: transparent;
  border: 0;
  font-size: 13px;
  text-align: left;
}

.eco-cash-autocomplete__list button:hover {
  background: var(--eco-hover);
}

.eco-cash-autocomplete__empty {
  color: var(--eco-muted);
}

.eco-cash-clickable-row {
  cursor: pointer;
}

.eco-cash-clickable-row .eco-icon.is-open {
  transform: rotate(180deg);
}

.eco-cash-audit {
  padding: 18px;
  background: var(--eco-surface-sunk);
}

.eco-cash-audit__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.eco-cash-audit__head h3 {
  margin: 4px 0 0;
  font-size: 18px;
}

.eco-cash-audit-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 14px;
}

.eco-cash-audit-op {
  display: grid;
  grid-template-columns: minmax(180px, 0.8fr) minmax(120px, auto) minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 10px 0;
  border-top: 1px solid var(--eco-line);
}

.eco-cash-audit-op > div {
  display: flex;
  align-items: center;
  gap: 8px;
}

.eco-cash-audit-op p {
  margin: 0;
  color: var(--eco-muted);
}

.eco-cash-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-cash-pagination__controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.eco-cash-mobile-list {
  display: none;
}

.eco-cash-mobile-card {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 7px;
  padding: 14px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  box-shadow: var(--eco-shadow-sm);
  text-align: left;
}

.eco-cash-mobile-card__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.eco-cash-table-skeleton,
.eco-cash-skeleton-grid {
  display: grid;
  gap: 12px;
}

.eco-cash-table-skeleton span,
.eco-cash-skeleton {
  min-height: 48px;
  overflow: hidden;
  position: relative;
  background: var(--eco-surface-sunk);
  border-radius: 4px;
}

.eco-cash-skeleton-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.eco-cash-skeleton--head,
.eco-cash-skeleton--wide {
  grid-column: 1 / -1;
}

.eco-cash-skeleton--head {
  min-height: 92px;
}

.eco-cash-skeleton--wide {
  min-height: 260px;
}

.eco-cash-table-skeleton span::after,
.eco-cash-skeleton::after {
  position: absolute;
  inset: 0;
  content: "";
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
  animation: eco-cash-shimmer 1.3s infinite;
}

.eco-cash-spin {
  animation: eco-cash-spin 0.8s linear infinite;
}

@keyframes eco-cash-shimmer {
  100% {
    transform: translateX(100%);
  }
}

@keyframes eco-cash-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 1320px) {
  .eco-cash-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .eco-cash-open-card,
  .eco-cash-active-grid,
  .eco-cash-operation-grid {
    grid-template-columns: 1fr;
  }

  .eco-cash-audit-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .eco-cash-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-cash-form-grid,
  .eco-cash-form-grid--compact,
  .eco-cash-close-grid,
  .eco-cash-definition-grid,
  .eco-cash-audit-grid {
    grid-template-columns: 1fr;
  }

  .eco-cash-doc-table,
  .eco-cash-history-table {
    display: none;
  }

  .eco-cash-mobile-list {
    display: grid;
    gap: 10px;
  }

  .eco-cash-filter-bar,
  .eco-cash-filter-bar .eco-search-wrap,
  .eco-cash-filter-bar .eco-select-chip,
  .eco-cash-pagination,
  .eco-cash-pagination .eco-select-chip,
  .eco-cash-pagination__controls,
  .eco-cash-open-form .eco-actions,
  .eco-cash-action-row .eco-btn,
  .eco-cash-action-row button {
    width: 100%;
  }

  .eco-cash-action-row,
  .eco-cash-pagination,
  .eco-cash-open-form .eco-actions {
