@media (max-width: 560px) {
  .eco-cash-kpis,
  .eco-cash-skeleton-grid {
    grid-template-columns: 1fr;
  }

  .eco-cash-tabs,
  .eco-cash-tabs .eco-seg-btn {
    width: 100%;
  }

  .eco-cash-tabs {
    display: grid;
    grid-template-columns: 1fr;
  }

  .eco-cash-open-card,
  .eco-cash-shift-card,
  .eco-cash-close-card,
  .eco-cash-documents,
  .eco-cash-history-card,
