/* Supplier invoices workspace */
.eco-invoices-page {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.eco-invoices-head {
  margin-bottom: 0;
}

.eco-invoices-source-note {
  max-width: 220px;
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
  text-align: right;
}

.eco-invoices-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid #bbf7d0;
  border-radius: 4px;
  font-size: 13px;
  font-weight: 650;
}

.eco-invoices-notice button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: transparent;
  border: 0;
}

.eco-invoices-kpis {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.eco-invoices-kpis .eco-kpi {
  min-height: 126px;
}

.eco-invoices-filter-grid {
  display: grid;
  grid-template-columns: minmax(280px, 1.7fr) repeat(4, minmax(150px, 1fr));
  gap: 12px;
  align-items: end;
}

.eco-invoices-filter-grid label,
.eco-invoices-payment-grid label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.eco-invoices-filter-grid label > span,
.eco-invoices-payment-grid label > span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.eco-invoices-search {
  grid-column: span 2;
}

.eco-invoices-search-input {
  position: relative;
}

.eco-invoices-search-input .eco-icon {
  position: absolute;
  top: 50%;
  left: 10px;
  z-index: 1;
  color: var(--eco-muted);
  transform: translateY(-50%);
}

.eco-invoices-search-input .eco-input {
  padding-left: 34px;
}

.eco-invoices-filter-toggles {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-invoices-check {
  display: inline-flex !important;
  min-height: 36px;
  align-items: center;
  flex-direction: row !important;
  gap: 8px !important;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 650;
}

.eco-invoices-filter-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.eco-invoices-documents {
  overflow: hidden;
}

.eco-invoices-documents-head {
  align-items: center;
}

.eco-invoices-bulkbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 12px;
  padding: 10px 12px;
  color: var(--eco-ink);
  background: var(--eco-rust-tint);
  border: 1px solid #fed7aa;
  border-radius: 4px;
  font-size: 13px;
}

.eco-invoices-bulkbar span {
  color: var(--eco-muted);
}

.eco-invoices-error,
.eco-invoices-warning-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px;
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border: 1px solid #fecaca;
  border-radius: 4px;
  font-size: 13px;
}

.eco-invoices-error strong,
.eco-invoices-error span {
  display: block;
}

.eco-invoices-error span {
  margin-top: 3px;
  color: var(--eco-ink-3);
}

.eco-invoices-error--compact {
  justify-content: flex-start;
  margin: 12px 16px 0;
}

.eco-invoices-warning-line {
  justify-content: flex-start;
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-invoices-table .eco-table {
  min-width: 1280px;
}

.eco-invoices-table .eco-table td {
  height: 72px;
}

.eco-invoices-row {
  cursor: pointer;
}

.eco-invoices-row:hover td {
  background: rgba(251, 146, 60, 0.05);
}

.eco-invoices-select-cell {
  width: 36px;
  text-align: center;
}

.eco-invoices-sort {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
}

.eco-invoices-doc-number,
.eco-invoices-primary {
  color: var(--eco-ink);
  font-weight: 700;
}

.eco-invoices-secondary,
.eco-invoices-danger {
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-invoices-danger {
  color: var(--eco-danger);
  font-weight: 650;
}

.eco-invoices-doc-link {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  gap: 7px;
  color: var(--eco-rust);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}

.eco-invoices-doc-link span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-invoices-doc-warning {
  color: var(--eco-warning);
  font-size: 12px;
  font-weight: 700;
}

.eco-invoices-table .l-money {
  color: var(--eco-ink);
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}

.eco-invoices-table .l-money.is-warning {
  color: var(--eco-warning);
}

.eco-invoices-table .l-money.is-ok {
  color: var(--eco-success);
}

.eco-invoices-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.eco-icon-btn--accent {
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #fed7aa;
}

.eco-invoices-empty {
  display: flex;
  min-height: 260px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 9px;
  color: var(--eco-muted);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 4px;
  text-align: center;
}

.eco-invoices-empty strong {
  color: var(--eco-ink);
  font-size: 18px;
}

.eco-invoices-empty span {
  max-width: 520px;
  line-height: 1.5;
}

.eco-invoices-empty__icon {
  width: 34px;
  height: 34px;
  color: var(--eco-rust);
}

.eco-invoices-table-skeleton {
  display: grid;
  gap: 10px;
}

.eco-invoices-table-skeleton span,
.eco-invoices-skeleton {
  position: relative;
  min-height: 54px;
  overflow: hidden;
  background: var(--eco-surface-sunk);
  border-radius: 4px;
}

.eco-invoices-skeleton {
  min-height: 126px;
}

.eco-invoices-table-skeleton span::after,
.eco-invoices-skeleton::after {
  position: absolute;
  inset: 0;
  content: "";
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
  animation: eco-invoices-shimmer 1.3s infinite;
}

.eco-invoices-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-invoices-pagination__controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.eco-invoices-mobile-list {
  display: none;
}

.eco-invoices-mobile-card {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  box-shadow: var(--eco-shadow-sm);
  text-align: left;
}

.eco-invoices-mobile-card__top,
.eco-invoices-mobile-card__money {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.eco-invoices-mobile-card small {
  display: block;
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-invoices-mobile-card__money span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  color: var(--eco-muted);
  font-size: 11px;
  text-transform: uppercase;
}

.eco-invoices-mobile-card__money b {
  color: var(--eco-ink);
  font-size: 16px;
  text-transform: none;
}

.eco-invoices-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  background: rgba(24, 24, 27, 0.32);
  border: 0;
}

.eco-invoices-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 81;
  display: flex;
  width: min(720px, 100vw);
  flex-direction: column;
  background: var(--eco-surface);
  border-left: 1px solid var(--eco-line);
  box-shadow: -28px 0 70px rgba(24, 24, 27, 0.18);
}

.eco-invoices-drawer__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-invoices-drawer__head h2 {
  margin: 6px 0 0;
  color: var(--eco-ink);
  font-size: 24px;
  line-height: 1.15;
}

.eco-invoices-drawer__head p {
  margin: 7px 0 0;
  color: var(--eco-muted);
}

.eco-invoices-drawer__head-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.eco-invoices-drawer__summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  background: var(--eco-line);
  border-bottom: 1px solid var(--eco-line);
}

.eco-invoices-drawer__summary span {
  display: flex;
  min-height: 82px;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  padding: 14px 18px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-invoices-drawer__summary b {
  color: var(--eco-ink);
  font-family: ui-monospace, monospace;
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  text-transform: none;
}

.eco-invoices-drawer__body {
  display: grid;
  gap: 14px;
  overflow: auto;
  padding: 18px 20px;
}

.eco-invoices-detail-block {
  display: grid;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-invoices-detail-block h3 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 15px;
}

.eco-invoices-detail-block p {
  margin: 0;
  color: var(--eco-ink-2);
  font-size: 13px;
  line-height: 1.5;
}

.eco-invoices-definition-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.eco-invoices-definition-grid span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-invoices-definition-grid b {
  color: var(--eco-muted);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.eco-invoices-linked-document {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  padding: 12px;
  color: var(--eco-ink);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  text-decoration: none;
}

.eco-invoices-linked-document b,
.eco-invoices-linked-document span {
  display: block;
}

.eco-invoices-linked-document span {
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-invoices-position-list,
.eco-invoices-payment-list {
  display: grid;
  gap: 8px;
}

.eco-invoices-position-list > div,
.eco-invoices-payment-list > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--eco-line);
}

.eco-invoices-position-list span,
.eco-invoices-payment-list span {
  min-width: 0;
}

.eco-invoices-position-list b,
.eco-invoices-payment-list b {
  display: block;
  color: var(--eco-ink);
}

.eco-invoices-position-list small,
.eco-invoices-payment-list small {
  display: block;
  margin-top: 3px;
  color: var(--eco-muted);
}

.eco-invoices-position-list strong {
  color: var(--eco-ink);
  font-family: ui-monospace, monospace;
  white-space: nowrap;
}

.eco-invoices-payment-form {
  padding: 18px 20px 20px;
  border-top: 1px solid var(--eco-line);
  box-shadow: 0 -12px 34px rgba(24, 24, 27, 0.06);
}

.eco-invoices-payment-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.eco-invoices-payment-comment {
  grid-column: 1 / -1;
}

.eco-invoices-payment-comment textarea {
  min-height: 76px;
  padding-top: 10px;
  resize: vertical;
}

.eco-invoices-drawer__footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}

.eco-invoices-spin {
  animation: eco-invoices-spin 0.8s linear infinite;
}

@keyframes eco-invoices-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes eco-invoices-shimmer {
  100% {
    transform: translateX(100%);
  }
}

@media (max-width: 1320px) {
  .eco-invoices-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .eco-invoices-filter-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .eco-invoices-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 920px) {
  .eco-invoices-kpis,
  .eco-invoices-filter-grid,
  .eco-invoices-payment-grid,
  .eco-invoices-definition-grid {
    grid-template-columns: 1fr;
  }

  .eco-invoices-source-note {
    width: 100%;
    max-width: none;
    text-align: left;
  }

  .eco-invoices-documents-head,
  .eco-invoices-documents-head .eco-page-actions,
  .eco-invoices-filter-actions,
  .eco-invoices-filter-actions .eco-btn,
  .eco-invoices-pagination,
  .eco-invoices-pagination .eco-select-chip,
  .eco-invoices-pagination__controls,
  .eco-invoices-drawer__footer,
  .eco-invoices-drawer__footer .eco-btn {
    width: 100%;
  }

  .eco-invoices-documents-head,
  .eco-invoices-documents-head .eco-page-actions,
  .eco-invoices-filter-actions,
  .eco-invoices-pagination,
  .eco-invoices-drawer__footer {
    align-items: stretch;
    flex-direction: column;
  }

  .eco-invoices-table {
    display: none;
  }

  .eco-invoices-mobile-list {
    display: grid;
    gap: 10px;
  }

  .eco-invoices-drawer {
    width: 100vw;
  }

  .eco-invoices-drawer__summary {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .eco-invoices-mobile-card__top,
  .eco-invoices-mobile-card__money,
  .eco-invoices-linked-document,
  .eco-invoices-position-list > div,
  .eco-invoices-payment-list > div {
    grid-template-columns: 1fr;
    flex-direction: column;
    align-items: flex-start;
  }

  .eco-invoices-drawer__head {
    padding: 16px;
  }

  .eco-invoices-drawer__body,
  .eco-invoices-payment-form {
    padding-right: 16px;
    padding-left: 16px;
  }
}

.eco-finance-profit-page {
