  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-color: #ffd6c2;
}

.eco-finance-sort-row button svg {
  width: 13px;
  height: 13px;
}

.eco-finance-toggle-row {
  justify-content: space-between;
}

.eco-finance-toggle-row label {
  display: inline-flex;
  grid-auto-flow: column;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  color: var(--eco-ink-2);
  font-size: 13px;
  font-weight: 700;
}

.eco-finance-toggle-row input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--eco-rust);
}

.eco-finance-calculate {
  min-width: 148px;
}

.eco-finance-progress {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  padding: 9px 12px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid #ffd6c2;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 750;
}

.eco-finance-progress svg {
  animation: eco-finance-spin 900ms linear infinite;
}

@keyframes eco-finance-spin {
  to {
    transform: rotate(360deg);
  }
}

.eco-finance-source {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  padding: 12px 14px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-finance-source strong {
  color: var(--eco-ink-2);
  font-weight: 750;
}

.eco-finance-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.eco-finance-kpi-grid--primary .eco-finance-kpi {
  min-height: 142px;
}

.eco-finance-kpi {
  position: relative;
  display: grid;
  gap: 9px;
  min-height: 118px;
  overflow: hidden;
  padding: 16px;
  text-align: left;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-finance-kpi::before {
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 3px;
  content: "";
  background: var(--eco-line-strong);
}

.eco-finance-kpi.is-clickable {
  cursor: pointer;
}

.eco-finance-kpi.is-clickable:hover {
  border-color: var(--eco-rust);
}

.eco-finance-kpi.is-success::before {
  background: var(--eco-success);
}

.eco-finance-kpi.is-warning::before {
  background: var(--eco-warning);
}

.eco-finance-kpi.is-danger::before {
  background: var(--eco-danger);
}

.eco-finance-kpi.is-info::before {
  background: var(--eco-info);
}

.eco-finance-kpi strong {
  color: var(--eco-ink);
  font-size: clamp(24px, 2.4vw, 34px);
  font-weight: 780;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
}

.eco-finance-kpi small {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
}

.eco-finance-kpi em {
  color: var(--eco-rust);
  font-size: 12px;
  font-style: normal;
  font-weight: 800;
}

.eco-finance-warning {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  gap: 14px;
  align-items: center;
  padding: 14px 16px;
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-finance-warning > svg {
  width: 22px;
  height: 22px;
  color: var(--eco-warning);
}

.eco-finance-warning strong {
  display: block;
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-finance-warning p {
  margin: 3px 0 0;
  color: #8a4b0d;
  font-size: 13px;
}

.eco-finance-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding-bottom: 2px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-finance-tabs button {
  min-height: 38px;
  padding: 0 14px;
  color: var(--eco-ink-3);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px 6px 0 0;
  font-size: 13px;
  font-weight: 780;
}

.eco-finance-tabs button:hover,
.eco-finance-tabs button.is-active {
  color: var(--eco-rust);
  background: var(--eco-surface);
  border-color: var(--eco-line);
  border-bottom-color: var(--eco-surface);
}

.eco-finance-overview {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(280px, 0.8fr);
  gap: 16px;
}

.eco-finance-overview .eco-finance-panel--wide,
.eco-finance-overview .eco-finance-formulas {
  grid-column: 1 / -1;
}

.eco-finance-panel {
  min-width: 0;
  padding: 16px;
}

.eco-finance-panel--wide {
  width: 100%;
}

.eco-finance-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.eco-finance-section-head h2,
.eco-finance-section-head h3,
.eco-finance-formulas summary,
.eco-finance-drawer h2,
.eco-finance-drawer h3 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 18px;
  font-weight: 780;
  letter-spacing: 0;
  line-height: 1.2;
}

.eco-finance-section-head h3,
.eco-finance-drawer h3 {
  font-size: 15px;
}

.eco-finance-section-head p,
.eco-finance-formulas p,
.eco-finance-drawer p {
  margin: 5px 0 0;
  color: var(--eco-muted);
  font-size: 13px;
  line-height: 1.45;
}

.eco-finance-section-head > svg {
  width: 22px;
  height: 22px;
  color: var(--eco-rust);
}

.eco-finance-chart {
  display: grid;
  gap: 10px;
}

.eco-finance-chart svg {
  width: 100%;
  height: auto;
  min-height: 220px;
}

.eco-finance-chart line {
  stroke: var(--eco-line-strong);
  stroke-width: 1;
}

.eco-finance-chart rect.is-revenue {
  fill: rgba(194, 65, 12, 0.62);
}

.eco-finance-chart rect.is-profit {
  fill: rgba(21, 128, 61, 0.72);
}

.eco-finance-chart polyline.is-margin {
  fill: none;
  stroke: var(--eco-info);
  stroke-linejoin: round;
  stroke-width: 3;
}

.eco-finance-chart text {
  fill: var(--eco-muted);
  font-size: 11px;
}

.eco-finance-chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 750;
}

.eco-finance-chart-legend span::before {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  content: "";
}

.eco-finance-chart-legend .is-revenue::before {
  background: rgba(194, 65, 12, 0.62);
}

.eco-finance-chart-legend .is-profit::before {
  background: rgba(21, 128, 61, 0.72);
}

.eco-finance-chart-legend .is-margin::before {
  height: 3px;
  background: var(--eco-info);
}

.eco-finance-chart-empty,
.eco-finance-empty-cell {
  padding: 28px 16px;
  color: var(--eco-muted);
  text-align: center;
}

.eco-finance-category-list,
.eco-finance-reason-list {
  display: grid;
  gap: 8px;
}

.eco-finance-category-list div,
.eco-finance-reason-list div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 42px;
  padding: 10px 12px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-finance-category-list span,
.eco-finance-reason-list span {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--eco-ink-2);
  font-size: 13px;
  font-weight: 720;
}

.eco-finance-category-list strong,
.eco-finance-reason-list strong,
.eco-finance-reason-list em {
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 800;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.eco-finance-reason-list em {
  grid-column: 1 / -1;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-finance-table-wrap {
  width: 100%;
  overflow-x: auto;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-finance-table {
  width: 100%;
  min-width: 980px;
  border-collapse: collapse;
  font-size: 13px;
}

.eco-finance-table--rows {
  min-width: 1180px;
}

.eco-finance-table th {
  padding: 12px 14px;
  color: var(--eco-muted);
  background: #f3f0e9;
  border-bottom: 1px solid var(--eco-line);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.eco-finance-table td {
  min-height: 56px;
  padding: 13px 14px;
  border-bottom: 1px solid var(--eco-line);
  vertical-align: middle;
}

.eco-finance-table tr:last-child td {
  border-bottom: 0;
}

.eco-finance-table tr:hover td {
  background: rgba(250, 250, 247, 0.78);
}

.eco-finance-table tr.is-warning td {
  background: rgba(254, 243, 199, 0.42);
}

.eco-finance-table tr.is-danger td {
  background: rgba(254, 226, 226, 0.38);
}

.eco-finance-table th.is-number,
.eco-finance-table td.is-number {
  text-align: right;
}

.eco-finance-table td.is-number,
.eco-finance-kpi strong,
.eco-finance-period-card strong,
.eco-finance-drawer-kpis strong,
.eco-finance-writeoff-summary strong {
  font-variant-numeric: tabular-nums;
}

.eco-finance-table td > strong,
.eco-finance-product-link strong,
.eco-finance-doc-link strong {
  display: block;
  color: var(--eco-ink);
  font-weight: 780;
}

.eco-finance-table td > span,
.eco-finance-product-link span,
.eco-finance-doc-link span {
  display: block;
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
}

.eco-finance-product-link {
  display: block;
  width: 100%;
  min-width: 260px;
  padding: 0;
  color: inherit;
  text-align: left;
  background: transparent;
  border: 0;
  text-decoration: none;
}

.eco-finance-product-link:not(.is-static):hover strong,
.eco-finance-doc-link:hover strong {
  color: var(--eco-rust);
}

.eco-finance-product-link.is-static {
  min-width: 0;
}

.eco-finance-doc-link {
  display: inline-block;
  min-width: 150px;
  color: inherit;
  text-decoration: none;
}

.eco-finance-table .is-profit {
  color: var(--eco-success);
  font-weight: 820;
}

.eco-finance-table .is-profit.is-danger {
  color: var(--eco-danger);
}

.eco-finance-status {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.eco-finance-status.is-success {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: #bbf7d0;
}

.eco-finance-status.is-warning {
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-finance-status.is-danger {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-finance-status.is-info {
  color: var(--eco-info);
  background: var(--eco-info-tint);
  border-color: #bfdbfe;
}

.eco-finance-status.is-neutral {
  color: var(--eco-ink-3);
  background: var(--eco-surface-sunk);
}

.eco-finance-row-action {
  display: block;
  margin-top: 6px;
  color: var(--eco-rust);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.eco-finance-mobile-cards {
  display: none;
}

.eco-finance-mobile-cards .eco-finance-product-link {
  min-width: 0;
}

.eco-finance-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-finance-formulas {
  padding: 0;
}

.eco-finance-formulas summary {
  display: flex;
  align-items: center;
  min-height: 52px;
  padding: 0 16px;
  cursor: pointer;
}

.eco-finance-formulas > div {
  display: grid;
  gap: 8px;
  padding: 0 16px 16px;
}

.eco-finance-formulas code {
  display: block;
  padding: 10px 12px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-family: inherit;
  font-size: 13px;
}

.eco-finance-state {
  display: grid;
  place-items: center;
  gap: 8px;
  padding: 36px 18px;
  color: var(--eco-muted);
  text-align: center;
}

.eco-finance-state svg {
  width: 34px;
  height: 34px;
  color: var(--eco-rust);
}

.eco-finance-state h2,
.eco-finance-state h3 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 20px;
  font-weight: 780;
}

.eco-finance-state p,
.eco-finance-state small {
  max-width: 620px;
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.eco-finance-state--error {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-finance-state--error svg,
.eco-finance-state--error small {
  color: var(--eco-danger);
}

.eco-finance-state--inline {
  margin-bottom: 14px;
  background: var(--eco-surface-sunk);
  box-shadow: none;
}

.eco-finance-skeleton {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.eco-finance-skeleton span {
  min-height: 120px;
  overflow: hidden;
  background: linear-gradient(90deg, #f3f0e9, #ffffff, #f3f0e9);
  background-size: 240% 100%;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  animation: eco-finance-skeleton 1.2s ease-in-out infinite;
}

@keyframes eco-finance-skeleton {
  to {
    background-position: -240% 0;
  }
}

.eco-finance-issue-list {
  display: grid;
  gap: 10px;
}

.eco-finance-issue-list article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 13px;
  background: var(--eco-warning-tint);
  border: 1px solid #fde68a;
  border-radius: 8px;
}

.eco-finance-issue-list article.is-danger {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-finance-issue-list svg {
  width: 20px;
  height: 20px;
  color: var(--eco-warning);
}

.eco-finance-issue-list article.is-danger svg {
  color: var(--eco-danger);
}

.eco-finance-issue-list strong {
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-finance-issue-list p {
  margin: 4px 0;
  color: var(--eco-ink-2);
  font-size: 13px;
  line-height: 1.4;
}

.eco-finance-issue-list span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-finance-issue-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.eco-finance-issue-actions b {
  flex-basis: 100%;
  color: var(--eco-ink);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.eco-finance-missing-block {
  margin-top: 18px;
}

.eco-finance-writeoff-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.eco-finance-writeoff-summary article,
.eco-finance-drawer-kpis article {
  display: grid;
  gap: 8px;
  min-height: 90px;
  padding: 14px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-finance-writeoff-summary strong,
.eco-finance-drawer-kpis strong {
  color: var(--eco-ink);
  font-size: 22px;
  font-weight: 780;
}

.eco-finance-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  justify-content: flex-end;
  background: rgba(10, 10, 10, 0.36);
}

.eco-finance-drawer {
  display: grid;
  grid-template-rows: auto minmax(0, auto);
  gap: 16px;
  width: min(620px, 100vw);
  height: 100%;
  overflow-y: auto;
  padding: 18px;
  background: var(--eco-bg);
  border-left: 1px solid var(--eco-line);
  box-shadow: -18px 0 60px rgba(10, 10, 10, 0.18);
}

.eco-finance-drawer header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-finance-drawer header span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.eco-finance-drawer header button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-finance-drawer header svg {
  width: 18px;
  height: 18px;
}

.eco-finance-drawer-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.eco-finance-drawer section {
  display: grid;
  gap: 10px;
  padding: 14px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-finance-drawer section.is-warning {
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-finance-drawer-list {
  display: grid;
  gap: 8px;
}

.eco-finance-drawer-list a {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  align-items: center;
  min-height: 48px;
  padding: 10px;
  color: inherit;
  text-decoration: none;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
}

.eco-finance-drawer-list a:hover strong {
  color: var(--eco-rust);
}

.eco-finance-drawer-list strong {
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 780;
}

.eco-finance-drawer-list span,
.eco-finance-drawer-list p {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-finance-drawer-list svg {
  width: 15px;
  height: 15px;
  color: var(--eco-muted);
}

@media (max-width: 1180px) {
  .eco-finance-head {
    grid-template-columns: 1fr;
  }

  .eco-finance-head__actions {
    justify-content: flex-start;
  }

  .eco-finance-filter-grid {
    grid-template-columns: repeat(3, minmax(160px, 1fr));
  }

  .eco-finance-kpi-grid,
  .eco-finance-skeleton {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-finance-overview {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .eco-finance-profit-page {
    padding: 18px 12px 40px;
  }

  .eco-finance-head__actions,
  .eco-finance-head__actions .eco-btn,
  .eco-finance-period-card,
  .eco-finance-calculate {
    width: 100%;
  }

  .eco-finance-filter-grid,
  .eco-finance-kpi-grid,
  .eco-finance-skeleton,
  .eco-finance-writeoff-summary,
  .eco-finance-drawer-kpis {
    grid-template-columns: 1fr;
  }

  .eco-finance-toggle-row,
  .eco-finance-warning,
  .eco-finance-issue-list article {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .eco-finance-table-wrap {
    display: none;
  }

  .eco-finance-mobile-cards {
    display: grid;
    gap: 10px;
  }

  .eco-finance-mobile-cards article {
    display: grid;
    gap: 12px;
    padding: 14px;
    background: var(--eco-surface);
    border: 1px solid var(--eco-line);
    border-radius: 8px;
  }

  .eco-finance-mobile-cards article.is-warning {
    background: var(--eco-warning-tint);
    border-color: #fde68a;
  }

  .eco-finance-mobile-cards article.is-danger {
    background: var(--eco-danger-tint);
    border-color: #fecaca;
  }

  .eco-finance-mobile-cards strong {
    color: var(--eco-ink);
    font-size: 14px;
  }

  .eco-finance-mobile-cards span {
    display: block;
    margin-top: 4px;
    color: var(--eco-muted);
    font-size: 12px;
  }

  .eco-finance-mobile-cards dl {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
    margin: 0;
  }

  .eco-finance-mobile-cards dt {
    color: var(--eco-muted);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .eco-finance-mobile-cards dd {
    margin: 5px 0 0;
    color: var(--eco-ink);
    font-size: 13px;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
  }

  .eco-finance-issue-actions,
  .eco-finance-issue-actions b {
    justify-content: flex-start;
    text-align: left;
  }
}

@media (max-width: 520px) {
  .eco-finance-mobile-cards dl {
    grid-template-columns: 1fr;
  }

  .eco-finance-tabs {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-finance-tabs button {
    border-radius: 6px;
  }
}

@media print {
  .platform-shell,
  .eco-finance-filter-bar,
  .eco-finance-head__actions,
  .eco-finance-tabs,
  .eco-finance-drawer-backdrop {
    display: none !important;
  }

  .eco-finance-profit-page {
    padding: 0;
  }
}

/* Finance center */
.eco-finance-center-page {
  width: 100%;
  max-width: none;
  padding: 28px clamp(16px, 3vw, 34px) 52px;
}

.eco-fc {
  display: grid;
  gap: 18px;
}

.eco-fc-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: end;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-fc-head-actions,
.eco-fc-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.eco-fc-modebar,
.eco-fc-filters,
.eco-fc-source,
.eco-fc-panel,
.eco-fc-alert,
.eco-fc-state {
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-fc-modebar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 12px 14px;
}

.eco-fc-modebar__copy {
  display: grid;
  gap: 3px;
}

.eco-fc-modebar__copy strong {
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 800;
}

.eco-fc-modebar__copy span,
.eco-fc-source,
.eco-fc-panel p,
.eco-fc-panel span,
.eco-fc-panel em {
  color: var(--eco-muted);
}

.eco-fc-segment {
  display: inline-flex;
  gap: 3px;
  padding: 3px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 7px;
}

.eco-fc-segment button {
  min-height: 32px;
  padding: 0 12px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 0;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.eco-fc-segment button.is-active {
  color: #fff;
  background: var(--eco-rust);
}

.eco-fc-filters {
  display: grid;
  grid-template-columns: repeat(5, minmax(150px, 1fr));
  gap: 12px;
  padding: 14px;
}

.eco-fc-filters label {
  display: grid;
  gap: 7px;
}

.eco-fc-filters label > span,
.eco-fc-kpi > span,
.eco-fc-definition-grid span,
.eco-fc-cash-grid span,
.eco-fc-category-grid span,
.eco-fc-mini-list span {
  color: var(--eco-muted);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.eco-fc-filters input,
.eco-fc-filters select {
  width: 100%;
  min-height: 40px;
  padding: 0 11px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  font-size: 13px;
  outline: none;
}

.eco-fc-filters input:focus,
.eco-fc-filters select:focus {
  border-color: var(--eco-rust);
  box-shadow: 0 0 0 2px rgba(194, 65, 12, 0.14);
}

.eco-fc-filter-actions {
  display: flex;
  grid-column: 1 / -1;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.eco-fc-filter-actions button:not(.eco-btn) {
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.eco-fc-progress {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  padding: 9px 12px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid #ffd6c2;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
}

.eco-fc-progress svg {
  animation: eco-finance-spin 900ms linear infinite;
}

.eco-fc-source {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: center;
  padding: 12px 14px;
  font-size: 12px;
}

.eco-fc-source strong {
  color: var(--eco-ink-2);
  font-weight: 800;
}

.eco-fc-source em {
  flex-basis: 100%;
  font-style: normal;
}

.eco-fc-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.eco-fc-kpi {
  position: relative;
  display: grid;
  gap: 9px;
  min-height: 128px;
  overflow: hidden;
  padding: 16px;
  text-align: left;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-sm);
}

.eco-fc-kpi::before {
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  content: "";
  background: var(--eco-line-strong);
}

.eco-fc-kpi.is-success::before { background: var(--eco-success); }
.eco-fc-kpi.is-warning::before { background: var(--eco-warning); }
.eco-fc-kpi.is-danger::before { background: var(--eco-danger); }
.eco-fc-kpi.is-info::before { background: var(--eco-info); }
.eco-fc-kpi.is-rust::before { background: var(--eco-rust); }

.eco-fc-kpi:hover {
  border-color: var(--eco-rust);
}

.eco-fc-kpi strong {
  color: var(--eco-ink);
  font-size: clamp(23px, 2.3vw, 32px);
  font-weight: 820;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
}

.eco-fc-kpi small {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.35;
}

.eco-fc-kpi em {
  color: var(--eco-rust);
  font-size: 12px;
  font-style: normal;
  font-weight: 800;
}

.eco-fc-alert {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px 16px;
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-fc-alert.is-inline {
  margin-bottom: 14px;
  box-shadow: none;
}

.eco-fc-alert > svg {
  width: 22px;
  height: 22px;
  color: var(--eco-warning);
}

.eco-fc-alert strong {
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-fc-alert p {
  margin: 3px 0 0;
  color: #8a4b0d;
  font-size: 13px;
}

.eco-fc-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-fc-tabs button {
  min-height: 38px;
  padding: 0 12px;
  color: var(--eco-ink-3);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px 6px 0 0;
  font-size: 12px;
  font-weight: 820;
}

.eco-fc-tabs button:hover,
.eco-fc-tabs button.is-active {
  color: var(--eco-rust);
  background: var(--eco-surface);
  border-color: var(--eco-line);
  border-bottom-color: var(--eco-surface);
}

.eco-fc-overview {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.65fr);
  gap: 16px;
}

.eco-fc-panel {
  min-width: 0;
  padding: 16px;
}

.eco-fc-panel--wide {
  grid-column: 1 / -1;
}

.eco-fc-stack {
  display: grid;
  gap: 16px;
}

.eco-fc-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 14px;
}

.eco-fc-section-head h2 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 18px;
  font-weight: 820;
  letter-spacing: 0;
  line-height: 1.2;
}

.eco-fc-section-head p {
  margin: 5px 0 0;
  font-size: 13px;
  line-height: 1.45;
}

.eco-fc-section-head svg {
  width: 22px;
  height: 22px;
  color: var(--eco-rust);
}

.eco-fc-split,
.eco-fc-definition-grid,
.eco-fc-cash-grid,
.eco-fc-category-grid,
.eco-fc-export-grid,
.eco-fc-rule-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.eco-fc-definition-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 14px;
}

.eco-fc-split article,
.eco-fc-definition-grid > div,
.eco-fc-cash-grid article,
.eco-fc-category-grid article,
.eco-fc-export-grid article,
.eco-fc-rule-grid article,
.eco-fc-mini-list div {
  display: grid;
  gap: 8px;
  min-height: 96px;
  padding: 14px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-fc-split strong,
.eco-fc-definition-grid strong,
.eco-fc-cash-grid strong,
.eco-fc-category-grid strong,
.eco-fc-mini-list strong,
.eco-fc-next-list b {
  color: var(--eco-ink);
  font-size: 22px;
  font-weight: 820;
  font-variant-numeric: tabular-nums;
}

.eco-fc-split p,
.eco-fc-rule-grid p,
.eco-fc-export-grid p {
  margin: 0;
  font-size: 12px;
  line-height: 1.4;
}

.eco-fc-split button {
  width: fit-content;
  padding: 0;
  color: var(--eco-rust);
  background: transparent;
  border: 0;
  font-size: 12px;
  font-weight: 850;
}

.eco-fc-mini-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.eco-fc-next-list,
.eco-fc-issue-compact,
.eco-fc-problems,
.eco-fc-rights {
  display: grid;
  gap: 10px;
}

.eco-fc-next-list a,
.eco-fc-next-list button,
.eco-fc-issue-compact button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  width: 100%;
  min-height: 58px;
  padding: 11px 12px;
  color: inherit;
  text-align: left;
  text-decoration: none;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-fc-next-list strong,
.eco-fc-issue-compact strong {
  color: var(--eco-ink);
  font-size: 13px;
  font-weight: 820;
}

.eco-fc-next-list span,
.eco-fc-issue-compact span {
  grid-column: 1 / -1;
  font-size: 12px;
}

.eco-fc-next-list b {
  grid-row: 1 / 3;
  grid-column: 2;
  align-self: center;
  font-size: 14px;
}

.eco-fc-good {
  display: flex;
  gap: 8px;
  align-items: center;
  min-height: 48px;
  padding: 12px;
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 800;
}

.eco-fc-plan-bars,
.eco-fc-category-grid {
  display: grid;
  gap: 10px;
}

.eco-fc-plan-bars > div,
.eco-fc-category-grid article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px 12px;
  align-items: center;
  min-height: 64px;
  padding: 12px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-fc-plan-bars strong {
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}

.eco-fc-plan-bars div > div,
.eco-fc-category-grid div {
  grid-column: 1 / -1;
  height: 8px;
  overflow: hidden;
  background: var(--eco-line);
  border-radius: 999px;
}

.eco-fc-plan-bars i,
.eco-fc-category-grid i {
  display: block;
  height: 100%;
  background: var(--eco-rust);
}

.eco-fc-plan-bars em,
.eco-fc-category-grid em {
  grid-column: 1 / -1;
  font-size: 12px;
  font-style: normal;
}

.eco-fc-table-wrap {
  width: 100%;
  overflow-x: auto;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-fc-table {
  width: 100%;
  min-width: 980px;
  border-collapse: collapse;
  font-size: 13px;
}

.eco-fc-table th {
  padding: 12px 14px;
  color: var(--eco-muted);
  background: #f3f0e9;
  border-bottom: 1px solid var(--eco-line);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.eco-fc-table td {
  padding: 13px 14px;
  border-bottom: 1px solid var(--eco-line);
  vertical-align: middle;
}

.eco-fc-table tr:last-child td {
  border-bottom: 0;
}

.eco-fc-table tr:hover td {
  background: rgba(250, 250, 247, 0.78);
}

.eco-fc-table th.is-number,
.eco-fc-table td.is-number {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.eco-fc-table td > strong,
.eco-fc-table a strong {
  display: block;
  color: var(--eco-ink);
  font-weight: 820;
}

.eco-fc-table td > span,
.eco-fc-table a span {
  display: block;
  margin-top: 3px;
  font-size: 12px;
  line-height: 1.35;
}

.eco-fc-table tr.is-subtotal td,
.eco-fc-table tr.is-total td {
  background: var(--eco-surface-sunk);
  font-weight: 850;
}

.eco-fc-table tr.is-total td {
  border-top: 2px solid var(--eco-line-strong);
}

.eco-fc-table tr.is-warning td {
  background: var(--eco-warning-tint);
}

.eco-fc-table tr.is-level-1 td:first-child {
  padding-left: 28px;
}

.eco-fc-chip,
.eco-fc-bool,
.eco-fc-rights span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 820;
  white-space: nowrap;
}

.eco-fc-chip.is-success,
.eco-fc-bool.is-yes {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: #bbf7d0;
}

.eco-fc-chip.is-warning {
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-fc-chip.is-danger,
.eco-fc-bool.is-no {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-fc-empty {
  padding: 26px 16px !important;
  color: var(--eco-muted);
  text-align: center;
}

.eco-fc-formulas {
  display: grid;
  gap: 8px;
  margin-top: 14px;
  padding: 12px;
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-fc-formulas summary {
  color: var(--eco-ink);
  cursor: pointer;
  font-weight: 820;
}

.eco-fc-formulas code {
  display: block;
  padding: 10px 12px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-family: inherit;
  font-size: 13px;
}

.eco-fc-problems article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 13px;
  background: var(--eco-warning-tint);
  border: 1px solid #fde68a;
  border-radius: 8px;
}

.eco-fc-problems article.is-danger {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-fc-problems article > svg {
  width: 20px;
  height: 20px;
  color: var(--eco-warning);
}

.eco-fc-problems article.is-danger > svg {
  color: var(--eco-danger);
}

.eco-fc-problems strong {
  color: var(--eco-ink);
  font-size: 14px;
}

.eco-fc-problems p {
  margin: 4px 0;
  color: var(--eco-ink-2);
  font-size: 13px;
}

.eco-fc-problems b {
  display: block;
  margin-bottom: 8px;
  color: var(--eco-ink);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.eco-fc-export-grid article,
.eco-fc-rule-grid article {
  min-height: 118px;
}

.eco-fc-export-grid strong,
.eco-fc-rule-grid strong {
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 850;
}

.eco-fc-rights {
  display: flex;
  flex-wrap: wrap;
}

.eco-fc-state {
  display: grid;
  place-items: center;
  gap: 8px;
  padding: 36px 18px;
  text-align: center;
}

.eco-fc-state.is-error {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-fc-state svg {
  width: 34px;
  height: 34px;
  color: var(--eco-danger);
}

.eco-fc-state h2 {
  margin: 0;
  color: var(--eco-ink);
  font-size: 20px;
  font-weight: 820;
}

@media (max-width: 1180px) {
  .eco-fc-head,
  .eco-fc-modebar,
  .eco-fc-overview {
    grid-template-columns: 1fr;
  }

  .eco-fc-head-actions {
    justify-content: flex-start;
  }

  .eco-fc-filters {
    grid-template-columns: repeat(3, minmax(150px, 1fr));
  }

  .eco-fc-kpis,
  .eco-fc-definition-grid,
  .eco-fc-split,
  .eco-fc-cash-grid,
  .eco-fc-export-grid,
  .eco-fc-rule-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .eco-finance-center-page {
    padding: 18px 12px 40px;
  }

  .eco-fc-head-actions,
  .eco-fc-head-actions .eco-btn,
  .eco-fc-filter-actions .eco-btn {
    width: 100%;
  }

  .eco-fc-segment {
    display: grid;
    grid-template-columns: 1fr;
  }

  .eco-fc-filters,
  .eco-fc-kpis,
  .eco-fc-definition-grid,
  .eco-fc-split,
  .eco-fc-cash-grid,
  .eco-fc-export-grid,
  .eco-fc-rule-grid,
  .eco-fc-mini-list {
    grid-template-columns: 1fr;
  }

  .eco-fc-alert,
  .eco-fc-problems article {
    grid-template-columns: 1fr;
  }

  .eco-fc-problems b {
    text-align: left;
  }

  .eco-fc-tabs {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .eco-fc-tabs button {
    border-radius: 6px;
  }
}

@media print {
  .eco-finance-center-page {
    padding: 0;
  }

  .eco-fc-head-actions,
  .eco-fc-modebar,
  .eco-fc-filters,
  .eco-fc-tabs,
  .eco-fc-toolbar,
  .eco-fc-alert {
    display: none !important;
  }
}

