@media print {
  @page { size: A4; margin: 0; }
  html,
  body {
    background: #fff !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  .diag-print-toolbar,
  .no-print {
    display: none !important;
  }
  .diag-print-screen {
    min-height: 0 !important;
    padding: 0 !important;
    background: #fff !important;
  }
  .diag-print-screen .paper-a4.rep {
    width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 auto !important;
    box-shadow: none !important;
    transform: none !important;
    zoom: 1 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  .paper-a4.rep .rep-hero,
  .paper-a4.rep .rep-verdict,
  .paper-a4.rep .rep-sec,
  .paper-a4.rep .rep-rec,
  .paper-a4.rep .rep-photo,
  .paper-a4.rep .rep-block,
  .paper-a4.rep .rep-foot,
  .paper-a4.rep .rep-foot-cta {
    break-inside: avoid;
    page-break-inside: avoid;
  }
}

@media (max-width: 760px) {
  .diag-print-screen.is-public .paper-a4.rep,
  .diag-print-screen.is-print .paper-a4.rep {
    width: calc(100vw - 20px);
    max-width: none;
  }
  .paper-a4.rep .rep-hero-body,
  .paper-a4.rep .rep-recs,
