  max-width: calc(100vw - 32px);
}

.eco-messenger-launcher {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 8px 12px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-pop);
  font-size: 13px;
  font-weight: 700;
}

.eco-messenger-launcher__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border-radius: 6px;
}

.eco-messenger-launcher strong,
.eco-messenger-unread {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 7px;
  color: #fff;
  background: var(--eco-rust);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.eco-messenger-popover {
  width: min(520px, calc(100vw - 32px));
  max-width: calc(100vw - 32px);
  height: min(720px, calc(100vh - 112px));
  overflow: hidden;
  background: var(--eco-surface);
  border: 1px solid rgba(148, 163, 184, 0.32);
  border-radius: 8px;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.16);
}

.eco-messenger-panel-head,
.eco-messenger-chat-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 68px;
  padding: 10px 12px;
  background: var(--eco-surface);
  border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.eco-messenger-panel-head h2,
.eco-messenger-context h3 {
  margin: 2px 0 0;
  color: var(--eco-ink);
  font-size: 18px;
  font-weight: 750;
  line-height: 1.15;
}

.eco-messenger-head-actions,
.eco-messenger-chat-head__actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.eco-messenger-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  color: var(--eco-ink-3);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  text-decoration: none;
}

.eco-messenger-icon-btn:hover {
  color: var(--eco-ink);
  background: var(--eco-hover);
}

.eco-messenger-inbox {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
}

.eco-messenger-search {
  position: relative;
  padding: 12px 14px 8px;
}

.eco-messenger-search .eco-icon {
  position: absolute;
  top: 22px;
  left: 26px;
  color: var(--eco-muted);
}

.eco-messenger-search input {
  width: 100%;
  height: 38px;
  padding: 0 12px 0 34px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  font-size: 13px;
  outline: none;
}

.eco-messenger-search input:focus {
  border-color: var(--eco-rust);
  box-shadow: 0 0 0 3px var(--eco-rust-tint);
}

.eco-messenger-channel-filter {
  display: grid;
  gap: 5px;
  padding: 0 14px 10px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 750;
  text-transform: uppercase;
}

.eco-messenger-channel-filter select {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 34px;
  padding: 0 34px 0 10px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  background-image: none !important;
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 650;
  outline: none;
  text-transform: none;
}

.eco-messenger-select-wrap {
  position: relative;
  display: block;
}

.eco-messenger-select-wrap .eco-icon {
  position: absolute;
  top: 50%;
  right: 10px;
  width: 14px;
  height: 14px;
  color: var(--eco-muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.eco-messenger-channel-filter select:focus {
  border-color: var(--eco-rust);
  box-shadow: 0 0 0 3px var(--eco-rust-tint);
}

.eco-messenger-filters {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 0 14px 10px;
  scrollbar-width: none;
}

.eco-messenger-filters::-webkit-scrollbar {
  display: none;
}

.eco-messenger-filters button,
.eco-messenger-dev-controls button,
.eco-messenger-dev-controls select {
  min-height: 30px;
  padding: 0 10px;
  color: var(--eco-ink-3);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}

.eco-messenger-filters button.is-active,
.eco-messenger-dev-controls button.is-active {
  color: #fff;
  background: var(--eco-ink);
  border-color: var(--eco-ink);
}

.eco-messenger-simulate {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 30px;
  margin: 0 14px 10px;
  color: var(--eco-rust);
  background: var(--eco-rust-tint);
  border: 1px solid var(--eco-rust-tint-2);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

.eco-messenger-dialog-list {
  min-height: 0;
  overflow-y: auto;
  padding: 4px 8px 10px;
}

.eco-messenger-dialog {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  width: 100%;
  min-height: 86px;
  padding: 9px 8px;
  color: var(--eco-ink);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 8px;
  text-align: left;
}

.eco-messenger-dialog:hover,
.eco-messenger-dialog.is-selected {
  background: #edf6ff;
  border-color: #cfe8ff;
}

.eco-messenger-avatar {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
}

.eco-messenger-avatar.is-compact {
  width: 42px;
  height: 42px;
}

.eco-messenger-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.eco-messenger-avatar.has-image {
  background: var(--eco-surface-sunk) !important;
}

.eco-messenger-dialog__body {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.eco-messenger-dialog__top,
.eco-messenger-dialog__meta,
.eco-messenger-dialog__tags,
.eco-messenger-message__meta {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.eco-messenger-dialog__top strong {
  overflow: hidden;
  font-size: 13px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-dialog__top time {
  margin-left: auto;
  color: var(--eco-muted);
  font-size: 11px;
  white-space: nowrap;
}

.eco-messenger-dialog__meta,
.eco-messenger-dialog__tags,
.eco-messenger-message__meta {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-messenger-channel {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 116px;
  padding: 2px 6px;
  background: color-mix(in srgb, currentColor 8%, transparent);
  border-radius: 5px;
  font-weight: 750;
  white-space: nowrap;
}

.eco-messenger-channel .eco-icon {
  width: 12px;
  height: 12px;
}

.eco-messenger-dialog__text {
  overflow: hidden;
  color: var(--eco-ink-2);
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-dialog__tags {
  flex-wrap: wrap;
}

.eco-messenger-dialog__tags em {
  padding: 2px 6px;
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-radius: 999px;
  font-size: 10px;
  font-style: normal;
  line-height: 1.2;
}

.eco-messenger-dialog__tags .eco-icon {
  width: 12px;
  height: 12px;
  color: var(--eco-rust);
  fill: currentColor;
}

.eco-messenger-dialog__meta .is-danger,
.eco-messenger-message__meta .is-danger {
  color: var(--eco-danger);
  font-weight: 750;
}

.eco-messenger-chat-head__copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.eco-messenger-chat-head__copy strong {
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 800;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-chat-head__copy > span,
.eco-messenger-chat-head__channel {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--eco-muted);
  font-size: 11px;
  min-width: 0;
}

.eco-messenger-client-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: auto;
  min-height: 30px;
  max-width: 148px;
  padding: 0 10px;
  color: var(--eco-ink-3);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 750;
  white-space: nowrap;
}

.eco-messenger-client-status + .eco-messenger-chat-head__actions {
  margin-left: 0;
}

.eco-messenger-client-status .is-short {
  display: none;
}

.eco-messenger-mini-chat {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100%;
}

.eco-messenger-thread {
  min-height: 0;
  overflow-y: auto;
  padding: 14px 16px 18px;
  background: #f6f8fb;
}

.eco-messenger-thread.is-compact {
  padding: 12px 14px 16px;
}

.eco-messenger-message-wrap {
  display: grid;
  gap: 8px;
}

.eco-messenger-day {
  justify-self: center;
  margin: 4px 0 8px;
  padding: 3px 9px;
  color: var(--eco-muted);
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid rgba(226, 232, 240, 0.9);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

.eco-messenger-message {
  display: grid;
  gap: 4px;
  width: fit-content;
  min-width: min(128px, 100%);
  max-width: min(72%, 640px);
  margin-bottom: 8px;
}

.eco-messenger-message.is-outbound {
  justify-self: end;
}

.eco-messenger-message.is-inbound {
  justify-self: start;
}

.eco-messenger-message__bubble {
  padding: 8px 10px 6px;
  background: var(--eco-surface);
  border: 1px solid rgba(226, 232, 240, 0.82);
  border-radius: 10px 10px 10px 4px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.eco-messenger-message.is-outbound .eco-messenger-message__bubble {
  background: #eef6ff;
  border-color: #cfe6ff;
  border-radius: 10px 10px 4px 10px;
}

.eco-messenger-message.is-failed .eco-messenger-message__bubble {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-messenger-message__bubble p {
  margin: 0;
  color: var(--eco-ink);
  font-size: 13px;
  line-height: 1.42;
  white-space: pre-wrap;
}

.eco-messenger-auto-note {
  display: grid;
  gap: 7px;
}

.eco-messenger-auto-note > span {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  color: var(--eco-muted);
  font-size: 11px;
  line-height: 1.2;
}

.eco-messenger-auto-note b,
.eco-messenger-auto-note em {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 6px;
  border-radius: 5px;
  font-style: normal;
}

.eco-messenger-auto-note b {
  color: #1d4ed8;
  background: #dbeafe;
}

.eco-messenger-auto-note em {
  color: var(--eco-muted);
  background: rgba(255, 255, 255, 0.62);
}

.eco-messenger-attachments {
  display: grid;
  gap: 6px;
  margin-top: 6px;
}

.eco-messenger-message__bubble p + .eco-messenger-attachments {
  margin-top: 8px;
}

.eco-messenger-attachment {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-width: 0;
  min-height: 40px;
  padding: 7px 8px;
  color: var(--eco-ink-2);
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(226, 232, 240, 0.82);
  border-radius: 7px;
  text-decoration: none;
}

.eco-messenger-attachment > span {
  min-width: 0;
}

.eco-messenger-attachment .eco-icon {
  width: 18px;
  height: 18px;
  color: var(--eco-rust);
}

.eco-messenger-attachment strong,
.eco-messenger-attachment small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-attachment strong {
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 750;
}

.eco-messenger-attachment small {
  margin-top: 2px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-messenger-attachment.is-image {
  display: block;
  overflow: hidden;
  width: min(240px, 100%);
  min-height: 120px;
  padding: 0;
  background: var(--eco-surface-sunk);
}

.eco-messenger-attachment.is-image img {
  display: block;
  width: 100%;
  max-height: 260px;
  object-fit: cover;
}

.eco-messenger-attachment.is-image span,
.eco-messenger-attachment.is-pending {
  color: var(--eco-muted);
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0.64), rgba(255, 255, 255, 0.22)),
    var(--eco-surface-sunk);
}

.eco-messenger-attachment.is-image span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 120px;
  font-size: 12px;
  font-weight: 700;
}

.eco-messenger-attachment.is-failed {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-messenger-attachment.is-failed .eco-icon,
.eco-messenger-attachment.is-failed small {
  color: var(--eco-danger);
}

.eco-messenger-attachment__mini-btn,
.eco-messenger-attachment__download {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 30px;
  padding: 0 8px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 750;
  text-decoration: none;
  white-space: nowrap;
}

.eco-messenger-attachment__mini-btn {
  color: var(--eco-danger);
}

.eco-messenger-attachment__mini-btn .eco-icon,
.eco-messenger-attachment__download .eco-icon {
  width: 15px;
  height: 15px;
}

.eco-messenger-media {
  width: min(100%, 320px);
  min-width: 0;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-messenger-thread:not(.is-compact) .eco-messenger-media {
  width: min(100%, 420px);
}

.eco-messenger-media.is-photo {
  background: var(--eco-surface-sunk);
}

.eco-messenger-media.is-sticker {
  width: min(100%, 220px);
  background: transparent;
  border-color: transparent;
}

.eco-messenger-media > button {
  display: block;
  width: 100%;
  padding: 0;
  background: transparent;
  border: 0;
  cursor: zoom-in;
}

.eco-messenger-media img {
  display: block;
  width: 100%;
  max-height: 260px;
  object-fit: contain;
  background: var(--eco-surface-sunk);
}

.eco-messenger-thread:not(.is-compact) .eco-messenger-media img {
  max-height: 320px;
}

.eco-messenger-media figcaption {
  padding: 7px 9px;
  color: var(--eco-muted);
  font-size: 11px;
  line-height: 1.35;
}

.eco-messenger-media.is-video {
  display: grid;
  gap: 0;
  width: min(100%, 320px);
}

.eco-messenger-thread:not(.is-compact) .eco-messenger-media.is-video {
  width: min(100%, 420px);
}

.eco-messenger-video-preview {
  position: relative;
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background: #111827;
}

.eco-messenger-video-preview video {
  display: block;
  width: 100%;
  height: 100%;
  max-height: none;
  object-fit: contain;
  background: #111;
}

.eco-messenger-video-preview button {
  position: absolute;
  top: 8px;
  right: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  color: #fff;
  background: rgba(15, 23, 42, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 6px;
  backdrop-filter: blur(8px);
}

.eco-messenger-video-preview button .eco-icon {
  width: 15px;
  height: 15px;
}

.eco-messenger-media.is-video-note {
  width: min(100%, 220px);
  background: transparent;
  border-color: transparent;
}

.eco-messenger-thread:not(.is-compact) .eco-messenger-media.is-video-note {
  width: min(100%, 260px);
}

.eco-messenger-media.is-video-note .eco-messenger-video-preview {
  aspect-ratio: 1;
  border-radius: 999px;
}

.eco-messenger-media.is-video-note video {
  object-fit: cover;
  border-radius: 999px;
}

.eco-messenger-media__caption {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 7px 8px;
  background: rgba(255, 255, 255, 0.72);
}

.eco-messenger-media__caption span {
  min-width: 0;
}

.eco-messenger-media__caption strong,
.eco-messenger-media__caption small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-media__caption strong {
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-messenger-media__caption small {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-messenger-audio {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  width: min(100%, 520px);
  min-width: 0;
  min-height: 60px;
  padding: 6px;
  background: rgba(255, 255, 255, 0.58);
  border: 0;
  border-radius: 8px;
}

.eco-messenger-audio__play {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: #fff;
  background: var(--eco-rust);
  border: 0;
  border-radius: 999px;
}

.eco-messenger-audio__play .eco-icon {
  width: 18px;
  height: 18px;
}

.eco-messenger-audio__body {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.eco-messenger-audio__top,
.eco-messenger-audio__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.eco-messenger-audio__top strong {
  min-width: 0;
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-audio__top small,
.eco-messenger-audio__meta {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-messenger-audio input[type="range"] {
  width: 100%;
  height: 14px;
  accent-color: var(--eco-rust);
}

.eco-messenger-audio__meta span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-audio__meta button {
  min-width: 34px;
  min-height: 24px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.eco-messenger-audio audio {
  display: none;
}

.eco-messenger-thread:not(.is-compact) .eco-messenger-audio {
  width: min(100%, 560px);
}

.eco-messenger-lightbox {
  position: fixed;
  z-index: 1200;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
}

.eco-messenger-lightbox__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.78);
  border: 0;
}

.eco-messenger-lightbox__stage {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 12px;
  width: min(96vw, 1040px);
  max-height: 92vh;
}

.eco-messenger-lightbox__stage img {
  display: block;
  max-width: 100%;
  max-height: calc(92vh - 72px);
  margin: 0 auto;
  object-fit: contain;
  border-radius: 8px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
}

.eco-messenger-lightbox__video {
  display: block;
  max-width: min(100%, 1080px);
  max-height: calc(92vh - 72px);
  margin: 0 auto;
  background: #050505;
  border-radius: 8px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
}

.eco-messenger-lightbox__video.is-video-note {
  aspect-ratio: 1;
  max-width: min(78vh, 520px);
  border-radius: 999px;
}

.eco-messenger-lightbox__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: #fff;
}

.eco-messenger-lightbox__toolbar strong {
  min-width: 0;
  overflow: hidden;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-lightbox__toolbar span {
  display: inline-flex;
  gap: 8px;
}

.eco-messenger-lightbox__toolbar button,
.eco-messenger-lightbox__nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  color: #fff;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
}

.eco-messenger-lightbox__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}

.eco-messenger-lightbox__nav.is-prev {
  left: -54px;
}

.eco-messenger-lightbox__nav.is-next {
  right: -54px;
}

.eco-messenger-message__meta {
  justify-content: flex-end;
  margin-top: 5px;
  gap: 5px;
  font-size: 10.5px;
}

.eco-messenger-system-message {
  justify-self: center;
  max-width: 72%;
  margin: 4px auto 12px;
  padding: 7px 10px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 999px;
  font-size: 11px;
  text-align: center;
}

.eco-messenger-retry {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  justify-self: end;
  min-height: 26px;
  padding: 0 8px;
  color: var(--eco-danger);
  background: var(--eco-surface);
  border: 1px solid #fecaca;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
}

.eco-messenger-composer {
  position: relative;
  padding: 10px 12px;
  background: var(--eco-surface);
  border-top: 1px solid var(--eco-line);
}

.eco-messenger-composer__bar {
  display: grid;
  grid-template-columns: 44px 44px minmax(0, 1fr) 44px 44px 44px;
  align-items: center;
  gap: 8px;
}

.eco-messenger-composer__bar button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--eco-ink-3);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 7px;
}

.eco-messenger-composer__bar button:hover {
  background: var(--eco-hover);
}

.eco-messenger-composer__bar button:disabled,
.eco-messenger-composer textarea:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.eco-messenger-composer__bar button.is-send {
  width: 44px;
  color: #fff;
  background: var(--eco-rust);
  border-color: var(--eco-rust);
}

.eco-messenger-composer textarea {
  width: 100%;
  min-height: 44px;
  max-height: 112px;
  padding: 11px 12px;
  resize: vertical;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 7px;
  font: inherit;
  font-size: 13px;
  outline: none;
}

.eco-messenger-composer textarea:focus {
  border-color: var(--eco-rust);
  box-shadow: 0 0 0 3px var(--eco-rust-tint);
}

.eco-messenger-composer__menus {
  position: absolute;
  right: 12px;
  bottom: calc(100% - 4px);
  left: 12px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  pointer-events: none;
}

.eco-messenger-menu {
  display: grid;
  gap: 4px;
  width: min(260px, 100%);
  padding: 6px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  box-shadow: var(--eco-shadow-pop);
  pointer-events: auto;
}

.eco-messenger-menu.is-quick {
  width: min(360px, 100%);
  margin-left: auto;
}

.eco-messenger-menu button {
  min-height: 30px;
  padding: 7px 9px;
  color: var(--eco-ink-2);
  background: transparent;
  border: 0;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 650;
  text-align: left;
}

.eco-messenger-menu button:hover {
  background: var(--eco-hover);
}

.eco-messenger-menu button strong,
.eco-messenger-menu button small {
  display: block;
}

.eco-messenger-menu button small {
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.25;
}

.eco-messenger-mock-notice {
  margin-bottom: 8px;
  padding: 8px 10px;
  color: var(--eco-warning);
  background: var(--eco-warning-tint);
  border: 1px solid #fde68a;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

.eco-messenger-state {
  display: grid;
  gap: 5px;
  margin: 12px;
  padding: 28px 18px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px dashed var(--eco-line-strong);
  border-radius: 8px;
  text-align: center;
}

.eco-messenger-state strong {
  color: var(--eco-ink-2);
  font-size: 14px;
}

.eco-messenger-state.is-danger strong {
  color: var(--eco-danger);
}

.eco-messenger-toast {
  position: fixed;
  right: 24px;
  bottom: 88px;
  z-index: 100;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: 320px;
  max-width: calc(100vw - 32px);
  padding: 12px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  box-shadow: var(--eco-shadow-pop);
  text-align: left;
}

.eco-messenger-toast.is-widget-open {
  bottom: min(82vh, 760px);
}

.eco-messenger-toast span:not(.eco-messenger-toast__dot) {
  display: grid;
  gap: 2px;
  flex: 1;
}

.eco-messenger-toast small {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-messenger-toast__dot {
  width: 10px;
  height: 10px;
  background: var(--eco-rust);
  border-radius: 999px;
}

.eco-messenger-page {
  max-width: none;
  padding-right: 24px;
  padding-left: 24px;
}

.eco-messenger-page-head {
  margin-bottom: 14px;
}

.eco-messenger-page-head .eco-page-kicker a {
  color: var(--eco-muted);
  text-decoration: none;
}

.eco-messenger-channel-strip {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 0 0 10px;
  scrollbar-width: none;
}

.eco-messenger-channel-strip::-webkit-scrollbar {
  display: none;
}

.eco-messenger-channel-strip span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  padding: 0 9px;
  color: var(--channel);
  background: var(--channel-bg);
  border: 1px solid color-mix(in srgb, var(--channel) 24%, transparent);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 750;
  white-space: nowrap;
}

.eco-messenger-channel-strip span.is-muted {
  color: var(--eco-muted);
  background: var(--eco-surface-sunk);
  border-color: var(--eco-line);
}

.eco-messenger-layout {
  display: grid;
  grid-template-columns: minmax(300px, 360px) minmax(420px, 1fr) minmax(300px, 360px);
  height: calc(100vh - var(--eco-topbar-h) - var(--eco-substrip-h) - 196px);
  min-height: 620px;
  overflow: hidden;
  background: var(--eco-surface);
  border: 1px solid rgba(226, 232, 240, 0.9);
  border-radius: 8px;
}

.eco-messenger-layout__inbox,
.eco-messenger-layout__thread,
.eco-messenger-context {
  min-width: 0;
  min-height: 0;
}

.eco-messenger-layout__inbox {
  border-right: 1px solid var(--eco-line);
}

.eco-messenger-layout__thread {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--eco-bg);
}

.eco-messenger-context {
  overflow-y: auto;
  padding: 12px;
  background: var(--eco-surface);
  border-left: 1px solid var(--eco-line);
}

.eco-messenger-context__section,
.eco-messenger-context-card {
  margin-bottom: 10px;
  padding: 12px;
  background: var(--eco-surface);
  border: 1px solid rgba(226, 232, 240, 0.9);
  border-radius: 8px;
}

.eco-messenger-context__section p {
  margin: 6px 0 0;
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.38;
}

.eco-messenger-context__title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.eco-messenger-dl {
  display: grid;
  gap: 8px;
  margin: 12px 0 0;
}

.eco-messenger-dl div,
.eco-messenger-context-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.eco-messenger-dl dt {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-messenger-dl dd {
  margin: 0;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 700;
  text-align: right;
}

.eco-messenger-context-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
}

.eco-messenger-context-card.is-danger {
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-messenger-context-card span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.eco-messenger-context-card small,
.eco-messenger-context-row small {
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-messenger-context-card strong,
.eco-messenger-context-row strong {
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-messenger-context-card em,
.eco-messenger-context-row em {
  color: var(--eco-muted);
  font-size: 11px;
  font-style: normal;
}

.eco-messenger-context-card b {
  grid-column: 2;
  color: var(--eco-rust);
  font-size: 12px;
}

.eco-messenger-context-row {
  padding: 9px 0;
  border-top: 1px solid var(--eco-line);
}

.eco-messenger-context-row:first-of-type {
  border-top: 0;
}

.eco-messenger-context-row span {
  display: grid;
  gap: 2px;
  flex: 1;
}

.eco-messenger-context__actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
  margin-top: 9px;
}

.eco-messenger-context__notice {
  margin-top: 8px;
  padding: 8px 9px;
  color: var(--eco-rust-strong);
  background: var(--eco-rust-tint);
  border: 1px solid color-mix(in srgb, var(--eco-rust) 24%, transparent);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
}

.eco-messenger-context__actions button {
  min-height: 34px;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  text-align: left;
}

.eco-messenger-context__actions button:hover {
  background: var(--eco-hover);
}

.eco-messenger-context__actions button:disabled {
  cursor: not-allowed;
  color: var(--eco-muted);
  background: var(--eco-bg-soft);
  opacity: 0.7;
}

.eco-messenger-context__header {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin: -12px -12px 10px;
  padding: 12px;
  background: color-mix(in srgb, var(--eco-surface) 92%, transparent);
  border-bottom: 1px solid var(--eco-line);
  backdrop-filter: blur(10px);
}

.eco-messenger-context__identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.eco-messenger-context__identity > span:last-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.eco-messenger-context__identity strong {
  overflow: hidden;
  color: var(--eco-ink);
  font-size: 14px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.eco-messenger-context__identity small,
.eco-messenger-context__badge,
.eco-messenger-context__subhead {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 750;
}

.eco-messenger-context__avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 850;
}

.eco-messenger-context__badge {
  flex: 0 0 auto;
  padding: 5px 7px;
  color: var(--eco-rust-strong);
  background: var(--eco-rust-tint);
  border: 1px solid color-mix(in srgb, var(--eco-rust) 20%, transparent);
  border-radius: 999px;
}

.eco-messenger-context__body {
  display: grid;
  gap: 9px;
  margin-top: 10px;
}

.eco-messenger-context__main-value {
  display: block;
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-messenger-context__inline-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  color: var(--eco-rust-strong);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.eco-messenger-context__warning,
.eco-messenger-context__empty {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 8px;
  padding: 8px 9px;
  color: var(--eco-muted);
  background: var(--eco-bg-soft);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  font-size: 12px;
  line-height: 1.35;
}

.eco-messenger-context__warning {
  color: #92400e;
  background: #fffbeb;
  border-color: #fde68a;
}

.eco-messenger-context__empty {
  display: grid;
  gap: 3px;
}

.eco-messenger-context__empty strong {
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-messenger-context__subhead {
  justify-content: space-between;
  margin: 12px 0 7px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.eco-messenger-context__notice.is-error,
.eco-messenger-client-card b {
  color: var(--eco-danger);
  background: var(--eco-danger-tint);
  border-color: #fecaca;
}

.eco-messenger-suggestions {
  margin-top: 4px;
}

.eco-messenger-client-card,
.eco-messenger-client-result,
.eco-messenger-client-confirm {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px;
  background: var(--eco-bg);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-messenger-client-card + .eco-messenger-client-card,
.eco-messenger-client-result + .eco-messenger-client-result {
  margin-top: 7px;
}

.eco-messenger-client-card > div:first-child,
.eco-messenger-client-result span {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.eco-messenger-client-card strong,
.eco-messenger-client-result strong {
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 800;
}

.eco-messenger-client-card small,
.eco-messenger-client-result small,
.eco-messenger-client-card em,
.eco-messenger-client-result em {
  color: var(--eco-muted);
  font-size: 11px;
  font-style: normal;
}

.eco-messenger-client-card b {
  padding: 5px 6px;
  border: 1px solid;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 750;
}

.eco-messenger-client-card__actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.eco-messenger-client-card__actions a,
.eco-messenger-client-card__actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 0 8px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

.eco-messenger-context-row {
  color: inherit;
  text-decoration: none;
}

.eco-messenger-context-row.is-danger {
  color: var(--eco-danger);
}

.eco-messenger-context-row:hover {
  background: var(--eco-hover);
}

.eco-messenger-context__action-group {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.eco-messenger-context__action-group > span {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.eco-messenger-context__actions a,
.eco-messenger-context__actions button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  min-height: 34px;
  text-decoration: none;
}

.eco-messenger-context__actions a {
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

.eco-messenger-context__actions a:hover,
.eco-messenger-context__actions button:hover {
  background: var(--eco-hover);
}

.eco-messenger-context__actions .is-primary,
.eco-messenger-context-modal__footer .is-primary {
  color: #fff;
  background: var(--eco-rust);
  border-color: var(--eco-rust);
}

.eco-messenger-context-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 96;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.44);
}

.eco-messenger-context-modal {
  width: min(680px, calc(100vw - 32px));
  max-height: min(760px, calc(100vh - 40px));
  overflow: auto;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 8px;
  box-shadow: 0 24px 72px rgba(15, 23, 42, 0.24);
}

.eco-messenger-context-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 16px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-messenger-context-modal__head small {
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 750;
}

.eco-messenger-context-modal__head h3 {
  margin: 3px 0 0;
  color: var(--eco-ink);
  font-size: 20px;
}

.eco-messenger-context-modal__head button {
