  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  color: var(--eco-muted);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
}

.eco-messenger-context-modal__tabs {
