  gap: 8px;
  padding: 12px 16px 0;
}

.eco-messenger-context-modal__tabs button,
.eco-messenger-context-modal__footer button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  color: var(--eco-ink);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 800;
}

.eco-messenger-context-modal__tabs button.is-active {
  color: var(--eco-rust-strong);
  background: var(--eco-rust-tint);
  border-color: color-mix(in srgb, var(--eco-rust) 28%, transparent);
}

.eco-messenger-client-search,
.eco-messenger-client-form {
  display: grid;
  gap: 12px;
  padding: 16px;
}

.eco-messenger-context-field {
  display: grid;
  gap: 6px;
}

.eco-messenger-context-field span {
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.eco-messenger-context-field input,
.eco-messenger-context-field select,
.eco-messenger-context-field textarea {
  width: 100%;
  min-height: 36px;
  padding: 0 10px;
  color: var(--eco-ink);
  background: var(--eco-bg);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 13px;
}

.eco-messenger-context-field textarea {
  min-height: 82px;
  padding: 9px 10px;
  resize: vertical;
}

.eco-messenger-client-results {
  display: grid;
  gap: 0;
  min-height: 120px;
}

.eco-messenger-client-result {
  width: 100%;
  color: inherit;
  text-align: left;
}

.eco-messenger-client-result.is-selected {
  border-color: color-mix(in srgb, var(--eco-rust) 42%, transparent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--eco-rust) 14%, transparent);
}

.eco-messenger-client-result b {
  align-self: flex-start;
  padding: 4px 6px;
  color: var(--eco-muted);
  background: var(--eco-bg-soft);
  border-radius: 999px;
  font-size: 10px;
}

.eco-messenger-client-confirm {
  align-items: center;
  color: var(--eco-rust-strong);
  background: var(--eco-rust-tint);
  border-color: color-mix(in srgb, var(--eco-rust) 24%, transparent);
}

.eco-messenger-client-confirm span {
  flex: 1;
  font-size: 12px;
  line-height: 1.4;
}

.eco-messenger-client-confirm button {
  min-height: 32px;
  padding: 0 10px;
  color: #fff;
  background: var(--eco-rust);
  border: 1px solid var(--eco-rust);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 800;
}

.eco-messenger-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.eco-messenger-context-field.is-wide {
  grid-column: 1 / -1;
}

.eco-messenger-context-modal__footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 2px;
}

.eco-diagnostic-telegram-status {
  display: grid;
  gap: 10px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-diagnostic-telegram-status.is-ok {
  color: var(--eco-success);
  background: var(--eco-success-tint);
  border-color: color-mix(in srgb, var(--eco-success) 26%, transparent);
}

.eco-diagnostic-telegram-status.is-warn {
  color: var(--eco-ink);
  background: var(--eco-warning-tint);
  border-color: #fde68a;
}

.eco-diagnostic-telegram-status strong {
  color: inherit;
  font-size: 13px;
}

.eco-diagnostic-telegram-status img {
  width: 128px;
  height: 128px;
  background: #fff;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-diagnostic-telegram-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-diagnostic-telegram-actions button {
  min-height: 32px;
  padding: 0 10px;
  color: var(--eco-ink-2);
  background: var(--eco-surface);
  border: 1px solid var(--eco-line-strong);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
}

.eco-diagnostic-telegram-actions button:disabled,
.diag-archive-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.eco-messenger-gateway {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 16px;
  margin-top: 16px;
  padding: 14px;
  background: var(--eco-surface);
  border: 1px solid var(--eco-line);
  border-radius: 8px;
}

.eco-messenger-gateway > div:first-child {
  display: grid;
  gap: 4px;
}

.eco-messenger-gateway span {
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.4;
}

.eco-messenger-gateway > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-messenger-gateway code {
  padding: 4px 7px;
  color: var(--eco-ink-2);
  background: var(--eco-surface-sunk);
  border: 1px solid var(--eco-line);
  border-radius: 4px;
  font-size: 11px;
}

.eco-messenger-dev-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.eco-messenger-dev-controls label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--eco-muted);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eco-messenger-dev-controls select {
  border-radius: 4px;
}

.eco-messenger-empty-selection {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  min-height: 100%;
  padding: 32px;
  color: var(--eco-muted);
  text-align: center;
}

.eco-messenger-empty-selection svg {
  width: 48px;
  height: 48px;
  color: var(--eco-rust);
}

.eco-messenger-empty-selection strong {
  color: var(--eco-ink);
  font-size: 18px;
}

.eco-messenger-integrations-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
  gap: 16px;
  align-items: start;
}

.eco-integration-channel-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin: 16px 0;
}

.eco-integration-channel-card {
  display: grid;
  gap: 12px;
}

.eco-integration-channel-card__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
}

.eco-integration-channel-card__mark {
  width: 9px;
  min-height: 42px;
  border-radius: 999px;
}

.eco-integration-channel-card__head strong,
.eco-integration-channel-card__head small,
.eco-integration-channel-card p {
  display: block;
}

.eco-integration-channel-card__head strong {
  font-size: 15px;
  line-height: 1.2;
  color: var(--eco-ink);
}

.eco-integration-channel-card__head small,
.eco-integration-channel-card p,
.eco-integration-channel-card__meta {
  font-size: 12px;
  line-height: 1.35;
  color: var(--eco-muted);
}

.eco-integration-channel-card p {
  margin: 0;
}

.eco-integration-channel-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-integration-channel-card__meta span {
  border: 1px solid rgba(68, 64, 58, 0.16);
  border-radius: 6px;
  padding: 3px 7px;
  background: #fffaf2;
}

.eco-messenger-telegram-card {
  grid-row: span 3;
}

.eco-integration-hero {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  margin-bottom: 14px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface-soft);
}

.eco-integration-hero__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  color: #fff;
  background: #229ed9;
  border-radius: 6px;
}

.eco-integration-hero strong,
.eco-integration-hero span {
  display: block;
}

.eco-integration-hero strong {
  color: var(--eco-ink);
  font-size: 16px;
}

.eco-integration-hero span {
  margin-top: 3px;
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.4;
}

.eco-integration-status-rows {
  display: grid;
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-line);
}

.eco-integration-status-row {
  display: grid;
  grid-template-columns: minmax(120px, 0.35fr) minmax(0, 0.65fr);
  gap: 12px;
  align-items: start;
  padding: 10px 12px;
  background: var(--eco-surface);
}

.eco-integration-status-row span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-integration-status-row strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--eco-ink);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.45;
}

.eco-messenger-settings-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.eco-telegram-settings-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
  padding: 12px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface-soft);
}

.eco-telegram-settings-form label:not(.eco-check-row) {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.eco-telegram-settings-form label:not(.eco-check-row) span {
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-telegram-settings-form .eco-check-row,
.eco-telegram-settings-form .eco-btn {
  align-self: end;
}

.eco-telegram-settings-form .eco-btn {
  justify-content: center;
}

.eco-integration-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 10px 12px;
  margin-top: 10px;
  color: var(--eco-ink-2);
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface-soft);
  font-size: 12px;
  line-height: 1.45;
}

.eco-integration-note svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.eco-integration-note--warning {
  color: #92400e;
  border-color: rgba(245, 158, 11, 0.28);
  background: rgba(245, 158, 11, 0.09);
}

.eco-integration-note--info {
  color: #075985;
  border-color: rgba(14, 165, 233, 0.28);
  background: rgba(14, 165, 233, 0.08);
}

.eco-integration-note--success {
  color: #166534;
  border-color: rgba(34, 197, 94, 0.24);
  background: rgba(34, 197, 94, 0.08);
}

.eco-integration-note--danger {
  color: #991b1b;
  border-color: rgba(220, 38, 38, 0.24);
  background: rgba(220, 38, 38, 0.08);
}

.eco-telegram-settings-form .eco-integration-note {
  grid-column: 1 / -1;
  margin-top: 0;
}

.eco-telegram-qr-panel {
  display: grid;
  grid-template-columns: 184px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  padding: 14px;
  margin-top: 14px;
  border: 1px solid rgba(14, 165, 233, 0.28);
  border-radius: 6px;
  background: rgba(14, 165, 233, 0.06);
}

.eco-telegram-qr-panel__image {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 184px;
  padding: 10px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: #fff;
}

.eco-telegram-qr-panel__image img {
  width: 160px;
  height: 160px;
  object-fit: contain;
}

.eco-telegram-qr-panel__body {
  min-width: 0;
}

.eco-telegram-qr-panel__body h3 {
  margin: 2px 0 8px;
  color: var(--eco-ink);
  font-size: 16px;
  line-height: 1.25;
}

.eco-telegram-qr-panel__body p,
.eco-telegram-qr-panel__body small {
  display: block;
  margin: 0 0 8px;
  color: var(--eco-muted);
  font-size: 12px;
  line-height: 1.45;
}

.eco-telegram-qr-panel__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 10px 0 8px;
}

.eco-integration-channel-list {
  display: grid;
  gap: 8px;
}

.eco-integration-channel {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 50px;
  padding: 10px 12px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface);
}

.eco-integration-channel__mark {
  width: 10px;
  height: 32px;
  border-radius: 4px;
}

.eco-integration-channel strong,
.eco-integration-channel small {
  display: block;
}

.eco-integration-channel strong {
  color: var(--eco-ink);
  font-size: 13px;
}

.eco-integration-channel small {
  margin-top: 2px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-integration-log-list {
  display: grid;
  gap: 8px;
}

.eco-integration-log {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px 10px;
  align-items: start;
  padding: 10px 12px;
  border: 1px solid var(--eco-line);
  border-radius: 6px;
  background: var(--eco-surface);
}

.eco-integration-log strong,
.eco-integration-log small {
  display: block;
}

.eco-integration-log strong {
  color: var(--eco-ink);
  font-size: 12px;
}

.eco-integration-log small {
  margin-top: 2px;
  color: var(--eco-muted);
  font-size: 11px;
}

.eco-integration-log p {
  grid-column: 1 / -1;
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--eco-ink-2);
  font-size: 12px;
  line-height: 1.45;
}

.eco-messenger-endpoints.eco-action-list {
  padding: 0;
}

.eco-messenger-mobile-back {
  display: none;
}

@media print {
  .eco-messenger-widget,
  .eco-messenger-toast,
  .eco-messenger-topbar {
    display: none !important;
  }
}

@media (max-width: 1180px) {
