  }

  .eco-telegram-settings-form {
    grid-template-columns: 1fr;
  }

  .eco-telegram-qr-panel {
    grid-template-columns: 1fr;
  }

  .eco-telegram-qr-panel__image {
    min-height: 172px;
  }

  .eco-messenger-composer__bar {
    grid-template-columns: 44px 44px minmax(0, 1fr) 44px 44px;
  }

  .eco-messenger-composer__bar button:nth-of-type(4) {
