.eco-crm-deadline-toast__summary {
  display: block;
  min-width: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  text-align: left;
}

.eco-crm-deadline-toast__mobile-later {
  display: none;
}

.eco-crm-deadline-toast__open-short {
  display: none !important;
}

