  }

  .eco-crm-deadline-toast__actions a,
  .eco-crm-deadline-toast__actions button {
    min-height: 32px;
    padding: 0 10px;
  }

  .eco-crm-deadline-toast__actions a:first-child {
    min-width: 84px;
    justify-content: center;
  }

  .eco-crm-deadline-toast__mobile-later {
    display: inline-flex;
  }

  .eco-crm-deadline-toast__open-full {
    display: none !important;
  }

  .eco-crm-deadline-toast__open-short {
    display: inline !important;
  }

  .eco-crm-deadline-toast:not(.is-expanded) .eco-crm-deadline-toast__detail-action {
    display: none;
  }
}

.eco-client-notifications-page {
  gap: 18px;
}

.eco-notification-result {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  background: var(--eco-surface);
  color: var(--eco-text);
}

.eco-notification-result--success {
  border-color: rgba(21, 128, 61, 0.22);
  background: rgba(21, 128, 61, 0.06);
}

.eco-notification-result--warning {
  border-color: rgba(180, 83, 9, 0.24);
  background: rgba(180, 83, 9, 0.07);
}

.eco-notification-result--danger {
  border-color: rgba(220, 38, 38, 0.24);
  background: rgba(220, 38, 38, 0.07);
}

.eco-notification-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 6px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  background: var(--eco-surface);
}

.eco-notification-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 7px;
  color: var(--eco-muted);
  background: transparent;
  font-weight: 700;
  cursor: pointer;
}

.eco-notification-tab.is-active {
  color: var(--eco-text);
  background: var(--eco-bg);
  border-color: var(--eco-line);
}

.eco-notification-loading {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.eco-notification-layout,
.eco-notification-channel-layout,
.eco-notification-template-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.eco-notification-template-layout,
.eco-notification-channel-layout {
  grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.8fr);
}

.eco-notification-events {
  display: grid;
  gap: 10px;
}

.eco-notification-event {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  background: var(--eco-surface);
}

.eco-notification-event__switch button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 7px;
  background: var(--eco-bg);
  color: var(--eco-rust);
  cursor: pointer;
}

.eco-notification-event__head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.eco-notification-event__head strong,
.eco-notification-reminder-add strong,
.eco-notification-variable-panel strong {
  display: block;
  font-size: 15px;
  color: var(--eco-text);
}

.eco-notification-event__head p,
.eco-notification-reminder-add span,
.eco-notification-muted {
  margin: 3px 0 0;
  color: var(--eco-muted);
  font-size: 13px;
}

.eco-notification-rule-list {
  display: grid;
  gap: 8px;
}

.eco-notification-rule {
  display: grid;
  gap: 9px;
  padding: 10px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  background: var(--eco-bg);
}

.eco-notification-rule__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  color: var(--eco-muted);
  font-size: 12px;
}

.eco-notification-rule__controls,
.eco-notification-rule__actions,
.eco-notification-editor-actions,
.eco-notification-row-actions,
.eco-notification-log-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.eco-notification-rule__controls .eco-input {
  min-width: 220px;
}

.eco-notification-inline-field {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  padding: 0 9px;
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  background: var(--eco-surface);
  color: var(--eco-muted);
}

.eco-notification-inline-field input {
  width: 64px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--eco-text);
  font-weight: 700;
}

.eco-notification-check {
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  background: var(--eco-surface);
  color: var(--eco-muted);
  font-weight: 700;
  cursor: pointer;
}

.eco-notification-check.is-on {
  border-color: rgba(21, 128, 61, 0.28);
  color: #166534;
  background: rgba(21, 128, 61, 0.08);
}

.eco-notification-reminder-add {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 120px auto;
  align-items: center;
  gap: 10px;
}

.eco-notification-form-grid,
.eco-notification-channel-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.eco-notification-form-grid label,
.eco-notification-template-editor {
  display: grid;
  gap: 6px;
  color: var(--eco-muted);
  font-size: 12px;
  font-weight: 700;
}

.eco-notification-template-editor {
  margin-top: 12px;
}

.eco-notification-template-editor textarea.eco-input {
  min-height: 230px;
  resize: vertical;
  line-height: 1.45;
}

.eco-notification-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 38px;
  color: var(--eco-text);
  font-weight: 700;
}

.eco-notification-preview {
  display: grid;
  gap: 8px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--eco-line);
  border-radius: 8px;
  background: var(--eco-bg);
}

.eco-notification-preview pre {
  margin: 0;
  white-space: pre-wrap;
  color: var(--eco-text);
  font-family: inherit;
  line-height: 1.45;
}

.eco-notification-variable-panel,
.eco-notification-variable-docs,
.eco-notification-variable-grid {
  display: grid;
  gap: 10px;
}

.eco-notification-variable-panel > div {
  display: grid;
  gap: 8px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--eco-line);
}

.eco-notification-variable-panel > div:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.eco-notification-variable-panel div div,
.eco-notification-variable-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.eco-notification-variable-panel button,
.eco-notification-variable-grid code,
.eco-notification-planned-channels span {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 9px;
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  background: var(--eco-bg);
  color: var(--eco-text);
  font-size: 12px;
  font-weight: 700;
}

.eco-notification-variable-panel button {
  cursor: pointer;
}

.eco-notification-test {
  display: grid;
  gap: 12px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--eco-line);
}

.eco-notification-planned-channels {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.eco-notification-row-actions a,
.eco-notification-row-actions button {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 8px;
  border: 1px solid var(--eco-line);
  border-radius: 7px;
  background: var(--eco-surface);
  color: var(--eco-text);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

@media (max-width: 980px) {
  .eco-notification-template-layout,
  .eco-notification-channel-layout,
  .eco-notification-form-grid,
  .eco-notification-channel-grid,
  .eco-notification-reminder-add {
    grid-template-columns: 1fr;
  }

  .eco-notification-event {
    grid-template-columns: 1fr;
  }

  .eco-notification-event__switch {
    display: none;
  }
}

