    display: inline-flex;
    min-height: 46px;
    align-items: center;
    justify-content: center;
    padding: 0 18px;
    color: #0a0a0a;
    background: #fffaf3;
    border: 1px solid rgba(10, 10, 10, 0.14);
    border-radius: 8px;
    font-size: 14px;
    font-weight: 850;
    text-decoration: none;
    white-space: nowrap;
  }

  .tgm-public-actions a.is-primary,
  .tgm-public-sticky a.is-primary {
    color: #fffaf3;
    background: #c2410c;
    border-color: #c2410c;
  }

  .tgm-client-report.tgm-public-report .tgm-public-footer {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 34px 0 44px;
    color: rgba(245, 242, 237, 0.55);
    background: transparent;
  }

  .tgm-public-footer img {
    width: 32px;
    height: 32px;
    flex: 0 0 auto;
  }

  .tgm-public-footer p {
    max-width: 760px;
    margin: 0;
    font-size: 12px;
    line-height: 1.55;
  }

  .tgm-public-sticky {
    display: none;
  }
}

@media screen and (max-width: 760px) {
  .diag-client-report-page.is-public {
    padding-bottom: calc(82px + env(safe-area-inset-bottom));
  }

  .diag-client-report-page.is-public .tgm-public-report {
    overflow-x: hidden;
  }

  .tgm-public-top,
  .tgm-public-hero,
  .tgm-public-summary,
  .tgm-public-result,
  .tgm-public-section,
  .tgm-public-next,
  .tgm-public-footer {
    width: 100%;
    padding-right: max(16px, env(safe-area-inset-right));
    padding-left: max(16px, env(safe-area-inset-left));
  }

  .tgm-client-report.tgm-public-report .tgm-public-top {
    align-items: flex-start;
    padding-top: 14px;
    padding-bottom: 14px;
    font-size: 13px;
  }

  .tgm-public-top img {
    height: 18px;
  }

  .tgm-client-report.tgm-public-report .tgm-public-hero {
    grid-template-columns: 1fr;
    gap: 20px;
    padding-top: 34px;
    padding-bottom: 28px;
  }

  .tgm-client-report.tgm-public-report .tgm-public-hero h1 {
    font-size: 44px;
    line-height: 1;
  }

  .tgm-public-hero-copy p {
    font-size: 16px;
  }

  .tgm-client-report.tgm-public-report .tgm-car-card {
    display: none;
  }

  .tgm-public-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .tgm-public-facts div {
    padding: 12px;
  }

  .tgm-public-facts dd {
    font-size: 15px;
  }

  .tgm-client-report.tgm-public-report .tgm-public-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding: 0 max(16px, env(safe-area-inset-right)) 20px max(16px, env(safe-area-inset-left));
  }

  .tgm-public-kpi {
    padding: 14px 12px;
  }

  .tgm-public-kpi span {
    font-size: 38px;
  }

  .tgm-public-kpi strong {
    font-size: 12px;
  }

  .tgm-client-report.tgm-public-report .tgm-public-result {
    padding-top: 22px;
    padding-bottom: 22px;
  }

  .tgm-public-result h2,
  .tgm-public-section-head h2,
  .tgm-public-next h2 {
    font-size: 26px;
    line-height: 1.12;
  }

  .tgm-client-report.tgm-public-report .tgm-public-section {
    padding-top: 42px;
  }

  .tgm-public-rec {
    padding: 16px;
  }

  .tgm-public-rec-head {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .tgm-public-rec h3 {
    font-size: 20px;
  }

  .tgm-public-rec-head span {
    justify-self: start;
  }

  .tgm-public-photos {
    grid-template-columns: 1fr;
  }

  .tgm-public-accordion summary {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .tgm-public-accordion summary b {
    white-space: normal;
  }

  .tgm-public-check {
    grid-template-columns: 18px minmax(0, 1fr);
    align-items: flex-start;
    padding: 12px 14px;
  }

  .tgm-public-check-status {
    grid-column: 2;
    justify-self: start;
    white-space: normal;
  }

  .tgm-client-report.tgm-public-report .tgm-public-next {
    grid-template-columns: 1fr;
    gap: 18px;
    margin-top: 42px;
    padding-top: 22px;
    padding-bottom: 22px;
  }

  .tgm-public-actions {
    display: grid;
    grid-template-columns: 1fr;
    justify-content: stretch;
  }

  .tgm-public-actions a {
    width: 100%;
  }

  .tgm-client-report.tgm-public-report .tgm-public-footer {
    align-items: flex-start;
    padding-top: 26px;
    padding-bottom: 24px;
  }

  .tgm-public-sticky {
    position: fixed;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 60;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
    padding: 10px max(12px, env(safe-area-inset-right)) calc(10px + env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));
    background: rgba(10, 10, 10, 0.92);
    border-top: 1px solid rgba(245, 242, 237, 0.12);
    backdrop-filter: blur(14px);
  }

  .tgm-public-sticky a {
    min-width: 0;
    min-height: 44px;
    padding: 0 8px;
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .tgm-client-report.tgm-public-report .tgm-public-hero h1 {
    font-size: 38px;
  }

  .tgm-public-facts,
  .tgm-client-report.tgm-public-report .tgm-public-summary {
    grid-template-columns: 1fr;
  }

  .tgm-public-sticky a {
    font-size: 12px;
  }
}
